/** `iphone-c603 (Peter_Maude_(iPhone))` — for error messages and diagnostics. */
export function describePeer(peer: IdentifiablePeer): string {
  return `${deviceHandleFor(peer)} (${peer.displayName})`;
}

/** The account whose Mac a relay room is, from `machine:<owner>:<machine>`; undefined for any other room. */
export function machineRoomOwner(roomId: string | undefined): string | undefined {
  const [kind, owner] = roomId?.split(':') ?? [];
  return kind === 'machine' && owner ? owner : undefined;
}

/**
 * Whether a connection in a Mac's room may be one of that Mac's owner's
 * devices. A teammate's app joins a shared Mac's room as
 * `controller-<their id>-…` (the relay refuses them any other controller id)
 * and is never the Mac's device. Anything that is not a controller is left to
 * the other rules.
 */
export function isOwnersDevice(clientId: string, ownerUserId: string | undefined): boolean {
  if (!ownerUserId || !clientId.startsWith('controller-')) return true;
  return clientId === `controller-${ownerUserId}` || clientId.startsWith(`controller-${ownerUserId}-`);
}

/**
 * Whether this page serves device tools in a room: only in the room of a Mac
 * on its own account. A teammate's app sits in a shared Mac's room too, and
 * answered that Mac's agents (its screen, its page's script, its browser)
 * without its owner being asked (31 October 2026).
 */
export function servesDeviceToolsIn(roomId: string, selfUserId: string | null | undefined): boolean {
  return !!selfUserId && machineRoomOwner(roomId) === selfUserId;
}

