function toolPeerSnapshot(chatId: string): { peers: Array<{ clientId: string; displayName: string }>; originClientId?: string } {
  return (window as any).__ripulToolPeerSnapshot?.(chatId) ?? { peers: [] };
}

function deviceTargetsFor(chatId: string) {
  const snapshot = toolPeerSnapshot(chatId);
  const live = new Map(snapshot.peers.map(p => [p.clientId, p]));
  // Only the owner's: a teammate's app in a shared Mac's room is not offered (deviceIdentity.ts).
  const owner = hostOwnerUserId();
  return readToolSources<AnnouncedTool>(chatId, 'device').filter(source => isOwnersDevice(source.id, owner)).map(source => {
    const peer = live.get(source.id);
    return { clientId: source.id,
      handle: deviceHandleFor({ clientId: source.id, displayName: source.label ?? '' }),
      label: peer?.displayName ?? source.label ?? source.id,
      available: Boolean(peer), tools: source.tools.map(t => t.name).sort() };
  });
}

async function browserRuntimeOptions(chatId: string): Promise<BrowserTargetOptions> {
  const targets = deviceTargetsFor(chatId);
  const snapshot = toolPeerSnapshot(chatId);
  const origin = targets.find(t => t.clientId === snapshot.originClientId && t.tools.some(isBrowserFamilyTool));
  rememberBrowserOrigin(chatId, origin?.handle);
  const providers = new Map<string, string[]>();
  for (const base of BROWSER_BASE_NAMES) {
    providers.set(`device_${base}`, targets.filter(t => t.available && t.tools.includes(base)).map(t => t.handle));
  }
  const { getNativeBridgeInstance } = await import('../hosted-app/NativeBridge');
  const native = getNativeBridgeInstance();
  const host = native?.isConnected() && !UserSettingsManager.getUserSettings().suppressHostToolsInRemoteChats
    ? native.getDiscoveredTools().map(t => ({ name: `host_${t.name}` })) : [];
  return computeBrowserTargetOptions(host, providers);
}

