2	import { verifyClerkJwt } from '../auth/clerk';
3	import { verifyMachineToken } from '../auth/machineToken';
4	import { validateShareTokenForWs } from './shareTokens';
5	import { ownsMachineRoom, parseMachineRoom } from './roomIdentity';
6	import { actorName, departmentAccess } from './departmentHosts';
7	
8	export const RELAY_GRANT_HEADER = 'x-ripul-relay-grant';
9	export type RelayGrant = {
10	  version: 1;
11	  ownerId: string;
12	  roomId: string;
13	  expiresAt: number;
14	} & (
15	  | { kind: 'user'; actorId?: string; actorName?: string; teamId?: string }
16	  | { kind: 'machine'; machineId: string; jti: string; rented?: boolean }
17	  | { kind: 'share'; token: string }
18	);
