20	/** Resolve identity AND resource permission before any DO lookup or upgrade. */
21	export async function authorizeRelay(request: Request, roomId: string, env: Env): Promise<RelayGrant | null> {
22	  const params = new URL(request.url).searchParams;
23	  const shareToken = params.get('shareToken');
24	  const machineToken = params.get('machineToken');
25	  const token = params.get('token');
26	  // Ambiguous credentials must not silently upgrade a viewing grant.
27	  if ([shareToken, machineToken, token].filter(Boolean).length !== 1) return null;
28	  if (shareToken) {
29	    const entry = await validateShareTokenForWs(shareToken, env);
30	    // Session shares use SessionChannel only: the machine room contains other chats and commands.
31	    if (!entry || entry.roomId !== roomId || entry.scope !== 'relay' || entry.chatId) return null;
32	    return { version: 1, kind: 'share', ownerId: entry.createdBy, roomId, token: shareToken, expiresAt: Date.parse(entry.expiresAt) };
33	  }
34	  if (machineToken) {
35	    const payload = await verifyMachineToken(machineToken, env);
36	    if (!payload || !ownsMachineRoom(roomId, payload.sub)) return null;
37	    // A rented Mac is someone else's hardware: its token opens its own room and no other.
