import type { Env } from '../types';
import { verifyClerkJwt } from '../auth/clerk';
import { verifyMachineToken } from '../auth/machineToken';
import { validateShareTokenForWs } from './shareTokens';
import { ownsMachineRoom, parseMachineRoom } from './roomIdentity';
import { actorName, departmentAccess } from './departmentHosts';

export const RELAY_GRANT_HEADER = 'x-ripul-relay-grant';
export type RelayGrant = {
  version: 1;
  ownerId: string;
  roomId: string;
  expiresAt: number;
} & (
  | { kind: 'user'; actorId?: string; actorName?: string; teamId?: string }
  | { kind: 'machine'; machineId: string; jti: string; rented?: boolean }
  | { kind: 'share'; token: string }
);

/** Resolve identity AND resource permission before any DO lookup or upgrade. */
export async function authorizeRelay(request: Request, roomId: string, env: Env): Promise<RelayGrant | null> {
  const params = new URL(request.url).searchParams;
  const shareToken = params.get('shareToken');
  const machineToken = params.get('machineToken');
  const token = params.get('token');
  // Ambiguous credentials must not silently upgrade a viewing grant.
  if ([shareToken, machineToken, token].filter(Boolean).length !== 1) return null;
  if (shareToken) {
    const entry = await validateShareTokenForWs(shareToken, env);
    // Session shares use SessionChannel only: the machine room contains other chats and commands.
    if (!entry || entry.roomId !== roomId || entry.scope !== 'relay' || entry.chatId) return null;
    return { version: 1, kind: 'share', ownerId: entry.createdBy, roomId, token: shareToken, expiresAt: Date.parse(entry.expiresAt) };
  }
  if (machineToken) {
    const payload = await verifyMachineToken(machineToken, env);
    if (!payload || !ownsMachineRoom(roomId, payload.sub)) return null;
    // A rented Mac is someone else's hardware: its token opens its own room and no other.
    if (payload.rentedUntil !== undefined) {
      if (parseMachineRoom(roomId)?.machineId !== payload.machineId) return null;
      return { version: 1, kind: 'machine', ownerId: payload.sub, roomId, machineId: payload.machineId, jti: payload.jti, expiresAt: payload.exp * 1000, rented: true };
    }
    // A registered machine may control another machine belonging to the SAME owner.
    return { version: 1, kind: 'machine', ownerId: payload.sub, roomId, machineId: payload.machineId, jti: payload.jti, expiresAt: payload.exp * 1000 };
  }
  const user = token ? await verifyClerkJwt(token, env) : null;
  if (!user) return null;
  if (ownsMachineRoom(roomId, user.sub)) {
    return { version: 1, kind: 'user', ownerId: user.sub, actorId: user.sub, roomId, expiresAt: user.exp * 1000 };
  }
  const room = parseMachineRoom(roomId);
  if (!room) return null;
  const access = await departmentAccess(room.ownerId, room.machineId, user.sub, env);
  if (!access) return null;
  return { version: 1, kind: 'user', ownerId: room.ownerId, actorId: user.sub,
    actorName: await actorName(user.sub, env), teamId: access.teamId, roomId, expiresAt: user.exp * 1000 };
}

/**
 * A user grant expires with the Clerk token that opened the socket, and those
 * live 60 seconds. The client re-presents each new token over the open socket
 * (`reauth`); Clerk mints the next one only ~10s before the last expires and
 * the client hands it over on its next heartbeat, so the grant stays current
 * this long past its token's expiry. Without the handover every signed-in
 * phone and browser was closed with 1008 about once a minute.
 */
export const USER_REAUTH_GRACE_MS = 45_000;

export function grantExpiry(grant: RelayGrant): number {
  return grant.kind === 'user' ? grant.expiresAt + USER_REAUTH_GRACE_MS : grant.expiresAt;
}

/** Extend a user grant with a fresh token from the same actor. Anything else leaves it unchanged. */
export async function refreshRelayGrant(grant: RelayGrant, token: string, env: Env): Promise<boolean> {
  if (grant.kind !== 'user') return false;
  const user = await verifyClerkJwt(token, env).catch(() => null);
  if (!user || user.sub !== (grant.actorId ?? grant.ownerId)) return false;
  grant.expiresAt = Math.max(grant.expiresAt, user.exp * 1000);
  return true;
}

/** Recheck live grants. KV revocation is eventually consistent; never allow indefinite sockets. */
export async function relayGrantIsCurrent(grant: RelayGrant, env: Env): Promise<boolean> {
  if (grant.version !== 1 || !Number.isFinite(grant.expiresAt) || grantExpiry(grant) <= Date.now() || !ownsMachineRoom(grant.roomId, grant.ownerId)) return false;
  if (grant.kind === 'user') {
    if (!grant.teamId) return !grant.actorId || grant.actorId === grant.ownerId;
    const room = parseMachineRoom(grant.roomId)!;
    const access = grant.actorId ? await departmentAccess(grant.ownerId, room.machineId, grant.actorId, env) : null;
    return access?.teamId === grant.teamId;
  }
  if (grant.kind === 'share') {
    const entry = await validateShareTokenForWs(grant.token, env);
    return !!entry && entry.roomId === grant.roomId && entry.createdBy === grant.ownerId && entry.scope === 'relay' && !entry.chatId;
  }
  if (grant.kind !== 'machine') return false;
  const stored = await env.RATE_LIMIT_KV.get(`machine-token:${grant.ownerId}:${grant.machineId}`, { type: 'json', cacheTtl: 30 }) as { jti?: string; exp?: number } | null;
  return stored?.jti === grant.jti && typeof stored.exp === 'number' && stored.exp * 1000 > Date.now();
}

