import RipulAgent

enum WACNativeTools {
    /// The END-USER agent's own tools — what a user's agent can do in the app.
    ///
    /// Kept separate from `all` because `all` also carries dev-only theme tools
    /// in debug builds. This is the list that describes the end-user surface,
    /// and it is what the console's Tool Collections editor organises: mixing
    /// dev tools in would blur the one distinction that screen exists to keep
    /// clear.
    static var endUser: [NativeTool] {
        [
            GetWorkplacesTool(),
            PickIndustryTool(),
            PickJobTool(),
            PickLocationTool(),
            PickOptionTool(),
            GetPayslipTool(),
            CreateWorkplaceTool(),
            SetWorkplaceLocationTool(),
            SetupWorkplacePaymentTool(),
            SetupPayslipTaxTool(),
            CreateRotaTool(),
            UpdateRotaTool(),
            DeleteRotaTool(),
            ListShiftsTool(),
            ManageArchivedJobsTool(),
            ConnectGoogleSheetsTool(),
            AddReceiptTool(),
            ListReceiptsTool(),
            ExportReceiptsTool(),
            ShowReceiptsTool(),
            SetOvertimeRuleTool(),
            ApproveShiftsTool(),
        ]
    }

    /// WAC's ONE tool registry (native-tool-registry phase 1): every native
    /// tool registered once, tagged by audience. The end-user agent panel
    /// (`AgentView(registry:)`) exposes the `.endUser` entries; the dev
    /// console overlay (`RipulDevConsoleConfig`) exposes the `.developer`
    /// entries; the Tool Collections editor reads the same registry for both
    /// surfaces. Theme dev tools are `.developer`-tagged — they no longer ride
    /// the panel's list at all (the SDK gated them there anyway).
    static let registry: RipulToolRegistry = {
        let registry = RipulToolRegistry()
        registry.register(endUser, audience: .endUser)
        // Developer tools: the SDK's theme tools plus WAC's headless payslip sandbox
        // (NativeTools/Tools/PayslipSandboxTool.swift). One register call so neither
        // set can clobber the other. Present only where the debug hub itself is.
        #if WAC_DEVELOPER_TOOLS
        let sandboxTools: [NativeTool] = ConfigurationHelper.debugToolsEnabled
            ? [PayslipSandboxRunTool(), PayslipSandboxSweepTool(), PayrollFunctionalTestTool(), FunctionalTestSuiteTool(),
               ThemeServerTool(), HubStyleTool(), OpenScreenTool(), ElementStyleTool(), HomeCardsTool(), DrivingModeTool(),
               BackendEndpointTool(), SimulateFailureTool(),
               WACAppStateTool(), WACDevSignInTool(), WACShiftEditorTool(), WACViewPayslipTool(), WACJobSetupTool()] : []
        #else
        let sandboxTools: [NativeTool] = []
        #endif
        registry.register(
            RipulDevThemeTools.all(isEnabled: { ConfigurationHelper.debugToolsEnabled }) + sandboxTools,
            audience: .developer
        )
        return registry
    }()
}

