struct ThemeServerTool: NativeTool {
    let name = "theme_server"
    let description = """
    DEVELOPER. Inspect and manage the published app theme (wac-v1), which every phone runs in \
    preference to the theme shipped in the build. action=status: the running source, remote origin \
    and version, local override, sign-in, and hubRowShowsCard as running / shipped / server. \
    action=diff: every path where the server document differs from the shipped Theme.json (0 = in \
    lockstep; jobKindCatalogue is excluded — it has its own publication flow). \
    action=local_diff: this phone's UNPUBLISHED editor edits versus the server version they were \
    taken from — what the person changed locally, path by path. \
    action=discard_local: drop those local edits and run the server theme again. \
    action=publish_shipped (dry_run to preview): make the server theme EQUAL the build's shipped \
    Theme.json (jobKindCatalogue kept as on the server), schema-validated, conditional on the version \
    read — keeps source and online in lockstep; affects EVERY phone following wac-v1. \
    action=publish_setting (key, value_json; dry_run to preview): changes ONE top-level key of the \
    LIVE server document, keeping everything else, validated against WAC's schema, conditional on \
    the version read (a concurrent publish is refused), then adopted on this phone — affects EVERY \
    phone following wac-v1; signs in with the WAC login (a WAC App site designer) or the Ripul assistant. action=use_shipped: \
    this phone runs the shipped defaults (persists across relaunch; server untouched). \
    action=follow_server: back to the server theme, checking for a newer version.
    """
    let inputSchema = ToolSchema.object(
        .string("action", "status | diff | local_diff | discard_local | publish_setting | publish_shipped | use_shipped | follow_server; default status"),
        .string("key", "publish_setting: top-level theme key, e.g. hubRowShowsCard"),
        .string("value_json", "publish_setting: the new value as JSON, e.g. true, \"card\", {\"a\":1}"),
        .bool("dry_run", "publish_setting / publish_shipped: report the change without publishing (default false)")
    )
    let outputSchema: [String: Any]? = nil
    let timeout: TimeInterval = 30

    @MainActor
    func execute(args: [String: Any]) async throws -> Any {
        switch args["action"] as? String ?? "status" {
        case "status":
            var result = ThemeProvider.themeDiagnostics
            result["serverStatus"] = await WACServerTheme.refreshStatus().summary
            return result
        case "diff":
            let diff = try await WACServerTheme.diffAgainstShipped()
            return ["serverVersion": diff.etag ?? "", "differences": diff.entries, "count": diff.entries.count] as [String: Any]
        case "publish_setting":
            guard let key = args["key"] as? String, !key.isEmpty else { throw ThemeToolError("publish_setting requires key") }
            guard let raw = args["value_json"] as? String,
                  let value = try? JSONSerialization.jsonObject(with: Data(raw.utf8), options: [.fragmentsAllowed]) else {
                throw ThemeToolError("publish_setting requires value_json (valid JSON)")
            }
            if args["dry_run"] as? Bool == true {
                return try await WACServerTheme.previewChange(setting: key, to: value)
            }
            try await WACServerTheme.publish(setting: key, to: value)
            var result = ThemeProvider.themeDiagnostics
            result["published"] = ["key": key, "value": value]
            return result
        case "local_diff":
            return try WACServerTheme.localDiff()
        case "discard_local":
            ThemeProvider.resetToAuthoritativeTheme()
            var result = ThemeProvider.themeDiagnostics
            result["localEditsRemaining"] = try WACServerTheme.localDiff()["count"] ?? 0
            return result
        case "publish_shipped":
            if args["dry_run"] as? Bool == true {
                return try await WACServerTheme.previewShippedPublish()
            }
            try await WACServerTheme.publishShipped()
            let drift = try await WACServerTheme.diffAgainstShipped()
            var result = ThemeProvider.themeDiagnostics
            result["lockstepDifferences"] = drift.entries
            result["serverVersion"] = drift.etag ?? ""
            return result
        case "use_shipped":
            try ThemeProvider.useShippedTheme()
            return ThemeProvider.themeDiagnostics
        case "follow_server":
            ThemeProvider.resetToAuthoritativeTheme()
            return ThemeProvider.themeDiagnostics
        default:
            throw ThemeToolError("Unknown action")
        }
    }
}

