/** On an owner's subscribe: say who is offering, when anyone is. */
greet(sub: S, chatId: string, ownerId: string): void {
  if (isOwnerParty(sub, ownerId) && offeredPeers(this.subscribers(), ownerId).length) this.announce(chatId, ownerId, sub);
}

offer(sub: S, message: SessionBrowserOfferMessage, ctx: { chatId: string; ownerId: string }): void {
  const refuse = (text: string) => this.send(sub, { type: 'session.error', chatId: ctx.chatId, code: 'unauthorized', message: text });
  if (message.chatId !== ctx.chatId) return refuse('Wrong chat');
  if (!isMemberParty(sub, ctx.ownerId)) return refuse('Only someone invited to this chat, or a teammate in a team chat, can offer their browser to it.');
  if (message.enabled === true) {
    const tools = Array.isArray(message.tools)
      ? [...new Set(message.tools.filter((t): t is string => typeof t === 'string' && TOOLS.has(t)))].sort() : [];
    if (!tools.length) return refuse('This device has no browser to offer.');
    sub.browserOffer = { tools, ...(typeof message.label === 'string' && message.label.trim()
      ? { label: message.label.trim().slice(0, 120) } : {}) };
  } else {
    this.withdraw(sub, ctx.chatId, ctx.ownerId, 'They stopped sharing their browser.', false);
  }
  this.send(sub, { type: 'session.browserOffer', chatId: ctx.chatId, enabled: !!sub.browserOffer,
    ...(message.requestId ? { requestId: message.requestId } : {}) });
  this.announce(ctx.chatId, ctx.ownerId);
}

/** The offer ends: on the member's word, when their socket closes, or when their membership does. */
withdraw(sub: S, chatId: string, ownerId: string, reason: string, announce = true): void {
  const had = !!sub.browserOffer;
  sub.browserOffer = undefined;
  for (const [requestId, entry] of this.pending) {
    if (entry.target !== sub.clientId) continue;
    this.finish(requestId, { type: 'session.browserResult', chatId, requestId, error: reason });
  }
  if (had && announce) this.announce(chatId, ownerId);
}

/** A connection has gone: an owner's waiting queries go with it. */
dropRequester(sub: S): void {
  for (const [requestId, entry] of this.pending) {
    if (entry.requester !== sub.clientId) continue;
    clearTimeout(entry.timer);
    this.pending.delete(requestId);
  }
}

query(sub: S, message: SessionBrowserQueryMessage, ctx: { chatId: string; ownerId: string }): void {
  const requestId = typeof message.requestId === 'string' ? message.requestId.slice(0, 128) : '';
  const fail = (error: string) => this.send(sub, { type: 'session.browserResult', chatId: ctx.chatId, requestId, error });
  if (!requestId || message.chatId !== ctx.chatId || !isOwnerParty(sub, ctx.ownerId)) {
    this.send(sub, { type: 'session.error', chatId: ctx.chatId, code: 'unauthorized',
      message: 'Only the chat owner\'s host can use a member\'s browser.' });
    return;
  }
  if (this.pending.has(requestId)) return fail('That request is already waiting.');
  if (!TOOLS.has(message.toolName)) return fail('That is not a browser operation a member can offer.');
  const args = message.args && typeof message.args === 'object' && !Array.isArray(message.args) ? message.args : {};
  if (JSON.stringify(args).length > MAX_ARGS_BYTES) return fail('The request is too large.');
  const candidates = [...this.subscribers()].filter(s => s.browserOffer && isMemberParty(s, ctx.ownerId)
