/**
 * SupportRoom — one support session, between a customer's app and the person helping.
 *
 * A customer of an app built with the SDK asks for help; the app gets a short
 * code and shows it. The supporter, signed in to Ripul and allowed to support
 * that app's site key, enters the code. Both ends then hold a WebSocket to
 * this room, which passes Live View's frames between them: the app's picture
 * one way, where the supporter is pointing the other.
 *
 * The room is named by the code, and keeps the session in its own storage, so
 * a code made a second ago is there for whoever enters it next, wherever they
 * are (KV would take up to a minute to say so).
 *
 * What crosses is `LiveStreamWire` (ripul-ios-sdk): [kind: 1 byte][length:
 * 4 bytes, big-endian][payload], one frame per binary message. The room reads
 * only the kind. It passes on the kinds a support session has a use for and
 * drops the rest, so a supporter can point but can't touch, type or run
 * commands, whatever the app at the other end was built to accept.
 *
 * Reached only through `handlers.ts`, which checks the site key or the
 * sign-in before any request gets here.
 */

import type { Env } from '../types';

export type SupportRole = 'customer' | 'supporter';

/** An unclaimed code is forgotten after this long. */
export const SUPPORT_CODE_LIFETIME_MS = 10 * 60_000;
/** From the moment a supporter takes the code, the session may run this long. */
export const SUPPORT_SESSION_LIFETIME_MS = 60 * 60_000;
/** The largest frame passed on: a keyframe of a phone's screen is a tenth of this. */
    const other: SupportRole = role === 'customer' ? 'supporter' : 'customer';

    server.addEventListener('message', (event) => {
      if (this.sockets[role] !== server || typeof event.data === 'string') return;
      const bytes = event.data as ArrayBuffer;
      if (bytes.byteLength < 5 || bytes.byteLength > SUPPORT_MAX_FRAME_BYTES) return;
      const kind = new Uint8Array(bytes, 0, 1)[0];
      if (!PASSED[role].has(kind)) return;
      try { this.sockets[other]?.send(bytes); } catch { /* the other end is going; its close follows */ }
      if (kind === KIND.bye) {
        // Either end saying goodbye is the end of the session: the code is spent.
        void this.end(role === 'customer' ? 'The customer stopped sharing' : 'The supporter left', role);
      }
    });
    const gone = () => {
      if (this.sockets[role] !== server) return;
      delete this.sockets[role];
      this.say(this.sockets[other], { event: 'peer', role, present: false });
    };
    server.addEventListener('close', gone);
    server.addEventListener('error', gone);

    // Each end is told who else is here; the customer's app asks before it shows anything.
    const supporter = session.supporter ? { name: session.supporter.name, who: session.supporter.who } : {};
    this.say(server, {
      event: 'peer', role: other, present: !!this.sockets[other],
      ...(other === 'supporter' ? supporter : {}),
      expiresAt: session.expiresAt,
    });
    this.say(this.sockets[other], {
      event: 'peer', role, present: true,
      ...(role === 'supporter' ? supporter : {}),
      expiresAt: session.expiresAt,
    });

    return new Response(null, { status: 101, webSocket: client });
  }

  private say(socket: WebSocket | undefined, message: Record<string, unknown>): void {
    try { socket?.send(roomFrame(message)); } catch { /* already closed */ }
  }
