      if (bytes.byteLength < 5 || bytes.byteLength > SUPPORT_MAX_FRAME_BYTES) return;
      const kind = new Uint8Array(bytes, 0, 1)[0];
      if (!PASSED[role].has(kind)) return;
      try { this.sockets[other]?.send(bytes); } catch { /* the other end is going; its close follows */ }
      if (kind === KIND.bye) {
        // Either end saying goodbye is the end of the session: the code is spent.
        void this.end(role === 'customer' ? 'The customer stopped sharing' : 'The supporter left', role);
      }
    });
    const gone = () => {
      if (this.sockets[role] !== server) return;
      delete this.sockets[role];
      this.say(this.sockets[other], { event: 'peer', role, present: false });
    };
    server.addEventListener('close', gone);
    server.addEventListener('error', gone);

    // Each end is told who else is here; the customer's app asks before it shows anything.
    const supporter = session.supporter ? { name: session.supporter.name, who: session.supporter.who } : {};
    this.say(server, {
      event: 'peer', role: other, present: !!this.sockets[other],
      ...(other === 'supporter' ? supporter : {}),
      expiresAt: session.expiresAt,
    });
    this.say(this.sockets[other], {
      event: 'peer', role, present: true,
      ...(role === 'supporter' ? supporter : {}),
      expiresAt: session.expiresAt,
    });

    return new Response(null, { status: 101, webSocket: client });
  }

  private say(socket: WebSocket | undefined, message: Record<string, unknown>): void {
    try { socket?.send(roomFrame(message)); } catch { /* already closed */ }
  }
