/**
 * An invited member's own browser, offered to the agent of a chat they were
 * invited to. The server half is packages/api/src/sessionChannel/memberBrowser.ts.
 *
 * Two sides share this file:
 *
 *  - **The member's device.** Nothing is offered until the member says so, per
 *    chat and per device (the choice is kept on the device). While it is on,
 *    this device answers the five browser operations and nothing else.
 *  - **The owner's host.** It learns who is offering, and sends an operation to
 *    one member's browser. It is used only in a turn that member asked for.
 */
import type { SessionBrowserFrame, SessionChannelClient } from './SessionChannelClient';
import { MEMBER_BROWSER_TOOLS, type SessionBrowserPeer } from './sessionChannelTypes';

const TOOLS: ReadonlySet<string> = new Set(MEMBER_BROWSER_TOOLS);
const CONSENT_KEY = 'ripul.memberBrowser.shared.v1';
/** Longer than the server's own wait, so its answer (or its timeout) is the one that lands. */
const QUERY_WAIT_MS = 58_000;

export interface MemberBrowserDeps {
  /** The browser operations this device can run now. */
  tools(): Promise<string[]>;
  invoke(toolName: string, args: Record<string, unknown>): Promise<unknown>;
  label(): string;
}

let client: SessionChannelClient | undefined;
let deps: MemberBrowserDeps | undefined;
const peersByChat = new Map<string, SessionBrowserPeer[]>();
const waiting = new Map<string, { resolve: (r: { result?: unknown; error?: string }) => void; timer: ReturnType<typeof setTimeout> }>();
const offered = new Set<string>();
const listeners = new Set<() => void>();

// ── The member's choice ─────────────────────────────────────────────────────

function readConsent(): Record<string, number> {
  try { return JSON.parse(globalThis.localStorage?.getItem(CONSENT_KEY) || '{}') ?? {}; } catch { return {}; }
}

/** Whether this device shares its browser with this chat's agent. The member's own choice, kept on this device. */
export function isSharingBrowser(chatId: string): boolean {
  return typeof readConsent()[chatId] === 'number';
}

/** Whether the server holds this device's offer now. */
export function isBrowserOffered(chatId: string): boolean { return offered.has(chatId); }

export function onMemberBrowserChange(listener: () => void): () => void {
  listeners.add(listener);
  return () => { listeners.delete(listener); };
}
const changed = () => { for (const l of listeners) try { l(); } catch { /* a listener never breaks the channel */ } };

/** The member turns sharing on or off for one chat. Off takes effect here at once, whatever the network does. */
export async function setSharingBrowser(chatId: string, enabled: boolean): Promise<void> {
  const consent = readConsent();
  if (enabled) consent[chatId] = Date.now(); else delete consent[chatId];
  try { globalThis.localStorage?.setItem(CONSENT_KEY, JSON.stringify(consent)); } catch { /* still applies for this page */ }
  if (!enabled) offered.delete(chatId);
  changed();
  await announce(chatId);
}

async function announce(chatId: string): Promise<void> {
  if (!client || !deps) return;
  const enabled = isSharingBrowser(chatId);
  const tools = enabled ? (await deps.tools().catch(() => [])).filter(t => TOOLS.has(t)) : [];
  if (enabled && !tools.length) throw new Error('This device has no browser the agent can use.');
  await client.sendBrowserFrame(chatId, { type: 'session.browserOffer', chatId, enabled, tools, label: deps.label() });
}

async function answer(chatId: string, requestId: string, toolName: string, args: Record<string, unknown> | undefined): Promise<void> {
  const reply = (body: { result?: unknown; error?: string }) =>
    client?.sendBrowserFrame(chatId, { type: 'session.browserResult', chatId, requestId, ...body }).catch(() => {});
  // Checked here as well as on the server: this device's own record is the last word.
  if (!isSharingBrowser(chatId)) return void reply({ error: 'They are not sharing a browser with this chat.' });
  if (!TOOLS.has(toolName) || !deps) return void reply({ error: 'That is not a browser operation a member can offer.' });
  try {
    await reply({ result: await deps.invoke(toolName, args ?? {}) ?? null });
  } catch (error) {
    await reply({ error: error instanceof Error ? error.message : String(error) });
  }
}

// ── The owner's host ────────────────────────────────────────────────────────

/** Who is offering a browser to this chat now, as last told by the server. */
export function memberBrowserPeers(chatId: string): SessionBrowserPeer[] { return peersByChat.get(chatId) ?? []; }

/** Every chat someone is offering a browser to now, for the room view. */
export function allMemberBrowserPeers(): Array<{ chatId: string; peers: SessionBrowserPeer[] }> {
  return [...peersByChat].filter(([, peers]) => peers.length).map(([chatId, peers]) => ({ chatId, peers }));
}

/** The handle a member's browser goes by in browser_list_targets. */
export function memberBrowserHandle(userId: string): string {
  return `member-${userId.replace(/[^a-zA-Z0-9]/g, '').slice(-6).toLowerCase()}`;
}

/** Run one browser operation in a member's own browser. Never throws: a failure is an `error`. */
export function queryMemberBrowser(
  chatId: string, userId: string, toolName: string, args: Record<string, unknown>,
): Promise<{ result?: unknown; error?: string }> {
  if (!client) return Promise.resolve({ error: 'This conversation is not connected.' });
  const requestId = `mb_${crypto.randomUUID()}`;
  return new Promise(resolve => {
    const timer = setTimeout(() => {
      waiting.delete(requestId);
      resolve({ error: 'Their browser did not answer. Their app may be closed or in the background.' });
    }, QUERY_WAIT_MS);
    waiting.set(requestId, { resolve, timer });
    client!.sendBrowserFrame(chatId, { type: 'session.browserQuery', chatId, requestId, userId, toolName, args }, true)
      .catch((error: unknown) => {
        if (!waiting.delete(requestId)) return;
        clearTimeout(timer);
        resolve({ error: error instanceof Error ? error.message : String(error) });
      });
  });
}

// ── Wiring ──────────────────────────────────────────────────────────────────

function onFrame(chatId: string, message: SessionBrowserFrame): void {
  switch (message.type) {
    case 'session.browserPeers':
      peersByChat.set(chatId, message.peers ?? []);
      changed();
      return;
    case 'session.browserOffer':
      if (message.enabled) offered.add(chatId); else offered.delete(chatId);
      changed();
      return;
    case 'session.browserResult': {
      const entry = waiting.get(message.requestId);
      if (!entry) return;
      clearTimeout(entry.timer);
      waiting.delete(message.requestId);
      entry.resolve(message.error ? { error: message.error } : { result: message.result });
      return;
    }
    case 'session.browserQuery':
      void answer(chatId, message.requestId, message.toolName, message.args);
      return;
  }
}

/** Attach to the page's session channel. Safe to call again with a new client. */
export function installMemberBrowser(channel: SessionChannelClient, dependencies: MemberBrowserDeps): void {
  client = channel;
  deps = dependencies;
  channel.onBrowserFrame = onFrame;
  // A socket that opens, or reopens, holds no offer: say it again if the member's choice stands.
  channel.onChannelOpen = (chatId) => {
    offered.delete(chatId);
    peersByChat.delete(chatId);
    if (isSharingBrowser(chatId)) void announce(chatId).catch(() => {});
  };
}

export function _resetMemberBrowserForTests(): void {
  client = undefined; deps = undefined;
  peersByChat.clear(); offered.clear(); listeners.clear();
  for (const entry of waiting.values()) clearTimeout(entry.timer);
  waiting.clear();
}

