1	/**
2	 * The simulator over a chat, on the device of a person invited to it. The
3	 * server half is packages/api/src/relay/memberSimulator.ts.
4	 *
5	 * An invited person's chat is paired to `shared-<room>` (RemotePairingsContext,
6	 * joining a share), a machine no one can reach: they are never in the owner's
7	 * machine room. The native picture-in-picture asks the chat's machine for its
8	 * simulator like any other (`MirrorInvoke`, SimulatorPreview.swift), so for
9	 * that machine this answers instead, through the chat's share: its picture,
10	 * and with the owner's say (MirrorMemberInvokeHandler on the host) Control's
11	 * gestures. Nothing else of the owner's Mac.
12	 */
13	import type { MirrorInvokeResponse } from './relayProtocol';
14	
15	const SHARED_MACHINE = 'shared-';
16	const NOT_HERE = 'That is not something you can do with a chat shared with you.';
17	const ALLOWED_METHODS = new Set(['simulatorSnapshot', 'simulatorInput', 'simulatorControl', 'simulatorClipboardExchange']);
18	
19	/**
20	 * The chat a shared machine's panel last showed. Control's own calls
21	 * (SimulatorLiveView.swift) name no chat, and Control is only reached from
22	 * that panel, so it is the chat they are for.
23	 */
24	const chatOfMachine = new Map<string, string>();
25	
26	export function isSharedChatMachine(machineId: string): boolean {
27	  return typeof machineId === 'string' && machineId.startsWith(SHARED_MACHINE);
28	}
29	
30	export function noteSharedSimulatorChat(machineId: string, chatId: string): void {
31	  if (isSharedChatMachine(machineId) && chatId) chatOfMachine.set(machineId, chatId);
32	}
33	
34	/** A capability call on a shared chat's machine; undefined for any other machine. */
35	export async function sharedChatMirrorInvoke(
36	  machineId: string, capability: string, method: string, args: unknown[], chatId?: string,
37	): Promise<MirrorInvokeResponse | { success: false; error: string } | undefined> {
38	  if (!isSharedChatMachine(machineId)) return undefined;
39	  if (capability !== 'screenWindows' || !ALLOWED_METHODS.has(method)) return { success: false, error: NOT_HERE };
40	  if (chatId) chatOfMachine.set(machineId, chatId);
41	  const chat = chatId ?? chatOfMachine.get(machineId);
42	  const { remoteConnectBridge } = await import('./remoteConnectBridge');
43	  const pairing = chat ? remoteConnectBridge.getPairingForChat(chat) : undefined;
44	  if (!pairing?.shareToken || !pairing.hostChatId || pairing.machineId !== machineId) {
45	    return { success: false, error: 'Open this shared chat again to see its simulator.' };
46	  }
47	  const { getSessionChannelClient } = await import('../config/storage/initializeStorage');
48	  const client = getSessionChannelClient();
49	  if (!client) return { success: false, error: 'This conversation is not connected.' };
50	  const target = args[0] && typeof args[0] === 'object' ? args[0] as { udid?: unknown; action?: unknown } : {};
51	  if (method === 'simulatorInput') {
52	    return client.sharedSimulatorPicture(pairing.hostChatId, pairing.shareToken, { method, udid: target.udid, input: args[1] });
53	  }
54	  if (method === 'simulatorControl') {
55	    const second = args[1] && typeof args[1] === 'object' ? args[1] as { action?: unknown } : {};
56	    const action = typeof second.action === 'string' ? second.action : typeof target.action === 'string' ? target.action : undefined;
57	    return client.sharedSimulatorPicture(pairing.hostChatId, pairing.shareToken, { method, udid: target.udid, control: { action } });
58	  }
59	  if (method === 'simulatorClipboardExchange') {
60	    return client.sharedSimulatorPicture(pairing.hostChatId, pairing.shareToken, { method, udid: target.udid, clipboard: args[1] });
61	  }
62	  return client.sharedSimulatorPicture(pairing.hostChatId, pairing.shareToken, { udid: target.udid, pixels: args[1], quality: args[2] });
63	}
64	
65	/**
66	 * A direct simulator stream offer (`screen:offer` with `simulatorUdid`) on a
67	 * shared chat's machine. Only a simulator offer is permitted; any window,
68	 * display, page or tab offer is refused.
69	 */
70	export async function sharedChatScreenOffer(
71	  machineId: string, params?: Record<string, unknown>,
72	): Promise<{ success: true; output: unknown } | { success: false; error: string } | undefined> {
73	  if (!isSharedChatMachine(machineId)) return undefined;
74	  const udid = typeof params?.simulatorUdid === 'string' ? params.simulatorUdid.trim() : '';
75	  if (!udid || params?.windowId != null || params?.displayId != null || params?.pageId != null || params?.tabId != null) {
76	    return { success: false, error: NOT_HERE };
77	  }
78	  const chat = chatOfMachine.get(machineId);
79	  const { remoteConnectBridge } = await import('./remoteConnectBridge');
80	  const pairing = chat ? remoteConnectBridge.getPairingForChat(chat) : undefined;
81	  if (!pairing?.shareToken || !pairing.hostChatId || pairing.machineId !== machineId) {
82	    return { success: false, error: 'Open this shared chat again to see its simulator.' };
