/**
 * The simulator over a chat, on the device of a person invited to it. The
 * server half is packages/api/src/relay/memberSimulator.ts.
 *
 * An invited person's chat is paired to `shared-<room>` (RemotePairingsContext,
 * joining a share), a machine no one can reach: they are never in the owner's
 * machine room. The native picture-in-picture asks the chat's machine for its
 * simulator like any other (`MirrorInvoke`, SimulatorPreview.swift), so for
 * that machine this answers instead, through the chat's share: its picture,
 * and with the owner's say (MirrorMemberInvokeHandler on the host) Control's
 * gestures. Nothing else of the owner's Mac.
 */
import type { MirrorInvokeResponse } from './relayProtocol';

const SHARED_MACHINE = 'shared-';
const NOT_HERE = 'That is not something you can do with a chat shared with you.';
const ALLOWED_METHODS = new Set(['simulatorSnapshot', 'simulatorInput', 'simulatorControl', 'simulatorClipboardExchange']);

/**
 * The chat a shared machine's panel last showed. Control's own calls
 * (SimulatorLiveView.swift) name no chat, and Control is only reached from
 * that panel, so it is the chat they are for.
 */
const chatOfMachine = new Map<string, string>();

export function isSharedChatMachine(machineId: string): boolean {
  return typeof machineId === 'string' && machineId.startsWith(SHARED_MACHINE);
}

export function noteSharedSimulatorChat(machineId: string, chatId: string): void {
  if (isSharedChatMachine(machineId) && chatId) chatOfMachine.set(machineId, chatId);
}

/** A capability call on a shared chat's machine; undefined for any other machine. */
export async function sharedChatMirrorInvoke(
  machineId: string, capability: string, method: string, args: unknown[], chatId?: string,
): Promise<MirrorInvokeResponse | { success: false; error: string } | undefined> {
  if (!isSharedChatMachine(machineId)) return undefined;
  if (capability !== 'screenWindows' || !ALLOWED_METHODS.has(method)) return { success: false, error: NOT_HERE };
  if (chatId) chatOfMachine.set(machineId, chatId);
  const chat = chatId ?? chatOfMachine.get(machineId);
  const { remoteConnectBridge } = await import('./remoteConnectBridge');
  const pairing = chat ? remoteConnectBridge.getPairingForChat(chat) : undefined;
  if (!pairing?.shareToken || !pairing.hostChatId || pairing.machineId !== machineId) {
    return { success: false, error: 'Open this shared chat again to see its simulator.' };
  }
  const { getSessionChannelClient } = await import('../config/storage/initializeStorage');
  const client = getSessionChannelClient();
  if (!client) return { success: false, error: 'This conversation is not connected.' };
  const target = args[0] && typeof args[0] === 'object' ? args[0] as { udid?: unknown; action?: unknown } : {};
  if (method === 'simulatorInput') {
    return client.sharedSimulatorPicture(pairing.hostChatId, pairing.shareToken, { method, udid: target.udid, input: args[1] });
  }
  if (method === 'simulatorControl') {
    const second = args[1] && typeof args[1] === 'object' ? args[1] as { action?: unknown } : {};
    const action = typeof second.action === 'string' ? second.action : typeof target.action === 'string' ? target.action : undefined;
    return client.sharedSimulatorPicture(pairing.hostChatId, pairing.shareToken, { method, udid: target.udid, control: { action } });
  }
  if (method === 'simulatorClipboardExchange') {
    return client.sharedSimulatorPicture(pairing.hostChatId, pairing.shareToken, { method, udid: target.udid, clipboard: args[1] });
  }
  return client.sharedSimulatorPicture(pairing.hostChatId, pairing.shareToken, { udid: target.udid, pixels: args[1], quality: args[2] });
}

/**
 * A direct simulator stream offer (`screen:offer` with `simulatorUdid`) on a
 * shared chat's machine. Only a simulator offer is permitted; any window,
 * display, page or tab offer is refused.
 */
export async function sharedChatScreenOffer(
  machineId: string, params?: Record<string, unknown>,
): Promise<{ success: true; output: unknown } | { success: false; error: string } | undefined> {
  if (!isSharedChatMachine(machineId)) return undefined;
  const udid = typeof params?.simulatorUdid === 'string' ? params.simulatorUdid.trim() : '';
  if (!udid || params?.windowId != null || params?.displayId != null || params?.pageId != null || params?.tabId != null) {
    return { success: false, error: NOT_HERE };
  }
  const chat = chatOfMachine.get(machineId);
  const { remoteConnectBridge } = await import('./remoteConnectBridge');
  const pairing = chat ? remoteConnectBridge.getPairingForChat(chat) : undefined;
  if (!pairing?.shareToken || !pairing.hostChatId || pairing.machineId !== machineId) {
    return { success: false, error: 'Open this shared chat again to see its simulator.' };
  }
  const { getSessionChannelClient } = await import('../config/storage/initializeStorage');
  const client = getSessionChannelClient();
  if (!client) return { success: false, error: 'This conversation is not connected.' };
  const reply = await client.sharedSimulatorPicture(pairing.hostChatId, pairing.shareToken, {
    method: 'simulatorOffer',
    udid,
    offer: params,
  });
  if (reply.success && 'result' in reply) {
    return { success: true, output: reply.result };
  }
  return { success: false, error: reply.error || 'The Mac did not offer a direct connection.' };
}

export function _resetMemberSimulatorForTests(): void { chatOfMachine.clear(); }

