/**
 * The card that asks an invited member whether to share their browser.
 *
 * The owner's host puts it in the chat when a turn the member asked for needs
 * a browser and they are not sharing one. Only the member's own device acts on
 * it: answering turns sharing on there (memberBrowser.ts), and the offer that
 * device then makes is what the host sees. The answer itself never travels, so
 * nobody else's tap, and nothing the host or the agent does, can turn it on.
 */
import { getBackgroundApi } from '../web/BackgroundApiFactory';
import { logAgentAction } from '../Logger';
import { memberBrowserPeers, onMemberBrowserChange, setSharingBrowser } from './memberBrowser';
import { toCanonicalChatId } from './chatIdAliasing';
import { resumeChat, memberSharedLine } from '../frame-bridge/browserAccessResume';

const KEY_PREFIX = 'member_browser_share_';
export const SHARE_LABEL = 'Share my browser';
export const DECLINE_LABEL = 'Not now';
/** An unanswered card closes, and a later call may ask again. */
export const SHARE_CARD_WAIT_MS = 15 * 60_000;

export function isMemberShareKey(responseKey: string | undefined): boolean {
  return !!responseKey?.startsWith(KEY_PREFIX);
}

/** `member_browser_share_<userId>_<uuid>`: the card says who it is for. */
export function memberOfShareKey(responseKey: string): string | undefined {
  const rest = responseKey.slice(KEY_PREFIX.length);
  const cut = rest.lastIndexOf('_');
  return cut > 0 ? rest.slice(0, cut) : undefined;
}

export function shareQuestion(name: string): string {
  return `${name}: the agent needs a browser for what you asked. It can use the browser inside your Ripul app on this device. `
    + 'It could open, read and act in tabs there, signed in as you, for your own requests in this chat. '
    + 'Nothing is shared until you say so here, and you can stop it by answering again or closing the app.';
}

// ── The owner's host ────────────────────────────────────────────────────────

const open = new Map<string, { responseKey: string; timer: ReturnType<typeof setTimeout>; stop: () => void }>();

async function closeCard(chatId: string, responseKey: string, text: string): Promise<void> {
  const backgroundApi = getBackgroundApi();
  if (!backgroundApi) return;
  await logAgentAction(backgroundApi, chatId, {
    method: 'askUserMultiChoice', status: 'success', isMergeable: true,
    toolInvocationId: responseKey, correlationId: responseKey, result: text, data: { answer: text, responseKey },
  }, 'askUserMultiChoice', { correlationId: responseKey, result: text });
}

/** Show the member the card, once while one is open. Returns whether a new card went up. */
export async function askMemberToShare(chatId: string, member: { userId: string; name: string }): Promise<boolean> {
  const key = `${chatId}|${member.userId}`;
  if (open.has(key)) return false;
  const backgroundApi = getBackgroundApi();
  if (!backgroundApi) throw new Error('The chat is not ready to show a question.');
  const responseKey = `${KEY_PREFIX}${member.userId}_${crypto.randomUUID()}`;
  const canonical = toCanonicalChatId(chatId);
  const finish = (text: string): boolean => {
    const entry = open.get(key);
    if (!entry || entry.responseKey !== responseKey) return false;
    clearTimeout(entry.timer); entry.stop(); open.delete(key);
    void closeCard(chatId, responseKey, text).catch(() => {});
    return true;
  };
  const stop = onMemberBrowserChange(() => {
    if (!memberBrowserPeers(canonical).some(p => p.userId === member.userId) || !finish(SHARE_LABEL)) return;
    // The agent's turn ended when the call was refused: start the next one.
    void resumeChat(chatId, memberSharedLine(member.name));
  });
  open.set(key, { responseKey, stop, timer: setTimeout(() => finish('No answer. The request has closed'), SHARE_CARD_WAIT_MS) });
  const question = shareQuestion(member.name);
  const options = [
    { label: SHARE_LABEL, value: SHARE_LABEL, description: 'This device, this chat, your own requests.' },
    { label: DECLINE_LABEL, value: DECLINE_LABEL, description: 'Nothing is shared.' },
  ];
  try {
    await logAgentAction(backgroundApi, chatId, {
      method: 'askUserMultiChoice', status: 'pending', isMergeable: true, isWorkflowNode: false,
      toolInvocationId: responseKey, correlationId: responseKey,
      args: { message: question, options, multiSelect: false },
      data: { question, header: 'Share your browser', options, multiSelect: false, type: 'multiChoice',
        threadId: `member-share-${responseKey}`, actionId: `member-share-action-${responseKey}`, responseKey,
        forUserId: member.userId },
      persistPayload: true,
    }, 'askUserMultiChoice', { correlationId: responseKey });
  } catch (error) {
    const entry = open.get(key);
    if (entry) { clearTimeout(entry.timer); entry.stop(); open.delete(key); }
    throw error;
  }
  return true;
}

// ── The member's device ─────────────────────────────────────────────────────

/**
 * The member answered the card on this device. Only the person it names may:
 * the owner and other members see the same card.
 */
export async function answerShareCard(
  chatId: string, responseKey: string, answer: string, currentUserId: string | null | undefined,
): Promise<void> {
  const forUser = memberOfShareKey(responseKey);
  if (!forUser || !currentUserId || forUser !== currentUserId) {
    throw new Error('This question is for the person who asked. Only they can answer it, on their own device.');
  }
  await setSharingBrowser(toCanonicalChatId(chatId), answer === SHARE_LABEL);
}

export function _resetShareCardsForTests(): void {
  for (const entry of open.values()) { clearTimeout(entry.timer); entry.stop(); }
  open.clear();
}

