import { invitedRequesterFor, memberNotSharingRefusal, teamRequesterFor } from '../relay/turnRequester';
import { memberBrowserHandle, memberBrowserPeers, queryMemberBrowser } from '../relay/memberBrowser';
import { askMemberToShare } from '../relay/memberBrowserPrompt';
import { toCanonicalChatId } from '../relay/chatIdAliasing';

/**
 * A member's own browser. In a turn an invited member asked for, or a teammate
 * asked for in a team chat on a shared Mac, a call that names no target goes to
 * their browser and nowhere else: if they are not sharing one, the call is
 * refused and they are asked, and it never falls back to a browser of the
 * owner's. A member's browser is not used in anyone else's turn.
 * Returns undefined when the call is not for a member's browser.
 */
export async function executeInMemberBrowser(
  chatId: string, toolName: string, wanted: string, toolArgs: Record<string, unknown>,
): Promise<{ result?: unknown; error?: string; chatId: string } | undefined> {
  const invited = invitedRequesterFor(chatId) ?? teamRequesterFor(chatId);
  const named = wanted.startsWith('member-');
  if (!named && (wanted || !invited)) return undefined;
  if (!invited) {
    return { error: `${wanted} is a member's own browser. It is used only in a turn that member asked for.`, chatId };
  }
  const handle = memberBrowserHandle(invited.userId);
  if (named && wanted !== handle) {
    return { error: `${wanted} is another member's browser. This turn was asked for by ${invited.name}, whose browser is ${handle}.`, chatId };
  }
  const canonical = toCanonicalChatId(chatId);
  const answer = await queryMemberBrowser(canonical, invited.userId, toolName, toolArgs);
  if (answer.error === undefined) {
    const peer = memberBrowserPeers(canonical).find(p => p.userId === invited.userId);
    const result = answer.result;
    return { chatId, result: {
      ...(result && typeof result === 'object' && !Array.isArray(result) ? result as Record<string, unknown> : { value: result }),
      _target: handle, _targetReason: named ? 'explicit' : 'requester',
      _device: `${invited.name}'s own browser${peer?.label ? ` (${peer.label})` : ''}`,
      _requestedBy: `${invited.name} (${invited.team ? 'teammate' : 'invited member'})`,
      _notice: `This ran in ${invited.name}'s own browser, signed in as them, because they asked for this turn and are sharing it.`,
    } };
  }
  if (!/not sharing a browser/i.test(answer.error)) {
    return { error: `${invited.name}'s browser (${handle}): ${answer.error} Nothing was sent to the chat owner's browsers.`, chatId };
  }
  const how = await askMemberToShare(chatId, invited).then((asked): 'asked' | 'waiting' => asked ? 'asked' : 'waiting')
    .catch((error): 'cannot-ask' => { console.warn('[MemberBrowser] could not ask the member', error); return 'cannot-ask'; });
  return { error: memberNotSharingRefusal(invited, how), chatId };
}

