/**
 * Which part of a chat's history a reply covers.
----
/**
 * An invited member's own browser, offered to the chat's agent.
 *
 * A member is never in the owner's machine room, so none of their devices is
 * a tool target there. This is the one way their browser can be reached, and
 * it is theirs to give: nothing is reachable until one of their own sockets
 * says so (`session.browserOffer`), and it stops when that socket says so or
 * closes. The offer lives on the socket and nowhere else, so it never outlasts
 * the device that made it.
 *
 * Only the chat's owner (the host of its agent) may send a query, only the five
 * browser operations cross, and only to a named invitee who is still a member.
 */
import type {
  SessionBrowserOfferMessage, SessionBrowserQueryMessage, SessionBrowserResultMessage, SessionBrowserPeer,
  SessionServerMessage,
} from './types';
import { MEMBER_BROWSER_TOOLS } from './types';

export interface BrowserParty {
  clientId: string;
  authorId: string;
  authorDisplayName?: string;
  capabilities: Set<string>;
  shareAccess?: unknown;
  departmentAccess?: unknown;
  browserOffer?: { tools: string[]; label?: string };
}

const TOOLS: ReadonlySet<string> = new Set(MEMBER_BROWSER_TOOLS);
const MAX_ARGS_BYTES = 64 * 1024;
const MAX_RESULT_BYTES = 1024 * 1024;
export const MEMBER_BROWSER_QUERY_MS = 55_000;

/** The owner's own connection: the host of the chat's agent, or another of the owner's devices. */
export function isOwnerParty(sub: BrowserParty, ownerId: string): boolean {
  return sub.authorId === ownerId && sub.capabilities.has('write') && !sub.shareAccess && !sub.departmentAccess;
}

/**
 * A named invitee, or a teammate in a team chat on a Mac shared with their
 * team, each on their own verified identity (a teammate's grant names this
 * chat and their account, and is checked again while they stay). A bare link,
 * an outsider and the owner are not.
 */
export function isMemberParty(sub: BrowserParty, ownerId: string): boolean {
  if (sub.authorId === ownerId) return false;
  return (!!sub.shareAccess && sub.capabilities.has('discuss')) || !!sub.departmentAccess;
}

export function offeredPeers(subs: Iterable<BrowserParty>, ownerId: string): SessionBrowserPeer[] {
  const peers: SessionBrowserPeer[] = [];
  for (const sub of subs) {
    if (!sub.browserOffer || !isMemberParty(sub, ownerId)) continue;
    peers.push({ userId: sub.authorId, clientId: sub.clientId, tools: sub.browserOffer.tools,
      ...(sub.authorDisplayName ? { displayName: sub.authorDisplayName } : {}),
      ...(sub.browserOffer.label ? { label: sub.browserOffer.label } : {}) });
  }
  return peers.sort((a, b) => a.clientId.localeCompare(b.clientId));
}

interface Pending { requester: string; target: string; timer: ReturnType<typeof setTimeout> }

export class MemberBrowserBroker<S extends BrowserParty> {
  private pending = new Map<string, Pending>();

  constructor(
    private readonly subscribers: () => Iterable<S>,
    private readonly send: (sub: S, message: SessionServerMessage) => void,
  ) {}

  private find(clientId: string): S | undefined {
    for (const sub of this.subscribers()) if (sub.clientId === clientId) return sub;
    return undefined;
  }

  /** Tell the owner's connections who is offering a browser now. */
  announce(chatId: string, ownerId: string, only?: S): void {
    const peers = offeredPeers(this.subscribers(), ownerId);

