/** Is this URL a Ripul app tab (this origin)? */
function sameOriginAsApp(url: string): boolean {
  try {
    return new URL(url).origin === location.origin;
  } catch {
    return false;
  }
}

/** Map web inspection tool names to existing peer query handler types. */
const WEB_TOOL_QUERY_MAP: Record<string, PeerQueryType> = {
  console_logs: 'consoleLogs',
  network_logs: 'networkLogs',
  query_elements: 'queryElements',
  page_info: 'pageInfo',
  evaluate: 'evaluateScript',
};

export async function computeLocalTools(): Promise<{ tools: Array<{ name: string; description: string; inputSchema: Record<string, unknown>; outputSchema?: Record<string, unknown>; timeout?: number }> }> {
  const tools: Array<{ name: string; description: string; inputSchema: Record<string, unknown>; outputSchema?: Record<string, unknown>; timeout?: number }> = [];

  // 1. Web inspection tools (always available)
  tools.push(...WEB_INSPECTION_TOOLS);
  if (!isCliHostPage()) tools.push(...VIEWER_DEBUG_TOOLS);

  // Native discovery failures must not become authoritative web-only snapshots.
  // Keep a previously discovered registry while the bridge reconnects; if there
  // is no complete snapshot yet, the announcement/query must fail and retry.
  const nativeTools = await nativeToolSnapshot(getNativeBridgeInstance(), isNativeAppMode());
  const webNames = new Set(tools.map((t) => t.name));
  for (const t of nativeTools) {
    if (!webNames.has(t.name)) {
      // `timeout` (ms, 0 = open-ended) is the tool's declared deadline. Hosts use
      // it to size their own waits, so a fast tool fails fast at every layer.
      tools.push({ name: t.name, description: t.description, inputSchema: t.inputSchema,
        ...(t.outputSchema ? { outputSchema: t.outputSchema } : {}),
        ...(typeof t.timeout === 'number' ? { timeout: t.timeout } : {}) });
    }
  }

  // 3. This browser's own tabs, when the extension is present.
  //    Skipped on a native shell: the native block above already contributed
  //    BrowserTools under these exact names, and double-advertising would make
  //    one surface look like two.
  try {
    const ctx = await viewerBrowserContext();
    if (ctx) {
      const taken = new Set(tools.map((t) => t.name));
      for (const t of VIEWER_BROWSER_TOOLS) {
        if (!taken.has(t.name)) tools.push(t);
      }
    }
  } catch {
    // No extension / no tabs capability — nothing to advertise.
  }

  return { tools };
}

async function handleInvokeTool(params: { toolName: string; args: Record<string, unknown> }): Promise<unknown> {
  const { toolName, args } = params;

  // Web inspection tools — dispatch to existing handlers
  const queryType = WEB_TOOL_QUERY_MAP[toolName];
  if (queryType) {
    return handlePeerQuery(`invoke_${Date.now()}`, queryType, args).then((r) => {
      if (!r.success) throw new Error(r.error || `${toolName} failed`);
      return r.result;
    });
  }

  if (VIEWER_DEBUG_TOOL_NAMES.has(toolName) && !isCliHostPage()) {
    return invokeViewerDebugTool(toolName, args ?? {});
  }

  // This browser's own tabs. Gated on the native bridge being ABSENT, exactly
  // mirroring the advertise-side dedupe: when a native shell is driving, these
  // names belong to its Swift BrowserTools and must route there.
  if (VIEWER_BROWSER_TOOL_NAMES.has(toolName) && !(await nativeBridgeOwnsBrowserTools())) {
    const ctx = await viewerBrowserContext();
    if (ctx) return invokeViewerBrowserTool(ctx, toolName, args ?? {});
    throw new Error(
      `${toolName} needs the Ripul browser extension — this tab has no tabs capability.`,
    );
  }

  // Native tools — forward to AgentBridge
  try {
    const { getNativeBridgeInstance } = await import('../hosted-app/NativeBridge');
    const nativeBridge = getNativeBridgeInstance();
    if (!nativeBridge?.isConnected()) {
      throw new Error(`Native bridge not connected — cannot invoke ${toolName}`);
    }
    // Honour the tool's declared timeout (0 = open-ended). Without it the bridge
    // applied a flat 30s to everything: too long for a tap, too short for a sweep.
    const declared = nativeBridge.hasDiscoveredTools()
      ? nativeBridge.getDiscoveredTools().find((t) => t.name === toolName)?.timeout
      : undefined;
    return await nativeBridge.invokeTool(toolName, args, typeof declared === 'number' ? declared : undefined);
  } catch (e) {
    throw new Error(`Failed to invoke ${toolName}: ${e instanceof Error ? e.message : String(e)}`);
  }
}

