/**
 * Who asked for a chat's latest turn.
 *
 * A chat can hold several people: its owner, and members the owner invited.
 * An invited member is never in the owner's machine room (authorizeRelay keeps
 * session shares out of it), so none of their devices is a tool target. Their
 * `@Agent` request reaches the host as an `agent:start` the server builds, sent
 * as `participant:<their user id>` (ChatRelay.invokeSessionAgent).
 *
 * Tools that act on a browser or device read this to say whose request they
 * are serving, because every target they can reach belongs to the owner.
 */
import { readToolState, writeToolState, flushToolState } from '../frame-bridge/toolCatalog';
import { noteMember } from '../frame-bridge/memberAuthority';

/** The invited member an agent's message is passed on for, and the chat they asked in. */
export interface OnBehalfOf { userId: string; name: string; chatId: string }

export interface TurnRequester {
  clientId: string;
  displayName?: string;
  /** Set when another agent sent this turn while serving an invited member's request. */
  onBehalfOf?: OnBehalfOf;
  /** The account the relay stamped on a person's request (stampHumanCommand); a client cannot set it. */
  userId?: string;
  at: number;
}

export interface InvitedRequester {
  userId: string;
  name: string;
  /** The chat whose authority counts, when the request was handed on from there. */
  authorityChatId?: string;
  /** A member of a team this Mac is shared with, in a team chat, rather than someone invited to the chat. */
  team?: true;
}

const STATE = 'turnRequester';
/** The host's own line that continues a chat after a card is answered. It is nobody's request. */
export const RESUME_SENDER = 'browser-access';
const PARTICIPANT_PREFIX = 'participant:';
const AGENT_PREFIX = 'agent:';

/** CLI chats are addressed as `cli_<uuid>` on some paths and as the bare uuid on others. */
function aliases(chatId: string): string[] {
  return chatId.startsWith('cli_') ? [chatId, chatId.slice(4)] : [chatId, `cli_${chatId}`];
}

/** The user id of an invited member's sender id, or undefined for anyone else. */
export function invitedUserIdFromClientId(clientId: string | undefined): string | undefined {
  if (!clientId?.startsWith(PARTICIPANT_PREFIX)) return undefined;
  return clientId.slice(PARTICIPANT_PREFIX.length) || undefined;
}

/** Record the sender of an `agent:start`. Every turn records, so the owner's next message replaces a member's. */
export function recordTurnRequester(chatId: string, clientId: string | undefined, displayName?: string, onBehalfOf?: OnBehalfOf, userId?: string): void {
  if (!chatId || !clientId || clientId === 'unknown' || clientId === RESUME_SENDER) return;
  // Only an agent passes a request on. From anyone else the field means nothing.
  const passedOn = clientId.startsWith(AGENT_PREFIX) && onBehalfOf?.userId && onBehalfOf.chatId
    ? { userId: onBehalfOf.userId, name: onBehalfOf.name?.trim() || 'An invited member', chatId: onBehalfOf.chatId } : undefined;
  writeToolState<TurnRequester>(chatId, STATE, {
    clientId, ...(displayName ? { displayName } : {}), ...(passedOn ? { onBehalfOf: passedOn } : {}),
    ...(userId ? { userId } : {}), at: Date.now(),
  });
  // Remember an invited member by name, so the owner can give them authority in a sentence.
  const memberId = invitedUserIdFromClientId(clientId);
  // Not awaited: who asked is already written above, which is all a check reads from here.
  if (memberId) void noteMember(chatId, memberId, displayName).catch(() => {});
  void flushToolState(chatId).catch(() => {});
}

export function turnRequesterFor(chatId: string): TurnRequester | undefined {
  let latest: TurnRequester | undefined;
  for (const id of aliases(chatId)) {
    const value = readToolState<TurnRequester | null>(id, STATE, () => null);
    if (value && (!latest || value.at > latest.at)) latest = value;
  }
  return latest;
}

