/** The invited member who asked for the latest turn, or undefined when the owner (or nobody known) did. */
export function invitedRequesterFor(chatId: string): InvitedRequester | undefined {
  const requester = turnRequesterFor(chatId);
  // An agent serving a member's request passed it on here: it is still the member's.
  if (requester?.clientId.startsWith(AGENT_PREFIX) && requester.onBehalfOf) {
    const { userId, name, chatId: authorityChatId } = requester.onBehalfOf;
    return { userId, name, authorityChatId };
  }
  const userId = invitedUserIdFromClientId(requester?.clientId);
  if (!userId) return undefined;
  return { userId, name: requester?.displayName?.trim() || 'An invited member' };
}

/**
 * The teammate who asked for the latest turn, in a team chat on a Mac shared
 * with their team. Their own device sent it: the relay stamped their account,
 * and their device's id carries the same one (the relay gives a teammate no
 * other). Undefined for the owner, an invited member, an agent or anyone else.
 * Only their own browser offer reads this: a team chat's agent otherwise still
 * runs as the Mac's owner (sharedMacAccess.md).
 */
export function teamRequesterFor(chatId: string): InvitedRequester | undefined {
  const requester = turnRequesterFor(chatId);
  const userId = requester?.userId;
  const owner = hostOwnerUserId();
  if (!userId || !owner || userId === owner) return undefined;
  if (!requester.clientId.startsWith(`controller-${userId}-`) && requester.clientId !== `controller-${userId}`) return undefined;
  return { userId, name: requester.displayName?.trim() || 'A teammate', team: true };
}

/** How a member is named to the agent: invited to the chat, or on the team this Mac is shared with. */
export function memberRole(requester: InvitedRequester): string {
  return requester.team ? 'a member of the team this Mac is shared with' : 'an invited member';
}

/** What an agent's message from this chat carries, so the chat it reaches knows whose request it serves. */
export function onBehalfOfFor(chatId: string): OnBehalfOf | undefined {
  const invited = invitedRequesterFor(chatId);
  return invited ? { userId: invited.userId, name: invited.name, chatId: invited.authorityChatId ?? chatId } : undefined;
}

/** What a browser result says when it ran in the owner's browser for a member's request. The owner allowed it. */
export function invitedRequestNotice(requester: InvitedRequester, target: string): string {
  return `${requester.name}, an invited member, asked for this turn. Their own browser cannot be reached from this chat, `
    + `so this ran in the chat owner's browser (${target}), which the owner allowed for ${requester.name}'s requests. `
