async function discoverDeviceTools(
  peerQuery: ((queryType: PeerQueryType, params: Record<string, unknown>, targeting?: { chatId?: string; peerTarget?: PeerTarget; peerSelector?: string; timeoutMs?: number }) => Promise<PeerQueryResponse>) | undefined,
  chatId = 'local',
): Promise<DiscoveredDeviceTool[]> {
  const sources = await discoverSessionDeviceSources(chatId, peerQuery ? async () => {
    const queryAll = (window as any).__ripulPeerQueryAll as
      ((q: PeerQueryType, p: Record<string, unknown>, o?: { timeoutMs?: number }) => Promise<PeerQueryResponse[]>) | undefined;
    return queryAll ? queryAll('listTools', {}, { timeoutMs: 5000 })
      : [await peerQuery('listTools', {}, { peerTarget: 'any' })];
  } : undefined, peerQuery ? {
    peers: () => toolPeerSnapshot(chatId).peers,
    ask: clientId => peerQuery('listTools', {}, { chatId, peerSelector: clientId, timeoutMs: 5000 }),
    chosen: () => {
      const working = peekWorkingDevice(chatId)?.clientId;
      const pinned = pinnedTargetFor(chatId);
      const pinnedIds = pinned ? readToolSources<AnnouncedTool>(chatId, 'device')
        .filter(s => deviceHandleFor({ clientId: s.id, displayName: s.label ?? '' }) === pinned).map(s => s.id) : [];
