/**
 * Execute a device tool by proxying through the generic `invokeTool`
 * peer query. Strips the `device_` prefix before sending.
 */
async function executeDeviceTool(
  chatId: string,
  toolName: string,
  args: Record<string, unknown>,
): Promise<{ result?: unknown; error?: string; chatId: string }> {
  const peerQuery = (window as any).__ripulPeerQuery as
    | ((queryType: PeerQueryType, params: Record<string, unknown>, targeting?: { chatId?: string; peerTarget?: PeerTarget; peerSelector?: string; timeoutMs?: number }) => Promise<PeerQueryResponse>)
    | undefined;

  if (!peerQuery) {
    return {
      error: 'No remote device connected — peer query bridge not available. ' +
        'A device must be connected via relay for device inspection tools to work.',
      chatId,
    };
  }

  const nativeName = toolName.startsWith(DEVICE_PREFIX)
    ? toolName.slice(DEVICE_PREFIX.length)
    : toolName;

  // `device` is a routing selector injected by withDeviceSelectorParam, not a
  // real device-tool arg — pull it out so it targets a peer and isn't forwarded.
  const { device, ...toolArgs } = (args ?? {}) as Record<string, unknown> & { device?: unknown };
  const peerSelector = typeof device === 'string' && device.trim() ? device.trim() : undefined;

  try {
    // Wait as long as the tool says it takes, plus transit — a tap declared at 5s
    // fails at ~10s, not at a fixed 15s, and a 60s sweep is no longer cut off.
    // Unknown (no declaration seen yet) keeps the relay's default.
    const declared = deviceToolTimeouts(chatId)[toolName];
    // A call may ask for longer than the declaration: `timeoutMs` (evaluate)
    // or `waitMs` (console_logs), capped. Mirrors the MCP bridge's deadline.
    const asked = Number((toolArgs as { timeoutMs?: unknown; waitMs?: unknown }).timeoutMs
      ?? (toolArgs as { waitMs?: unknown }).waitMs) || 0;
    const timeoutMs = asked > 0 ? Math.min(asked, 120_000) + DEVICE_TRANSIT_MARGIN_MS
      : declared === undefined ? undefined
      : declared === 0 ? OPEN_ENDED_DEVICE_WAIT_MS : declared + DEVICE_TRANSIT_MARGIN_MS;
    const response = await peerQuery('invokeTool', { toolName: nativeName, args: toolArgs },
      { chatId, peerSelector, ...(timeoutMs !== undefined ? { timeoutMs } : {}) });
    if (response.success) {
      let result = response.result;
      // Identify which device actually answered (most useful when no selector
      // was given and the fastest of several connected peers won the race).
      //
      // `_device` is the handle, not the display name: two peers can share a
      // label, so a label cannot say WHICH one ran this. The handle is unique
      // and is what a follow-up call should pass back as `device`.
      if (response.responderClientId && result && typeof result === 'object' && !Array.isArray(result)) {
        // A simulator's UDID goes with every answer from it, so the chat that
        // drives it can show it (simulatorPreviewAuto.ts) and simctl can name it.
        learnSimulatorUdid(response.responderClientId, (result as { simulatorUdid?: unknown }).simulatorUdid);
        const simulator = simulatorUdidOf(response.responderClientId);
        if (simulator && chatId) {
          void import('../logging/components/chat/v2/simulatorPreviewAuto')
            .then(({ recordChatSimulator }) => recordChatSimulator(chatId, simulator))
            .catch(() => {});
        }
        result = {
          ...(result as Record<string, unknown>),
          _device: deviceHandleFor({
            clientId: response.responderClientId,
            displayName: response.responderName ?? '',
          }),
          ...(response.responderName ? { _deviceLabel: response.responderName } : {}),
          ...(simulator ? { _simulator: simulator } : {}),
        };
      }
      return { result, chatId };
    }
    // Lazy repair: if the call failed in a way that means the device is gone or
    // its bridge is down, drop its announcement. Push-based tools would
    // otherwise be advertised until the peer formally left the roster, and the
    // model would keep choosing a device that cannot serve it. Narrowly scoped
    // on purpose - an ordinary tool failure (bad selector, page not loaded) must
    // NOT invalidate, or every real error would re-trigger discovery.
    const err = response.error || '';
    if (/not connected|not found|no remote device responded|bridge/i.test(err)) {
      const gone = response.responderClientId;
      if (gone) forgetAnnouncedTools(gone);
    }
    return { error: response.error || 'Peer query failed', chatId };
  } catch (e) {
    return { error: e instanceof Error ? e.message : String(e), chatId };
  }
}

