      // label, so a label cannot say WHICH one ran this. The handle is unique
      // and is what a follow-up call should pass back as `device`.
      if (response.responderClientId && result && typeof result === 'object' && !Array.isArray(result)) {
        // A simulator's UDID goes with every answer from it, so the chat that
        // drives it can show it (simulatorPreviewAuto.ts) and simctl can name it.
        learnSimulatorUdid(response.responderClientId, (result as { simulatorUdid?: unknown }).simulatorUdid);
        const simulator = simulatorUdidOf(response.responderClientId);
        if (simulator && chatId) {
          void import('../logging/components/chat/v2/simulatorPreviewAuto')
            .then(({ recordChatSimulator }) => recordChatSimulator(chatId, simulator))
            .catch(() => {});
        }
        result = {
          ...(result as Record<string, unknown>),
          _device: deviceHandleFor({
            clientId: response.responderClientId,
            displayName: response.responderName ?? '',
          }),
          ...(response.responderName ? { _deviceLabel: response.responderName } : {}),
          ...(simulator ? { _simulator: simulator } : {}),
        };
      }
      return { result, chatId };
    }
    // Lazy repair: if the call failed in a way that means the device is gone or
    // its bridge is down, drop its announcement. Push-based tools would
    // otherwise be advertised until the peer formally left the roster, and the
    // model would keep choosing a device that cannot serve it. Narrowly scoped
    // on purpose - an ordinary tool failure (bad selector, page not loaded) must
    // NOT invalidate, or every real error would re-trigger discovery.
    const err = response.error || '';
    if (/not connected|not found|no remote device responded|bridge/i.test(err)) {
      const gone = response.responderClientId;
      if (gone) forgetAnnouncedTools(gone);
    }
    return { error: response.error || 'Peer query failed', chatId };
  } catch (e) {
    return { error: e instanceof Error ? e.message : String(e), chatId };
  }
}

