// Everything here is wiring: compute what is reachable, collapse the manifest,
// and route a call to whichever surface `target` named.

/** Known capabilities and live reachability are intentionally separate. */
function toolPeerSnapshot(chatId: string): { peers: Array<{ clientId: string; displayName: string }>; originClientId?: string } {
  return (window as any).__ripulToolPeerSnapshot?.(chatId) ?? { peers: [] };
}

