/**
 * device_list_targets: each device with its model (the relay labels every
 * iPhone alike, so the model is how "the iPhone 16" is found), who holds it,
 * and this chat's working device.
 */
async function describeDeviceTargets(chatId: string, devices: ReturnType<typeof deviceTargetsFor>) {
  const invited = invitedRequesterFor(chatId);
  if (invited) await loadMemberAuthority(invited.authorityChatId ?? chatId);
  await Promise.all([
    // Reading a model asks the device for a frame of its screen: not in a member's turn.
    invited ? Promise.resolve() : probeDeviceModels(devices
      .filter(d => d.available && d.tools.includes('screen_frame'))
      .map(d => ({ clientId: d.clientId, displayName: d.label }))),
    bridgePhones(),
  ]);
  const working = await getWorkingDevice(chatId);
  const leases = liveLeases();
  return {
    workingDevice: working ? {
      handle: working.handle,
      model: working.model ?? modelOf(working.clientId) ?? null,
      ...(working.udid ? { udid: working.udid, bridgeName: working.bridgeName ?? null } : {}),
      connected: devices.some(d => d.clientId === working.clientId && d.available),
      setBy: working.setBy,
      heldByThisChat: leases.some(l => l.clientId === working.clientId && sameChat(l.chatId, chatId)),
    } : null,
    targets: devices.map(d => {
      const lease = leases.find(l => l.clientId === d.clientId);
      const link = knownLink({ clientId: d.clientId, displayName: d.label });
      return {
        ...d,
        model: modelOf(d.clientId) ?? null,
        // The same phone as ripul-bridge and installs know it (host_bridge_* tools' `phone`).
        ...(link ? { udid: link.udid, bridgeName: link.bridgeName ?? null } : {}),
        // A simulator by the UDID simctl and ripul-train acquire take.
        ...(!link && simulatorUdidOf(d.clientId) ? { udid: simulatorUdidOf(d.clientId), simulator: true } : {}),
        ...(lease ? { heldBy: sameChat(lease.chatId, chatId) ? 'this chat' : `${lease.holder} (${lease.chatId})` } : {}),
        // What member_authority calls this device, for "let George use my iPhone".
        permission: deviceTargets({ clientId: d.clientId })[0],
        ...(invited ? { access: memberAccessState(chatId, deviceTargets({ clientId: d.clientId, udid: link?.udid })) } : {}),
      };
    }),
    ...(invited ? { requestedBy: { ...invited, invitedMember: true },
      memberNote: `${invited.name}, an invited member, asked for this turn. Every device here belongs to the chat owner. A call to one `
        + 'that is not allowed is refused, and the owner decides.' } : {}),
    note: working
      ? 'Device tools act on the working device when a call names none. device_set_working_device moves this chat or hands the device back.'
      : 'This chat has no working device, so device tools need a `device` when several are connected. device_set_working_device gives it one.',
  };
}

/** device_set_working_device: move this chat to a device, or hand its device back. */
async function setWorkingDeviceTool(chatId: string, args: Record<string, unknown>): Promise<{ result?: unknown; error?: string; chatId: string }> {
  const previous = await getWorkingDevice(chatId);
  if (args.release === true) {
    const released = await releaseChatDevices(chatId, { clearWorkingDevice: true });
    return { result: {
      workingDevice: null,
      previous: previous ? describeWorkingDevice(previous) : null,
      released: released.map(l => describeWorkingDevice(l)),
      note: 'Handed back. Other agents can use it now. This chat has no working device until it is given one.',
    }, chatId };
  }
  const selector = typeof args.device === 'string' ? args.device.trim() : '';
  if (!selector) return { error: 'Pass `device` (a handle or model name from device_list_targets), or `release: true`.', chatId };
  const resolved = await resolveDeviceByAnyName(selector, toolPeerSnapshot(chatId).peers);
  if (!resolved.ok) return { error: resolved.error, chatId };
  const refused = await deviceRefusal(chatId, {
    clientId: resolved.peer.clientId, udid: knownLink(resolved.peer)?.udid, name: resolved.peer.displayName,
  });
  if (refused) return { error: refused, chatId };
  try {
    const { device, lease } = await claimDevice(chatId, resolved.peer, chatTitleOf(chatId), 'move');
    return { result: {
      workingDevice: describeWorkingDevice(device),
      handle: device.handle,
      previous: previous ? describeWorkingDevice(previous) : null,
      heldUntil: new Date(lease.expiresAt).toISOString(),
      note: 'Device tools now act on this device when a call names none. Other agents\' device calls to it are refused '
        + 'until you move, hand it back (release: true), or go an hour without using it.',
    }, chatId };
  } catch (e) {
    return { error: e instanceof DeviceLeaseError || e instanceof Error ? e.message : String(e), chatId };
  }
