import type { IBackgroundApi } from '../../IBackgroundApi';
import type { ToolResult } from '../../types/ThreadTypes';
import type { QuestionAnswerDelivery } from '../../LLM/CodexUserInputBridge';
import { authorizeQuestionAnswer } from '../../notifications/questionNotifier';
import { isDirectMacSession, directMacCommand } from '../../standalone/directMacSession';
import { isRelayPairedRemoteChat } from '../../relay/chatIdAliasing';
import { ThreadStorageManager } from '../../ThreadStorageManager';
import { ToolCallResultPromiseRegistry } from '../../LLM/Tools/Utils/ToolCallResultPromiseRegistry';
import { SEALED_SECRET_KEY_PREFIX } from '../../shared/sealedSecret';

/** Shared by web cards, native embeds and the full native chat scroller.
 * A submission succeeds only when the owning agent's transport accepts it. */
export const submitToolResult = async (
  threadId: string,
  actionId: string,
  responseKey: string,
  result: string,
  background: IBackgroundApi | null,
  _chatId?: string,
  remoteSendToolResult?: (threadId: string, actionId: string, responseKey: string, result: string) => Promise<QuestionAnswerDelivery>
) => {
  // A secret for one Mac is sealed to it here, before it leaves this device (shared/sealedSecret.ts).
  if (responseKey.startsWith(SEALED_SECRET_KEY_PREFIX)) {
    const { sealAnswerIfAsked } = await import('../../shared/sealedSecret');
    result = await sealAnswerIfAsked(responseKey, result, { chatId: _chatId });
  }
  // A member's choice to share their browser is made on their own device and
  // goes nowhere else (relay/memberBrowserPrompt.ts).
  if (_chatId && responseKey.startsWith('member_browser_share_')) {
    const { answerShareCard } = await import('../../relay/memberBrowserPrompt');
    await answerShareCard(_chatId, responseKey, result, (window as any).Clerk?.user?.id);
    return;
  }
  if (_chatId && isDirectMacSession(_chatId)) {
    await directMacCommand(_chatId, { op: 'answerQuestion', responseKey, value: result });
    return;
  }
  if (!remoteSendToolResult && _chatId) {
    const { remoteConnectBridge } = await import('../../relay/remoteConnectBridge');
    if (remoteConnectBridge.getPairingForChat(_chatId) || isRelayPairedRemoteChat(_chatId)) {
      remoteSendToolResult = (thread, action, key, value) =>
        remoteConnectBridge.sendToolResult(_chatId, thread, action, key, value);
    }
  }
  if (remoteSendToolResult) {
    const delivery = await remoteSendToolResult(threadId, actionId, responseKey, result);
    if (delivery === 'expired') throw new Error('This question has closed. Send a new message to continue.');
    return;
  }
  if (_chatId) await authorizeQuestionAnswer(_chatId, responseKey, result);
  if (_chatId && responseKey.startsWith('codex_question_')) {
    const { acceptCodexQuestionAnswer } = await import('../../LLM/CodexUserInputBridge');
    const delivery = await acceptCodexQuestionAnswer(_chatId, responseKey, result);
    if (delivery === 'expired') throw new Error('This question has closed. Send a new message to continue.');
    return;
  }
  const thread = await ThreadStorageManager.getById(threadId);

  if (!thread) {
    // Fallback: some question flows are not backed by a real thread in storage
    // (e.g. Claude Code CLI's `ask_user` MCP tool, which flows through the
    // CliPermissionBridge and awaits a promise in ToolCallResultPromiseRegistry).
    // If a promise is pending for this responseKey, resolve it directly so the
    // caller gets the user's answer.
    if (ToolCallResultPromiseRegistry.hasPromise(responseKey)) {
      ToolCallResultPromiseRegistry.resolve(responseKey, result);
      return;
    }
    // Nothing waits in memory any more (a reload, or a call handed back
    // unanswered): the card's saved record takes the answer (lateAnswers.ts).
    if (_chatId) {
      const { deliverLateAnswer } = await import('../../notifications/lateAnswers');
      if (await deliverLateAnswer(_chatId, responseKey, result)) return;
      // An owner's request nothing here waits for: closed everywhere, and said so (browserAccessPrompt.ts).
      const { isOwnerApprovalKey } = await import('../../frame-bridge/browserAccess');
      if (isOwnerApprovalKey(responseKey)) {
        const { closeUnwaitedOwnerApproval } = await import('../../frame-bridge/browserAccessPrompt');
        await closeUnwaitedOwnerApproval(_chatId, responseKey).catch(() => {});
        throw new Error('This question has closed: nothing was waiting for its answer any more.');
      }
    }
    console.error('[UnifiedAgentQuestionPanel] Thread not found:', threadId);
    throw new Error(`Thread ${threadId} not found`);
  }
  const action = thread?.nextAction;
  if (!action) {
    console.error('[UnifiedAgentQuestionPanel] Thread has no next action:', threadId);
    throw new Error(`Thread ${threadId} has no next action.`);
  }

  if (!background) throw new Error('The conversation is not ready. Please try again.');
  action.data[responseKey] = result;
  const toolResult: ToolResult = {
    ...action,
    toolResult: result,
    responseKey,
    actionType: 'toolResult',
  };
  await background.recordToolResult(threadId, toolResult);
};

