      sessionChannelClient = client;
      // The Mac host, which alone puts requests to the owner, closes the ones nothing waits for any more (browserAccessPrompt.ts).
      const settleOwnerApprovals = () => void import('../../shared/providerConstants')
        .then(({ getAnyCliBridge }) => getAnyCliBridge()
          && import('../../frame-bridge/browserAccessPrompt').then(prompt => prompt.settleOwnerApprovals()))
        .catch(error => console.warn('[OwnerApprovals] could not settle open requests', error));
      setTimeout(settleOwnerApprovals, 60_000);
      setInterval(settleOwnerApprovals, 30 * 60_000);
