/**
 * A member's own device, shared with the chat's agent for reading.
 *
 * The device of a person invited to a chat (an iPhone running an app that
 * embeds Ripul, say) is never in the owner's machine room, so the chat's agent
 * cannot reach it. This is the one way it can, and it is the member's to give,
 * as with their browser (memberBrowser.ts): nothing is reachable until one of
 * their own sockets offers it (`session.deviceOffer`), the offer lives on that
 * socket alone, and it ends when that socket says so or closes, when the
 * member leaves the chat, or at the end the member set, an hour at most.
 *
 * The device names each tool it shares and what it does: `reads` (the app's
 * data) or `screen` (what is on its screen). Only those cross, and no tool that
 * changes anything is ever taken. Only the chat's owner may send a query, only
 * for a tool in the offer, and only to the member's device it names.
 */
import type {
  MemberDeviceAccess, MemberDeviceTool, SessionDeviceOfferMessage, SessionDevicePeer, SessionDeviceQueryMessage,
  SessionDeviceResultMessage, SessionServerMessage,
} from './types';
import { MEMBER_DEVICE_ACCESS } from './types';
import { isMemberParty, isOwnerParty, type BrowserParty } from './memberBrowser';

export interface DeviceOffer { tools: MemberDeviceTool[]; label?: string; until: number }

export interface DeviceParty extends BrowserParty {
  deviceOffer?: DeviceOffer;
}

const ACCESS: ReadonlySet<string> = new Set(MEMBER_DEVICE_ACCESS);
const TOOL_NAME = /^[a-z][a-z0-9_]{0,63}$/;
const MAX_TOOLS = 64;
const MAX_DESCRIPTION = 4000;
const MAX_OFFER_BYTES = 192 * 1024;
const MAX_ARGS_BYTES = 64 * 1024;
const MAX_RESULT_BYTES = 1024 * 1024;
/** The longest a device is shared for at a time. The member shares it again for more. */
export const MEMBER_DEVICE_MAX_SHARE_MS = 60 * 60_000;
/** How long a query waits for a tool that declares no deadline. */
export const MEMBER_DEVICE_QUERY_MS = 55_000;
/** The longest any query waits, whatever the tool declares. */
export const MEMBER_DEVICE_MAX_QUERY_MS = 115_000;

/** How long the server waits for one tool: its own deadline and a little more, within the limits. */
export function deviceQueryWait(tool: Pick<MemberDeviceTool, 'timeout'>): number {
  const declared = tool.timeout;
  if (typeof declared !== 'number' || !Number.isFinite(declared) || declared < 0) return MEMBER_DEVICE_QUERY_MS;
  if (declared === 0) return MEMBER_DEVICE_MAX_QUERY_MS;
  return Math.min(declared + 5_000, MEMBER_DEVICE_MAX_QUERY_MS);
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return !!value && typeof value === 'object' && !Array.isArray(value);
}

/**
 * The tools of an offer as the server keeps them, or a reason it takes none.
 * A tool that does not say it only reads is refused, and so is the offer: a
 * device that names one is not telling the truth about the rest.
 */
export function readOfferedTools(raw: unknown): { tools: MemberDeviceTool[] } | { error: string } {
  if (!Array.isArray(raw) || !raw.length) return { error: 'This device offered no tools.' };
  if (raw.length > MAX_TOOLS) return { error: `A device can share ${MAX_TOOLS} tools at most.` };
  const byName = new Map<string, MemberDeviceTool>();
  for (const entry of raw) {
    if (!isRecord(entry) || typeof entry.name !== 'string' || !TOOL_NAME.test(entry.name)) {
      return { error: 'A shared tool needs a name of lower-case letters, digits and underscores.' };
    }
    if (typeof entry.access !== 'string' || !ACCESS.has(entry.access)) {
      return { error: `${entry.name} does not say it only reads, so it cannot be shared.` };
    }
    const tool: MemberDeviceTool = {
      name: entry.name,
      description: typeof entry.description === 'string' ? entry.description.slice(0, MAX_DESCRIPTION) : '',
      inputSchema: isRecord(entry.inputSchema) ? entry.inputSchema : { type: 'object', properties: {} },
      ...(isRecord(entry.outputSchema) ? { outputSchema: entry.outputSchema } : {}),
      ...(typeof entry.timeout === 'number' && Number.isFinite(entry.timeout) && entry.timeout >= 0 ? { timeout: entry.timeout } : {}),
      access: entry.access as MemberDeviceAccess,
    };
    byName.set(tool.name, tool);
  }
  const tools = [...byName.values()].sort((a, b) => a.name.localeCompare(b.name));
  if (JSON.stringify(tools).length > MAX_OFFER_BYTES) return { error: 'The list of shared tools is too large.' };
  return { tools };
}

export function sharedDevicePeers(subs: Iterable<DeviceParty>, ownerId: string, now = Date.now()): SessionDevicePeer[] {
  const peers: SessionDevicePeer[] = [];
  for (const sub of subs) {
    const offer = sub.deviceOffer;
    if (!offer || offer.until <= now || !isMemberParty(sub, ownerId)) continue;
    peers.push({ userId: sub.authorId, clientId: sub.clientId, tools: offer.tools, until: offer.until,
      ...(sub.authorDisplayName ? { displayName: sub.authorDisplayName } : {}),
      ...(offer.label ? { label: offer.label } : {}) });
  }
  return peers.sort((a, b) => a.clientId.localeCompare(b.clientId));
}

interface Pending { requester: string; target: string; timer: ReturnType<typeof setTimeout> }

export class MemberDeviceBroker<S extends DeviceParty> {
  private pending = new Map<string, Pending>();
  private endings = new Map<string, ReturnType<typeof setTimeout>>();

  constructor(
    private readonly subscribers: () => Iterable<S>,
    private readonly send: (sub: S, message: SessionServerMessage) => void,
    private readonly now: () => number = Date.now,
  ) {}

  private find(clientId: string): S | undefined {
    for (const sub of this.subscribers()) if (sub.clientId === clientId) return sub;
    return undefined;
  }

  /** Tell the owner's connections who is sharing a device now. */
  announce(chatId: string, ownerId: string, only?: S): void {
    const peers = sharedDevicePeers(this.subscribers(), ownerId, this.now());
    for (const sub of only ? [only] : this.subscribers()) {
      if (isOwnerParty(sub, ownerId)) this.send(sub, { type: 'session.devicePeers', chatId, peers });
    }
  }

  /** On an owner's subscribe: say who is sharing, when anyone is. */
  greet(sub: S, chatId: string, ownerId: string): void {
    if (isOwnerParty(sub, ownerId) && sharedDevicePeers(this.subscribers(), ownerId, this.now()).length) {
      this.announce(chatId, ownerId, sub);
    }
  }

  offer(sub: S, message: SessionDeviceOfferMessage, ctx: { chatId: string; ownerId: string }): void {
    const refuse = (text: string) => this.send(sub, { type: 'session.error', chatId: ctx.chatId, code: 'unauthorized', message: text });
    if (message.chatId !== ctx.chatId) return refuse('Wrong chat');
    if (!isMemberParty(sub, ctx.ownerId)) {
      return refuse('Only someone invited to this chat, or a teammate in a team chat, can share their device with it.');
    }
    if (message.enabled !== true) {
      this.withdraw(sub, ctx.chatId, ctx.ownerId, 'They stopped sharing their device.', false);
    } else {
      const read = readOfferedTools(message.tools);
      if ('error' in read) return refuse(read.error);
      const now = this.now();
      const asked = typeof message.until === 'number' && Number.isFinite(message.until) ? message.until : now + MEMBER_DEVICE_MAX_SHARE_MS;
      if (asked <= now) return refuse('That sharing has already ended.');
      const until = Math.min(asked, now + MEMBER_DEVICE_MAX_SHARE_MS);
      sub.deviceOffer = { tools: read.tools, until,
        ...(typeof message.label === 'string' && message.label.trim() ? { label: message.label.trim().slice(0, 120) } : {}) };
      this.endAt(sub, ctx.chatId, ctx.ownerId, until);
    }
    this.send(sub, { type: 'session.deviceOffer', chatId: ctx.chatId, enabled: !!sub.deviceOffer,
      ...(sub.deviceOffer ? { until: sub.deviceOffer.until } : {}),
      ...(message.requestId ? { requestId: message.requestId } : {}) });
    this.announce(ctx.chatId, ctx.ownerId);
  }

  /** The sharing ends at the time the member set, whether or not anyone is asking. */
  private endAt(sub: S, chatId: string, ownerId: string, until: number): void {
    const previous = this.endings.get(sub.clientId);
    if (previous) clearTimeout(previous);
    this.endings.set(sub.clientId, setTimeout(() => {
      this.endings.delete(sub.clientId);
      if (!sub.deviceOffer || sub.deviceOffer.until > this.now()) return;
      this.withdraw(sub, chatId, ownerId, 'Their sharing has ended.');
      this.send(sub, { type: 'session.deviceOffer', chatId, enabled: false });
    }, Math.max(0, until - this.now())));
  }

  /** The sharing ends: on the member's word, when their socket closes, when their membership does, or at its end. */
  withdraw(sub: S, chatId: string, ownerId: string, reason: string, announce = true): void {
    const had = !!sub.deviceOffer;
    sub.deviceOffer = undefined;
    const ending = this.endings.get(sub.clientId);
    if (ending) { clearTimeout(ending); this.endings.delete(sub.clientId); }
    for (const [requestId, entry] of this.pending) {
      if (entry.target !== sub.clientId) continue;
      this.finish(requestId, { type: 'session.deviceResult', chatId, requestId, error: reason });
    }
    if (had && announce) this.announce(chatId, ownerId);
  }

  /** A connection has gone: an owner's waiting queries go with it. */
  dropRequester(sub: S): void {
    for (const [requestId, entry] of this.pending) {
      if (entry.requester !== sub.clientId) continue;
      clearTimeout(entry.timer);
      this.pending.delete(requestId);
    }
  }

  query(sub: S, message: SessionDeviceQueryMessage, ctx: { chatId: string; ownerId: string }): void {
    const requestId = typeof message.requestId === 'string' ? message.requestId.slice(0, 128) : '';
    const fail = (error: string) => this.send(sub, { type: 'session.deviceResult', chatId: ctx.chatId, requestId, error });
    if (!requestId || message.chatId !== ctx.chatId || !isOwnerParty(sub, ctx.ownerId)) {
      this.send(sub, { type: 'session.error', chatId: ctx.chatId, code: 'unauthorized',
        message: 'Only the chat owner\'s host can use a member\'s device.' });
      return;
    }
    if (this.pending.has(requestId)) return fail('That request is already waiting.');
    const args = isRecord(message.args) ? message.args : {};
    if (JSON.stringify(args).length > MAX_ARGS_BYTES) return fail('The request is too large.');
    const now = this.now();
    const candidates = [...this.subscribers()].filter(s => s.deviceOffer && s.deviceOffer.until > now
      && isMemberParty(s, ctx.ownerId) && s.authorId === message.userId && (!message.clientId || s.clientId === message.clientId));
    const target = candidates.find(s => s.deviceOffer!.tools.some(t => t.name === message.toolName));
    if (!target) {
      return fail(candidates.length ? `Their device does not share ${message.toolName}.`
        : 'That member is not sharing a device with this chat right now.');
    }
    const tool = target.deviceOffer!.tools.find(t => t.name === message.toolName)!;
    const timer = setTimeout(() => this.finish(requestId, { type: 'session.deviceResult', chatId: ctx.chatId, requestId,
      error: 'Their device did not answer. The app may be closed or in the background.' }), deviceQueryWait(tool));
    this.pending.set(requestId, { requester: sub.clientId, target: target.clientId, timer });
    this.send(target, { type: 'session.deviceQuery', chatId: ctx.chatId, requestId, toolName: message.toolName, args });
  }

  result(sub: S, message: SessionDeviceResultMessage, ctx: { chatId: string }): void {
    const entry = this.pending.get(message.requestId);
    // Only the device that was asked may answer, and only while it still shares.
    if (!entry || entry.target !== sub.clientId || message.chatId !== ctx.chatId || !sub.deviceOffer) return;
    const error = typeof message.error === 'string' ? message.error.slice(0, 2000) : undefined;
    let result = error ? undefined : message.result;
    if (result !== undefined && JSON.stringify(result).length > MAX_RESULT_BYTES) {
      return this.finish(message.requestId, { type: 'session.deviceResult', chatId: ctx.chatId, requestId: message.requestId,
        error: 'The answer was too large to send. Ask for less.' });
    }
    if (result === undefined && !error) result = null;
    this.finish(message.requestId, { type: 'session.deviceResult', chatId: ctx.chatId, requestId: message.requestId,
      ...(error ? { error } : { result }), userId: sub.authorId, clientId: sub.clientId });
  }

  private finish(requestId: string, message: SessionServerMessage): void {
    const entry = this.pending.get(requestId);
    if (!entry) return;
    clearTimeout(entry.timer);
    this.pending.delete(requestId);
    const requester = this.find(entry.requester);
    if (requester) this.send(requester, message);
  }
}

