  greet(sub: S, chatId: string, ownerId: string): void {
    if (isOwnerParty(sub, ownerId) && sharedDevicePeers(this.subscribers(), ownerId, this.now()).length) {
      this.announce(chatId, ownerId, sub);
    }
  }

