import { MEMBER_DEVICE_ACCESS } from './types';
import { isMemberParty, isOwnerParty, type BrowserParty } from './memberBrowser';

export interface DeviceOffer { tools: MemberDeviceTool[]; label?: string; until: number }

export interface DeviceParty extends BrowserParty {
  deviceOffer?: DeviceOffer;
}

