export const MEMBER_DEVICE_QUERY_MS = 55_000;
/** The longest any query waits, whatever the tool declares. */
export const MEMBER_DEVICE_MAX_QUERY_MS = 115_000;

/** How long the server waits for one tool: its own deadline and a little more, within the limits. */
export function deviceQueryWait(tool: Pick<MemberDeviceTool, 'timeout'>): number {
  const declared = tool.timeout;
  if (typeof declared !== 'number' || !Number.isFinite(declared) || declared < 0) return MEMBER_DEVICE_QUERY_MS;
  if (declared === 0) return MEMBER_DEVICE_MAX_QUERY_MS;
  return Math.min(declared + 5_000, MEMBER_DEVICE_MAX_QUERY_MS);
