const cleanup = () => {
  this.typing.clear(sub, chatId);
  // Only remove this subscriber if it's still the one in the map — a
  // later reconnect with the same clientId swaps the entry, and the
  // displaced socket's close event must not evict its successor.
  if (this.subscribers.get(clientId) === sub) {
    this.subscribers.delete(clientId);
  }
  this.memberBrowsers.dropRequester(sub);
  this.memberBrowsers.withdraw(sub, chatId, ownerId, 'Their browser disconnected.');
  this.stopReaperIfEmpty();
};

