  ({ clientId: 'socket', authorId: 'teammate', capabilities: new Set<string>(), ...over });

// A teammate's own device stopped taking a shared Mac's device commands (31 October 2026); their
// browser reaches that Mac's agent the way an invitee's does, by their offer in the chat.
it('counts a teammate in a team chat as a member who may offer, and never as the owner', () => {
  const teammate = party({ departmentAccess: { grant: {} } });
  expect(isMemberParty(teammate, 'owner')).toBe(true);
  expect(isOwnerParty({ ...teammate, authorId: 'owner', capabilities: new Set(['write']) }, 'owner')).toBe(false);
  expect(isMemberParty({ ...teammate, authorId: 'owner' }, 'owner')).toBe(false);
  expect(offeredPeers([{ ...teammate, browserOffer: { tools: ['browser_read_page'] } }], 'owner'))
    .toEqual([{ userId: 'teammate', clientId: 'socket', tools: ['browser_read_page'] }]);
});

it('still counts a named invitee, and still not a bare link or someone with no grant', () => {
  expect(isMemberParty(party({ shareAccess: {}, capabilities: new Set(['discuss']) }), 'owner')).toBe(true);
  expect(isMemberParty(party({ shareAccess: {} }), 'owner')).toBe(false);
  expect(isMemberParty(party(), 'owner')).toBe(false);
});

