import { afterAll, beforeAll, expect, it } from 'vitest';
import { startHarness, type Harness, type WsClient } from './miniflareHarness';
let harness: Harness;
let serial = 0;
beforeAll(async () => { harness = await startHarness(); }, 60_000);
afterAll(async () => { await harness?.close(); });

const TOOLS = ['browser_list_tabs', 'browser_open_tab', 'browser_close_tab', 'browser_read_page', 'browser_run_js'];

async function fixture() {
  const chatId = `member-browser-${++serial}`, ownerId = `owner-mb-${serial}`, token = `member-browser-token-${serial}`;
  await harness.seedChat(ownerId, chatId, []);
  await harness.seedShareToken({
    authorizationVersion: 1, token, scope: 'session', grants: ['read', 'presence'], chatId,
    roomId: `machine:${ownerId}:host`, createdBy: ownerId,
    createdAt: new Date().toISOString(), expiresAt: new Date(Date.now() + 60_000).toISOString(),
    discussionParticipants: { george: 'George Fairhall', sam: 'Sam Other' },
  });
  const sockets: WsClient[] = [];
  const owner = async (clientId = 'host') => {
    const socket = await harness.connect(`/v1/session/${chatId}?testUserId=${ownerId}&clientId=${clientId}`);
    sockets.push(socket); return socket;
  };
  const guest = async (user?: string, clientId = `device-${sockets.length}`) => {
    const socket = await harness.connect(`/v1/session/share/${token}?clientId=${clientId}${user ? `&testUserId=${user}` : ''}`);
    sockets.push(socket); return socket;
  };
  const offer = async (socket: WsClient, tools = TOOLS, label = 'iPhone') => {
    socket.send({ type: 'session.browserOffer', chatId, enabled: true, tools, label, requestId: 'offer' });
    return socket.nextMessage();
  };
  return { chatId, ownerId, owner, guest, offer, close: () => Promise.all(sockets.map(s => s.close())) };
}

it('reaches nothing until the member offers, then tells the owner who is offering', async () => {
  const f = await fixture();
  try {
    const host = await f.owner();
    const george = await f.guest('george', 'george-phone');
    host.send({ type: 'session.browserQuery', chatId: f.chatId, requestId: 'q0', userId: 'george', toolName: 'browser_list_tabs' });
    expect(await host.nextMessage()).toMatchObject({ type: 'session.browserResult', requestId: 'q0', error: expect.stringContaining('not sharing a browser') });

    expect(await f.offer(george)).toMatchObject({ type: 'session.browserOffer', enabled: true, requestId: 'offer' });
    expect(await host.nextMessage()).toEqual({ type: 'session.browserPeers', chatId: f.chatId,
      peers: [{ userId: 'george', clientId: expect.stringMatching(/^share:/), displayName: 'George Fairhall', label: 'iPhone', tools: [...TOOLS].sort() }] });
  } finally { await f.close(); }
});

it('carries a query to the member and her answer back, with her identity stamped by the server', async () => {
  const f = await fixture();
  try {
    const host = await f.owner();
    const george = await f.guest('george', 'george-phone');
    await f.offer(george); await host.nextMessage();
    host.send({ type: 'session.browserQuery', chatId: f.chatId, requestId: 'q1', userId: 'george', toolName: 'browser_read_page', args: { id: 3 } });
    expect(await george.nextMessage()).toEqual({ type: 'session.browserQuery', chatId: f.chatId, requestId: 'q1', toolName: 'browser_read_page', args: { id: 3 } });
    george.send({ type: 'session.browserResult', chatId: f.chatId, requestId: 'q1', result: { title: 'Her page' }, userId: 'spoofed', clientId: 'spoofed' });
    expect(await host.nextMessage()).toEqual({ type: 'session.browserResult', chatId: f.chatId, requestId: 'q1',
      result: { title: 'Her page' }, userId: 'george', clientId: expect.stringMatching(/^share:/) });
    // An error from her browser comes back as an error.
    host.send({ type: 'session.browserQuery', chatId: f.chatId, requestId: 'q2', userId: 'george', toolName: 'browser_run_js', args: { code: '1' } });
    await george.nextMessage();
    george.send({ type: 'session.browserResult', chatId: f.chatId, requestId: 'q2', error: 'No such tab' });
    expect(await host.nextMessage()).toMatchObject({ requestId: 'q2', error: 'No such tab' });
  } finally { await f.close(); }
});

it('lets only the owner ask, and only for the five browser operations', async () => {
  const f = await fixture();
  try {
    const host = await f.owner();
    const george = await f.guest('george', 'george-phone');
    const sam = await f.guest('sam', 'sam-phone');
    await f.offer(george); await host.nextMessage();
    // Another member, and the offering member herself, cannot drive her browser.
    for (const socket of [sam, george]) {
      socket.send({ type: 'session.browserQuery', chatId: f.chatId, requestId: 'x', userId: 'george', toolName: 'browser_list_tabs' });
      expect(await socket.nextMessage()).toMatchObject({ type: 'session.error', code: 'unauthorized' });
    }
    for (const toolName of ['evaluate', 'console_logs', 'screen_frame', 'bash']) {
      host.send({ type: 'session.browserQuery', chatId: f.chatId, requestId: `bad-${toolName}`, userId: 'george', toolName });
      expect(await host.nextMessage()).toMatchObject({ type: 'session.browserResult', requestId: `bad-${toolName}`, error: expect.stringContaining('not a browser operation') });
    }
    host.send({ type: 'session.browserQuery', chatId: f.chatId, requestId: 'sam', userId: 'sam', toolName: 'browser_list_tabs' });
    expect(await host.nextMessage()).toMatchObject({ requestId: 'sam', error: expect.stringContaining('not sharing a browser') });
    host.send({ type: 'session.browserQuery', chatId: f.chatId, requestId: 'big', userId: 'george', toolName: 'browser_run_js', args: { code: 'x'.repeat(70_000) } });
    expect(await host.nextMessage()).toMatchObject({ requestId: 'big', error: expect.stringContaining('too large') });
  } finally { await f.close(); }
});

it('takes an offer only from a named invitee, and only for operations that exist', async () => {
  const f = await fixture();
  try {
    const host = await f.owner();
    for (const socket of [await f.guest(undefined, 'anon'), await f.guest('outsider', 'outsider-phone'), host]) {
      socket.send({ type: 'session.browserOffer', chatId: f.chatId, enabled: true, tools: TOOLS });
      expect(await socket.nextMessage()).toMatchObject({ type: 'session.error', code: 'unauthorized' });
    }
    const george = await f.guest('george', 'george-phone');
    george.send({ type: 'session.browserOffer', chatId: f.chatId, enabled: true, tools: ['evaluate', 'bash'] });
    expect(await george.nextMessage()).toMatchObject({ type: 'session.error', message: expect.stringContaining('no browser to offer') });
    expect(await f.offer(george, ['browser_read_page', 'evaluate'])).toMatchObject({ enabled: true });
    expect(await host.nextMessage()).toMatchObject({ peers: [{ userId: 'george', tools: ['browser_read_page'] }] });
    host.send({ type: 'session.browserQuery', chatId: f.chatId, requestId: 'no-js', userId: 'george', toolName: 'browser_run_js' });
    expect(await host.nextMessage()).toMatchObject({ requestId: 'no-js', error: expect.stringContaining('does not offer that operation') });
  } finally { await f.close(); }
});

it('stops when she says stop, and when her device goes, failing a query that was waiting', async () => {
  const f = await fixture();
  try {
    const host = await f.owner();
    const george = await f.guest('george', 'george-phone');
    await f.offer(george); await host.nextMessage();
    host.send({ type: 'session.browserQuery', chatId: f.chatId, requestId: 'waiting', userId: 'george', toolName: 'browser_list_tabs' });
    await george.nextMessage();
    george.send({ type: 'session.browserOffer', chatId: f.chatId, enabled: false, requestId: 'stop' });
    expect(await george.nextMessage()).toMatchObject({ type: 'session.browserOffer', enabled: false, requestId: 'stop' });
    const afterStop = [await host.nextMessage(), await host.nextMessage()];
    expect(afterStop.find(m => m.type === 'session.browserResult')).toMatchObject({ requestId: 'waiting', error: expect.stringContaining('stopped sharing') });
    expect(afterStop.find(m => m.type === 'session.browserPeers')).toMatchObject({ peers: [] });
    // A late answer after stopping goes nowhere, and a new query is refused.
    george.send({ type: 'session.browserResult', chatId: f.chatId, requestId: 'waiting', result: { tabs: [] } });
    host.send({ type: 'session.browserQuery', chatId: f.chatId, requestId: 'after', userId: 'george', toolName: 'browser_list_tabs' });
    expect(await host.nextMessage()).toMatchObject({ requestId: 'after', error: expect.stringContaining('not sharing a browser') });

    await f.offer(george); expect(await host.nextMessage()).toMatchObject({ peers: [{ userId: 'george' }] });
    await george.close();
    expect(await host.nextMessage()).toMatchObject({ type: 'session.browserPeers', peers: [] });
  } finally { await f.close(); }
});

it('answers only from the browser that was asked, and tells an owner who connects later who is offering', async () => {
  const f = await fixture();
  try {
    const host = await f.owner();
    const george = await f.guest('george', 'george-phone');
    const sam = await f.guest('sam', 'sam-phone');
    await f.offer(george); await host.nextMessage();
    await f.offer(sam); await host.nextMessage();

