import { afterAll, beforeAll, expect, it } from 'vitest';
import { startHarness, type Harness, type WsClient } from './miniflareHarness';
let harness: Harness;
let serial = 0;
beforeAll(async () => { harness = await startHarness(); }, 60_000);
afterAll(async () => { await harness?.close(); });

const tool = (name: string, access: string, extra: Record<string, unknown> = {}) =>
  ({ name, description: `${name} for the test`, inputSchema: { type: 'object', properties: {} }, access, ...extra });
const TOOLS = [tool('theme_server', 'reads', { timeout: 30_000 }), tool('inspect_screen', 'screen')];

async function fixture() {
  const chatId = `member-device-${++serial}`, ownerId = `owner-md-${serial}`, token = `member-device-token-${serial}`;
  await harness.seedChat(ownerId, chatId, []);
  await harness.seedShareToken({
    authorizationVersion: 1, token, scope: 'session', grants: ['read', 'presence'], chatId,
    roomId: `machine:${ownerId}:host`, createdBy: ownerId,
    createdAt: new Date().toISOString(), expiresAt: new Date(Date.now() + 60_000).toISOString(),
    discussionParticipants: { eden: 'Eden Heath', sam: 'Sam Other' },
  });
  const sockets: WsClient[] = [];
  const owner = async (clientId = 'host') => {
    const socket = await harness.connect(`/v1/session/${chatId}?testUserId=${ownerId}&clientId=${clientId}`);
    sockets.push(socket); return socket;
  };
  const guest = async (user?: string, clientId = `device-${sockets.length}`) => {
    const socket = await harness.connect(`/v1/session/share/${token}?clientId=${clientId}${user ? `&testUserId=${user}` : ''}`);
    sockets.push(socket); return socket;
  };
  const share = async (socket: WsClient, tools: unknown[] = TOOLS, extra: Record<string, unknown> = {}) => {
    socket.send({ type: 'session.deviceOffer', chatId, enabled: true, tools, label: 'wac on iPhone', requestId: 'share', ...extra });
    return socket.nextMessage();
  };
  return { chatId, ownerId, owner, guest, share, close: () => Promise.all(sockets.map(s => s.close())) };
}

it('reaches nothing until the member shares, then tells the owner what is shared and until when', async () => {
  const f = await fixture();
  try {
    const host = await f.owner();
    const eden = await f.guest('eden', 'eden-phone');
    host.send({ type: 'session.deviceQuery', chatId: f.chatId, requestId: 'q0', userId: 'eden', toolName: 'theme_server' });
    expect(await host.nextMessage()).toMatchObject({ type: 'session.deviceResult', requestId: 'q0', error: expect.stringContaining('not sharing a device') });

    const before = Date.now();
    const answer = await f.share(eden);
    expect(answer).toMatchObject({ type: 'session.deviceOffer', enabled: true, requestId: 'share' });
    expect(answer.until).toBeGreaterThan(before + 59 * 60_000);
    expect(await host.nextMessage()).toEqual({ type: 'session.devicePeers', chatId: f.chatId, peers: [{
      userId: 'eden', clientId: expect.stringMatching(/^share:/), displayName: 'Eden Heath', label: 'wac on iPhone',
      until: answer.until, tools: [TOOLS[1], TOOLS[0]],
    }] });
  } finally { await f.close(); }
});

it('carries a query to the member and the answer back, with their identity stamped by the server', async () => {
  const f = await fixture();
  try {
