beforeEach(() => { vi.useFakeTimers(); });
afterEach(() => { vi.useRealTimers(); });

const tool = (name: string, access = 'reads', extra: Record<string, unknown> = {}) =>
  ({ name, description: name, inputSchema: { type: 'object', properties: {} }, access, ...extra });

function room() {
  const subs: DeviceParty[] = [];
  const sent: Array<{ to: string; message: SessionServerMessage }> = [];
