  const host: DeviceParty = { clientId: 'host', authorId: 'owner', capabilities: new Set(['write']) };
  const device = (clientId = 'eden-phone'): DeviceParty =>
    ({ clientId, authorId: 'eden', authorDisplayName: 'Eden Heath', capabilities: new Set(['discuss']), shareAccess: {} });
  subs.push(host);
  return { subs, sent, broker, host, device, ctx: { chatId: 'chat', ownerId: 'owner' } };
}

it('keeps the definitions a device declares, and refuses an offer with any tool that does not say it only reads', () => {
  expect(readOfferedTools([tool('theme_server', 'reads', { timeout: 30_000, extra: 'dropped' }), tool('inspect_screen', 'screen')]))
    .toEqual({ tools: [tool('inspect_screen', 'screen'), tool('theme_server', 'reads', { timeout: 30_000 })] });
  expect(readOfferedTools([tool('theme_server'), tool('theme_server_edit', 'changes')])).toEqual({ error: expect.stringContaining('theme_server_edit') });
  expect(readOfferedTools([{ name: 'tap_element' }])).toEqual({ error: expect.stringContaining('tap_element') });
  expect(readOfferedTools([])).toEqual({ error: expect.any(String) });
  expect(readOfferedTools(Array.from({ length: 65 }, (_, i) => tool(`tool_${i}`)))).toEqual({ error: expect.stringContaining('64') });
});

it('waits as long as the tool says it takes, within limits', () => {
  expect(deviceQueryWait({})).toBe(MEMBER_DEVICE_QUERY_MS);
  expect(deviceQueryWait({ timeout: 30_000 })).toBe(35_000);
  expect(deviceQueryWait({ timeout: 0 })).toBe(MEMBER_DEVICE_MAX_QUERY_MS);
  expect(deviceQueryWait({ timeout: 10 * 60_000 })).toBe(MEMBER_DEVICE_MAX_QUERY_MS);
});

