  expect(eden.deviceOffer?.until).toBe(Date.now() + 10 * 60_000);
  r.sent.length = 0;
  vi.advanceTimersByTime(10 * 60_000);
  expect(eden.deviceOffer).toBeUndefined();
  expect(r.sent).toEqual([
