  const r = room();
  const eden = r.device();
  r.subs.push(eden);
  r.broker.offer(eden, { type: 'session.deviceOffer', chatId: 'chat', enabled: true, tools: [tool('theme_server')] }, r.ctx);
  expect(eden.deviceOffer?.until).toBe(Date.now() + MEMBER_DEVICE_MAX_SHARE_MS);
});

it('does not let an old socket closing end the sharing its reconnected successor made', () => {
  const r = room();
  const old = r.device(), renewed = r.device();
  r.subs.push(old);
  r.broker.offer(old, { type: 'session.deviceOffer', chatId: 'chat', enabled: true, tools: [tool('theme_server')], until: Date.now() + 5 * 60_000 }, r.ctx);
  r.subs.splice(r.subs.indexOf(old), 1, renewed);
  r.broker.offer(renewed, { type: 'session.deviceOffer', chatId: 'chat', enabled: true, tools: [tool('theme_server')], until: Date.now() + 5 * 60_000 }, r.ctx);
  r.broker.query(r.host, { type: 'session.deviceQuery', chatId: 'chat', requestId: 'q', userId: 'eden', toolName: 'theme_server' }, r.ctx);
  // The old socket's close arrives after the new one is sharing.
  r.broker.withdraw(old, 'chat', 'owner', 'Their device disconnected.');
  r.sent.length = 0;
  r.broker.result(renewed, { type: 'session.deviceResult', chatId: 'chat', requestId: 'q', result: { count: 0 } }, r.ctx);
  expect(r.sent).toEqual([{ to: 'host', message: expect.objectContaining({ requestId: 'q', result: { count: 0 } }) }]);
  vi.advanceTimersByTime(5 * 60_000);
  expect(renewed.deviceOffer).toBeUndefined();
});

