import { startHarness, type Harness, type WsClient } from './miniflareHarness';
let harness: Harness;
let serial = 0;
beforeAll(async () => { harness = await startHarness(); }, 60_000);
afterAll(async () => { await harness?.close(); });

const tool = (name: string, access: string, extra: Record<string, unknown> = {}) =>
  ({ name, description: `${name} for the test`, inputSchema: { type: 'object', properties: {} }, access, ...extra });
const TOOLS = [tool('theme_server', 'reads', { timeout: 30_000 }), tool('inspect_screen', 'screen')];

async function fixture() {
  const chatId = `member-device-${++serial}`, ownerId = `owner-md-${serial}`, token = `member-device-token-${serial}`;
  await harness.seedChat(ownerId, chatId, []);
  await harness.seedShareToken({
    authorizationVersion: 1, token, scope: 'session', grants: ['read', 'presence'], chatId,
    roomId: `machine:${ownerId}:host`, createdBy: ownerId,
    createdAt: new Date().toISOString(), expiresAt: new Date(Date.now() + 60_000).toISOString(),
    discussionParticipants: { eden: 'Eden Heath', sam: 'Sam Other' },
  });
  const sockets: WsClient[] = [];
  const owner = async (clientId = 'host') => {
    const socket = await harness.connect(`/v1/session/${chatId}?testUserId=${ownerId}&clientId=${clientId}`);
    sockets.push(socket); return socket;
  };
  const guest = async (user?: string, clientId = `device-${sockets.length}`) => {
    const socket = await harness.connect(`/v1/session/share/${token}?clientId=${clientId}${user ? `&testUserId=${user}` : ''}`);
    sockets.push(socket); return socket;
  };
  const share = async (socket: WsClient, tools: unknown[] = TOOLS, extra: Record<string, unknown> = {}) => {
    socket.send({ type: 'session.deviceOffer', chatId, enabled: true, tools, label: 'wac on iPhone', requestId: 'share', ...extra });
    return socket.nextMessage();
  };
  return { chatId, ownerId, owner, guest, share, close: () => Promise.all(sockets.map(s => s.close())) };
}

it('reaches nothing until the member shares, then tells the owner what is shared and until when', async () => {
  const f = await fixture();
  try {
    const host = await f.owner();
    const eden = await f.guest('eden', 'eden-phone');
    host.send({ type: 'session.deviceQuery', chatId: f.chatId, requestId: 'q0', userId: 'eden', toolName: 'theme_server' });
    expect(await host.nextMessage()).toMatchObject({ type: 'session.deviceResult', requestId: 'q0', error: expect.stringContaining('not sharing a device') });

    const before = Date.now();
    const answer = await f.share(eden);
    expect(answer).toMatchObject({ type: 'session.deviceOffer', enabled: true, requestId: 'share' });
    expect(answer.until).toBeGreaterThan(before + 59 * 60_000);
    expect(await host.nextMessage()).toEqual({ type: 'session.devicePeers', chatId: f.chatId, peers: [{
      userId: 'eden', clientId: expect.stringMatching(/^share:/), displayName: 'Eden Heath', label: 'wac on iPhone',
      until: answer.until, tools: [TOOLS[1], TOOLS[0]],
    }] });
  } finally { await f.close(); }
});

it('carries a query to the member and the answer back, with their identity stamped by the server', async () => {
  const f = await fixture();
  try {
    const host = await f.owner();
    const eden = await f.guest('eden', 'eden-phone');
    await f.share(eden); await host.nextMessage();
    host.send({ type: 'session.deviceQuery', chatId: f.chatId, requestId: 'q1', userId: 'eden', toolName: 'theme_server', args: { action: 'local_diff' } });
    expect(await eden.nextMessage()).toEqual({ type: 'session.deviceQuery', chatId: f.chatId, requestId: 'q1', toolName: 'theme_server', args: { action: 'local_diff' } });
    eden.send({ type: 'session.deviceResult', chatId: f.chatId, requestId: 'q1', result: { count: 2 }, userId: 'spoofed', clientId: 'spoofed' });
    expect(await host.nextMessage()).toEqual({ type: 'session.deviceResult', chatId: f.chatId, requestId: 'q1',
      result: { count: 2 }, userId: 'eden', clientId: expect.stringMatching(/^share:/) });
  } finally { await f.close(); }
});

it('lets only the owner ask, and only for a tool the device shares', async () => {
  const f = await fixture();
  try {
    const host = await f.owner();
    const eden = await f.guest('eden', 'eden-phone');
    const sam = await f.guest('sam', 'sam-phone');
    await f.share(eden); await host.nextMessage();
    for (const socket of [sam, eden]) {
      socket.send({ type: 'session.deviceQuery', chatId: f.chatId, requestId: 'x', userId: 'eden', toolName: 'theme_server' });
      expect(await socket.nextMessage()).toMatchObject({ type: 'session.error', code: 'unauthorized' });
    }
    for (const toolName of ['theme_server_edit', 'tap_element', 'evaluate', 'browser_run_js']) {
      host.send({ type: 'session.deviceQuery', chatId: f.chatId, requestId: `bad-${toolName}`, userId: 'eden', toolName });
      expect(await host.nextMessage()).toMatchObject({ requestId: `bad-${toolName}`, error: `Their device does not share ${toolName}.` });
    }
    host.send({ type: 'session.deviceQuery', chatId: f.chatId, requestId: 'sam', userId: 'sam', toolName: 'theme_server' });
    expect(await host.nextMessage()).toMatchObject({ requestId: 'sam', error: expect.stringContaining('not sharing a device') });
    host.send({ type: 'session.deviceQuery', chatId: f.chatId, requestId: 'big', userId: 'eden', toolName: 'theme_server', args: { action: 'x'.repeat(70_000) } });
    expect(await host.nextMessage()).toMatchObject({ requestId: 'big', error: expect.stringContaining('too large') });
  } finally { await f.close(); }
});

it('takes a share only from a named invitee, and only of tools that say they only read', async () => {
  const f = await fixture();
  try {
    const host = await f.owner();
    for (const socket of [await f.guest(undefined, 'anon'), await f.guest('outsider', 'outsider-phone'), host]) {
      socket.send({ type: 'session.deviceOffer', chatId: f.chatId, enabled: true, tools: TOOLS });
      expect(await socket.nextMessage()).toMatchObject({ type: 'session.error', code: 'unauthorized' });
    }
    const eden = await f.guest('eden', 'eden-phone');
    // One tool that changes things, or says nothing about it, and nothing is shared.
    for (const tools of [[...TOOLS, tool('theme_server_edit', 'changes')], [...TOOLS, { name: 'tap_element', description: '' }], []]) {
      eden.send({ type: 'session.deviceOffer', chatId: f.chatId, enabled: true, tools });
      expect(await eden.nextMessage()).toMatchObject({ type: 'session.error', code: 'unauthorized' });
    }
    eden.send({ type: 'session.deviceOffer', chatId: f.chatId, enabled: true, tools: [tool('Bad Name', 'reads')] });
    expect(await eden.nextMessage()).toMatchObject({ type: 'session.error', message: expect.stringContaining('lower-case') });
    // An end in the past is refused; one more than an hour away is held to an hour.
    eden.send({ type: 'session.deviceOffer', chatId: f.chatId, enabled: true, tools: TOOLS, until: Date.now() - 1000 });
    expect(await eden.nextMessage()).toMatchObject({ type: 'session.error', message: expect.stringContaining('already ended') });
    const answer = await f.share(eden, TOOLS, { until: Date.now() + 5 * 60 * 60_000 });
    expect(answer.until).toBeLessThanOrEqual(Date.now() + 60 * 60_000);
    expect(await host.nextMessage()).toMatchObject({ peers: [{ userId: 'eden', until: answer.until }] });
  } finally { await f.close(); }
});

it('stops when they say stop, and when their device goes, failing a query that was waiting', async () => {
  const f = await fixture();
  try {
    const host = await f.owner();
    const eden = await f.guest('eden', 'eden-phone');
    await f.share(eden); await host.nextMessage();
    host.send({ type: 'session.deviceQuery', chatId: f.chatId, requestId: 'waiting', userId: 'eden', toolName: 'theme_server' });
    await eden.nextMessage();
    eden.send({ type: 'session.deviceOffer', chatId: f.chatId, enabled: false, requestId: 'stop' });
    expect(await eden.nextMessage()).toMatchObject({ type: 'session.deviceOffer', enabled: false, requestId: 'stop' });
    const afterStop = [await host.nextMessage(), await host.nextMessage()];
    expect(afterStop.find(m => m.type === 'session.deviceResult')).toMatchObject({ requestId: 'waiting', error: expect.stringContaining('stopped sharing') });
    expect(afterStop.find(m => m.type === 'session.devicePeers')).toMatchObject({ peers: [] });
    // A late answer goes nowhere, and a new query is refused.
    eden.send({ type: 'session.deviceResult', chatId: f.chatId, requestId: 'waiting', result: { count: 1 } });
    host.send({ type: 'session.deviceQuery', chatId: f.chatId, requestId: 'after', userId: 'eden', toolName: 'theme_server' });
    expect(await host.nextMessage()).toMatchObject({ requestId: 'after', error: expect.stringContaining('not sharing a device') });

    await f.share(eden); expect(await host.nextMessage()).toMatchObject({ peers: [{ userId: 'eden' }] });
    await eden.close();
    expect(await host.nextMessage()).toMatchObject({ type: 'session.devicePeers', peers: [] });
  } finally { await f.close(); }
});

it('tells an owner who connects later who is sharing', async () => {
  const f = await fixture();
  try {
    const eden = await f.guest('eden', 'eden-phone');
    await f.share(eden);
    const host = await f.owner('late-host');
    host.send({ type: 'session.subscribe', chatId: f.chatId, tail: 1 });
    let peers: { type?: string; peers?: unknown[] } | undefined;
    for (let i = 0; i < 8 && !peers; i++) {
      const message = await host.nextMessage();
      if (message.type === 'session.devicePeers') peers = message;
    }
    expect(peers).toMatchObject({ peers: [{ userId: 'eden', label: 'wac on iPhone' }] });
  } finally { await f.close(); }
});

