// ---------------------------------------------------------------------------
// An invited member's own browser (memberBrowser.ts)
// ---------------------------------------------------------------------------

/** The browser operations a member can offer. Nothing else crosses. */
export const MEMBER_BROWSER_TOOLS = [
  'browser_list_tabs', 'browser_open_tab', 'browser_close_tab', 'browser_read_page', 'browser_run_js',
  // Shows a tab to the member and waits for them: their own browser, on their own screen.
  'browser_hand_over',
] as const;

/** Member → server: start or stop offering this device's browser. Server → member: the state it now holds. */
export interface SessionBrowserOfferMessage {
  type: 'session.browserOffer';
  chatId: string;
  enabled: boolean;
  tools?: string[];
  label?: string;
  requestId?: string;
}

export interface SessionBrowserPeer {
  userId: string;
  clientId: string;
  displayName?: string;
  label?: string;
  tools: string[];
}

/** Server → the owner's connections: who is offering a browser now. */
export interface SessionBrowserPeersMessage {
  type: 'session.browserPeers';
  chatId: string;
  peers: SessionBrowserPeer[];
}

/** Owner → server names the member; server → member carries only the operation. */
export interface SessionBrowserQueryMessage {
  type: 'session.browserQuery';
  chatId: string;
  requestId: string;
  userId?: string;
  clientId?: string;
  toolName: string;
  args?: Record<string, unknown>;
}

/** Member → server → the owner connection that asked. */
export interface SessionBrowserResultMessage {
  type: 'session.browserResult';
  chatId: string;
  requestId: string;
  result?: unknown;
  error?: string;
  userId?: string;
  clientId?: string;
}

export type SessionClientMessage =
  | SessionTypingMessage
  | SessionSubscribeMessage
  | SessionUnsubscribeMessage
  | SessionPingMessage
  | SessionApplyMessage
  | SessionDiscussionMessage
  | SessionLoadMoreMessage
  | SessionFactsMessage
  | SessionBrowserOfferMessage
  | SessionBrowserQueryMessage
  | SessionBrowserResultMessage
  | SessionTurnStateMessage;

// ---------------------------------------------------------------------------
// Server → client
// ---------------------------------------------------------------------------

export interface SessionSnapshotMessage {
  type: 'session.snapshot';
  chatId: string;

