/** What a shared tool does: reads the app's data, or reads what is on the device's screen. Nothing else is shared. */
export type MemberDeviceAccess = 'reads' | 'screen';

/** One tool a member's device shares: its definition as the device declares it. */
export interface MemberDeviceTool {
  name: string;
  description: string;
  inputSchema: Record<string, unknown>;
  outputSchema?: Record<string, unknown>;
  /** The tool's own deadline in ms; 0 waits as long as the server allows. */
  timeout?: number;
  access: MemberDeviceAccess;
}

/** Member → server: start or stop sharing this device. Server → member: the state it now holds. */
export interface SessionDeviceOfferMessage {
  type: 'session.deviceOffer';
  chatId: string;
  enabled: boolean;
  tools?: MemberDeviceTool[];
  label?: string;
  /** When the sharing ends (ms since the epoch). The server holds it to an hour at most. */
  until?: number;
  requestId?: string;
}

export interface SessionDevicePeer {
  userId: string;
  clientId: string;
  displayName?: string;
  label?: string;
  tools: MemberDeviceTool[];
  until: number;
}

/** Server → the owner's connections: who is sharing a device now. */
export interface SessionDevicePeersMessage {
  type: 'session.devicePeers';
  chatId: string;
  peers: SessionDevicePeer[];
}

/** Owner → server names the member's device; server → that device carries only the tool and its arguments. */
export interface SessionDeviceQueryMessage {
  type: 'session.deviceQuery';
  chatId: string;
  requestId: string;
  userId?: string;
  clientId?: string;
  toolName: string;
  args?: Record<string, unknown>;
}

/** Member's device → server → the owner connection that asked. */
export interface SessionDeviceResultMessage {
  type: 'session.deviceResult';
  chatId: string;
  requestId: string;
  result?: unknown;
  error?: string;
  userId?: string;
  clientId?: string;
}

export type SessionClientMessage =
  | SessionTypingMessage
  | SessionSubscribeMessage
  | SessionUnsubscribeMessage
  | SessionPingMessage
  | SessionApplyMessage
  | SessionDiscussionMessage
  | SessionLoadMoreMessage
  | SessionFactsMessage
  | SessionBrowserOfferMessage
  | SessionBrowserQueryMessage
  | SessionBrowserResultMessage
  | SessionDeviceOfferMessage
  | SessionDeviceQueryMessage
  | SessionDeviceResultMessage
  | SessionTurnStateMessage;

