/**
 * A member's own device, shared with the agent of a chat they were invited to,
 * for reading. The server half is packages/api/src/sessionChannel/memberDevice.ts.
 *
 * Two sides share this file, as with a member's browser (memberBrowser.ts):
 *
 *  - **The member's device.** Nothing is shared until the member says so, per
 *    chat and per device, and the choice is kept on the device. Only tools that
 *    say they only read are shared (`reads`), and those that read the screen
 *    (`screen`) only when the member chose that too. Every request is checked
 *    here again against the device's own tools before it runs. Sharing ends
 *    when the member stops it, at the end they were given (an hour), or when
 *    the server says it has ended.
 *  - **The owner's host.** It learns who is sharing, and sends one tool call
 *    to one member's device.
 */
import type { SessionChannelClient, SessionDeviceFrame } from './SessionChannelClient';
import type { MemberDeviceAccess, MemberDeviceTool, SessionDevicePeer } from './sessionChannelTypes';

const CONSENT_KEY = 'ripul.memberDevice.shared.v1';
/** How long one "share" lasts. The member shares again for more. */
export const MEMBER_DEVICE_SHARE_MS = 60 * 60_000;
/** Longer than the server's own wait for the tool, so its answer (or its timeout) is the one that lands. */
const QUERY_MARGIN_MS = 3_000;
const DEFAULT_QUERY_WAIT_MS = 58_000;
const MAX_QUERY_WAIT_MS = 118_000;

/** A tool as this device knows it: its definition and what it says it does. */
export interface LocalDeviceTool {
  name: string;
  description: string;
  inputSchema: Record<string, unknown>;
  outputSchema?: Record<string, unknown>;
  timeout?: number;
  access?: string;
}

export interface MemberDeviceDeps {
  /** Every tool this device can run now, as its app declares them. */
  tools(): Promise<LocalDeviceTool[]>;
  invoke(toolName: string, args: Record<string, unknown>): Promise<unknown>;
  /** What the owner's agent sees this device as, such as "wac on iPhone". */
  label(): string;
  /** Tell the app which chats can read it now, so it can say so on screen and offer Stop. */
  report(shares: DeviceShareState[]): void;
  /** Keep this chat's socket open while it is shared; returns the release. */
  hold(chatId: string): () => void;
}

/** The member's choice for one chat. */
export interface DeviceConsent { screen: boolean; since: number; until: number }

/** What the app shows for one chat this device is shared with. */
export interface DeviceShareState {
  chatId: string;
  screen: boolean;
  until: number;
  /** Whether the server holds the share now: false while the chat's socket is away. */
  live: boolean;
  lastUse?: { tool: string; at: number };
}

let client: SessionChannelClient | undefined;
let deps: MemberDeviceDeps | undefined;
const peersByChat = new Map<string, SessionDevicePeer[]>();
const waiting = new Map<string, { resolve: (r: { result?: unknown; error?: string }) => void; timer: ReturnType<typeof setTimeout> }>();
const live = new Set<string>();
const holds = new Map<string, () => void>();
const endings = new Map<string, ReturnType<typeof setTimeout>>();
const lastUse = new Map<string, { tool: string; at: number }>();
const listeners = new Set<() => void>();

/** The tools of this device a share may carry: those that only read, and those that read the screen when chosen. */
export function shareableTools(tools: readonly LocalDeviceTool[], screen: boolean): MemberDeviceTool[] {
  const allowed = new Set<string>(screen ? ['reads', 'screen'] : ['reads']);
  return tools.filter(t => typeof t.access === 'string' && allowed.has(t.access)).map(t => ({
    name: t.name, description: t.description, inputSchema: t.inputSchema,
    ...(t.outputSchema ? { outputSchema: t.outputSchema } : {}),
    ...(typeof t.timeout === 'number' ? { timeout: t.timeout } : {}),
    access: t.access as MemberDeviceAccess,
  }));
}

// ── The member's choice ─────────────────────────────────────────────────────

function readConsents(): Record<string, DeviceConsent> {
  try { return JSON.parse(globalThis.localStorage?.getItem(CONSENT_KEY) || '{}') ?? {}; } catch { return {}; }
}

function writeConsents(consents: Record<string, DeviceConsent>): void {
  try { globalThis.localStorage?.setItem(CONSENT_KEY, JSON.stringify(consents)); } catch { /* still applies for this page */ }
}

/** The member's standing choice for this chat, or undefined when it is not shared (or its time is up). */
export function deviceConsent(chatId: string, now = Date.now()): DeviceConsent | undefined {
  const consent = readConsents()[chatId];
  return consent && typeof consent.until === 'number' && consent.until > now ? consent : undefined;
}

export function isSharingDevice(chatId: string): boolean { return !!deviceConsent(chatId); }

export function onMemberDeviceChange(listener: () => void): () => void {
  listeners.add(listener);
  return () => { listeners.delete(listener); };
}

/** The chats this device is shared with now, as the app shows them. */
export function deviceShares(now = Date.now()): DeviceShareState[] {
  return Object.entries(readConsents())
    .filter(([, consent]) => consent.until > now)
    .map(([chatId, consent]) => ({ chatId, screen: consent.screen, until: consent.until, live: live.has(chatId),
      ...(lastUse.get(chatId) ? { lastUse: lastUse.get(chatId) } : {}) }));
}

function changed(): void {
  try { deps?.report(deviceShares()); } catch { /* the app's own view never breaks the channel */ }
  for (const l of listeners) try { l(); } catch { /* a listener never breaks the channel */ }
}

/**
 * The member shares this device with one chat (reading tools, and the screen
 * if they chose it), or stops. Stopping takes effect here at once, whatever the
 * network does: a request that arrives afterwards is refused on this device.
 */
export async function setSharingDevice(chatId: string, choice: { screen: boolean } | null, now = Date.now()): Promise<void> {
  const consents = readConsents();
  if (choice) consents[chatId] = { screen: choice.screen, since: now, until: now + MEMBER_DEVICE_SHARE_MS };
  else delete consents[chatId];
  writeConsents(consents);
  if (!choice) end(chatId);
  else follow(chatId);
  changed();
