  for (const l of listeners) try { l(); } catch { /* a listener never breaks the channel */ }
}

/**
 * The member shares this device with one chat (reading tools, and the screen
 * if they chose it), or stops. Stopping takes effect here at once, whatever the
 * network does: a request that arrives afterwards is refused on this device.
 */
export async function setSharingDevice(chatId: string, choice: { screen: boolean } | null, now = Date.now()): Promise<void> {
  const consents = readConsents();
  if (choice) consents[chatId] = { screen: choice.screen, since: now, until: now + MEMBER_DEVICE_SHARE_MS };
  else delete consents[chatId];
  writeConsents(consents);
  if (!choice) end(chatId);
  else follow(chatId);
  changed();
  await announce(chatId);
}

/** Keep the socket open while shared, and end the sharing on this device at its time. */
function follow(chatId: string): void {
  const consent = deviceConsent(chatId);
  if (!consent || !deps) return;
  if (!holds.has(chatId)) holds.set(chatId, deps.hold(chatId));
  const previous = endings.get(chatId);
  if (previous) clearTimeout(previous);
  endings.set(chatId, setTimeout(() => { void setSharingDevice(chatId, null).catch(() => {}); }, Math.max(0, consent.until - Date.now())));
}

function end(chatId: string): void {
  live.delete(chatId);
  lastUse.delete(chatId);
  const release = holds.get(chatId);
  holds.delete(chatId);
  try { release?.(); } catch { /* the socket goes when it goes */ }
  const ending = endings.get(chatId);
  if (ending) clearTimeout(ending);
  endings.delete(chatId);
}

async function announce(chatId: string): Promise<void> {
  if (!client || !deps) return;
  const consent = deviceConsent(chatId);
  if (!consent) {
    await client.sendDeviceFrame(chatId, { type: 'session.deviceOffer', chatId, enabled: false });
    return;
  }
  const tools = shareableTools(await deps.tools().catch(() => []), consent.screen);
  if (!tools.length) throw new Error('This app has no tools that only read, so there is nothing to share.');
  await client.sendDeviceFrame(chatId, { type: 'session.deviceOffer', chatId, enabled: true, tools, label: deps.label(), until: consent.until });
}

async function answer(chatId: string, requestId: string, toolName: string, args: Record<string, unknown> | undefined): Promise<void> {
  const reply = (body: { result?: unknown; error?: string }) =>
    client?.sendDeviceFrame(chatId, { type: 'session.deviceResult', chatId, requestId, ...body }).catch(() => {});
  // Checked here as well as on the server: this device's own record, and its own tools, are the last word.
  const consent = deviceConsent(chatId);
  if (!consent || !deps) return void reply({ error: 'They are not sharing a device with this chat.' });
  const tools = shareableTools(await deps.tools().catch(() => []), consent.screen);
  if (!tools.some(t => t.name === toolName)) {
    return void reply({ error: `${toolName} is not something this device shares. It shares only tools that read${consent.screen ? ', and its screen' : ''}.` });
  }
  lastUse.set(chatId, { tool: toolName, at: Date.now() });
  changed();
  try {
    await reply({ result: await deps.invoke(toolName, args ?? {}) ?? null });
  } catch (error) {
    await reply({ error: error instanceof Error ? error.message : String(error) });
  }
}

// ── The owner's host ────────────────────────────────────────────────────────

/** Who is sharing a device with this chat now, as last told by the server. */
export function memberDevicePeers(chatId: string, now = Date.now()): SessionDevicePeer[] {
  return (peersByChat.get(chatId) ?? []).filter(p => p.until > now);
}

/** How long the host waits for one tool on a member's device: a little longer than the server does. */
export function memberDeviceWait(tool: Pick<MemberDeviceTool, 'timeout'> | undefined): number {
  const declared = tool?.timeout;
  if (typeof declared !== 'number' || !Number.isFinite(declared) || declared < 0) return DEFAULT_QUERY_WAIT_MS;
  if (declared === 0) return MAX_QUERY_WAIT_MS;
  return Math.min(declared + 5_000 + QUERY_MARGIN_MS, MAX_QUERY_WAIT_MS);
}

/** Run one tool on a member's shared device. Never throws: a failure is an `error`. */
export function queryMemberDevice(
  chatId: string, peer: Pick<SessionDevicePeer, 'userId' | 'clientId' | 'tools'>, toolName: string, args: Record<string, unknown>,
): Promise<{ result?: unknown; error?: string }> {
  if (!client) return Promise.resolve({ error: 'This conversation is not connected.' });
  const requestId = `md_${crypto.randomUUID()}`;
  return new Promise(resolve => {
    const timer = setTimeout(() => {
      waiting.delete(requestId);
      resolve({ error: 'Their device did not answer. The app may be closed or in the background.' });
    }, memberDeviceWait(peer.tools.find(t => t.name === toolName)));
    waiting.set(requestId, { resolve, timer });
    client!.sendDeviceFrame(chatId, {
      type: 'session.deviceQuery', chatId, requestId, userId: peer.userId, clientId: peer.clientId, toolName, args,
    }, true).catch((error: unknown) => {
      if (!waiting.delete(requestId)) return;
      clearTimeout(timer);
      resolve({ error: error instanceof Error ? error.message : String(error) });
    });
  });
}

// ── Wiring ──────────────────────────────────────────────────────────────────

function onFrame(chatId: string, message: SessionDeviceFrame): void {
  switch (message.type) {
    case 'session.devicePeers':
      peersByChat.set(chatId, message.peers ?? []);
      for (const l of listeners) try { l(); } catch { /* a listener never breaks the channel */ }
      return;
    case 'session.deviceOffer':
      if (message.enabled) {
        live.add(chatId);
      } else {
        // The server ended it (its time, or the member's stop elsewhere): so does this device.
        live.delete(chatId);
        if (readConsents()[chatId]) {
          const consents = readConsents();
          delete consents[chatId];
          writeConsents(consents);
          end(chatId);
        }
      }
      changed();
      return;
    case 'session.deviceResult': {
      const entry = waiting.get(message.requestId);
      if (!entry) return;
      clearTimeout(entry.timer);
      waiting.delete(message.requestId);
      entry.resolve(message.error ? { error: message.error } : { result: message.result });
      return;
    }
    case 'session.deviceQuery':
      void answer(chatId, message.requestId, message.toolName, message.args);
      return;
  }
}

/**
 * Attach to the page's session channel. Safe to call again with a new client.
 * Composes with whatever else already listens for the channel opening.
 */
export function installMemberDevice(channel: SessionChannelClient, dependencies: MemberDeviceDeps): void {
  client = channel;
  deps = dependencies;
  channel.onDeviceFrame = onFrame;
  const previous = channel.onChannelOpen;
  // A socket that opens, or reopens, holds no offer: say it again while the member's choice stands.
  channel.onChannelOpen = (chatId) => {
    previous?.(chatId);
    live.delete(chatId);
    peersByChat.delete(chatId);
    if (isSharingDevice(chatId)) void announce(chatId).catch(() => {});
  };
  // Shares made before this page loaded, still within their time.
  for (const share of deviceShares()) follow(share.chatId);
  changed();
}

/** Stop every share on this device, or one chat's: the app's Stop. */
export async function stopSharingDevice(chatId?: string): Promise<void> {
  const chats = chatId ? [chatId] : deviceShares().map(s => s.chatId);
  await Promise.all(chats.map(id => setSharingDevice(id, null).catch(() => {})));
}

export function _resetMemberDeviceForTests(): void {
  client = undefined; deps = undefined;
  peersByChat.clear(); live.clear(); lastUse.clear(); listeners.clear();
  for (const release of holds.values()) try { release(); } catch { /* test */ }
  holds.clear();
  for (const timer of endings.values()) clearTimeout(timer);
  endings.clear();
  for (const entry of waiting.values()) clearTimeout(entry.timer);
  waiting.clear();
}

