/**
 * Wires relay/memberBrowser.ts and relay/memberDevice.ts to this page's session
 * channel, and to the browser and tools this device can run.
 */
import type { SessionChannelClient } from './SessionChannelClient';
import { installMemberBrowser } from './memberBrowser';
import { installMemberDevice, stopSharingDevice } from './memberDevice';
import { getDevicePlatformLabel } from './deviceIdentity';
import { getShareInfoForChat, toLocalChatId } from './chatIdAliasing';

async function invokeLocalTool(toolName: string, args: Record<string, unknown>, failure: string): Promise<unknown> {
  const { handlePeerQuery } = await import('./peerQueryHandlers');
  const response = await handlePeerQuery(`member_${crypto.randomUUID()}`, 'invokeTool', { toolName, args });
  if (!response.success) throw new Error(response.error || failure);
  return response.result;
}

/** What the chat owner's agent sees this device as: "wac on iPhone", or "iPhone" when the app gives no name. */
function deviceLabel(): string {
  const app = (globalThis as { __ripulHostAppName?: unknown }).__ripulHostAppName;
  const platform = getDevicePlatformLabel();
  return typeof app === 'string' && app.trim() ? `${app.trim().slice(0, 60)} on ${platform}` : platform;
}

export function installMemberBrowserOn(client: SessionChannelClient): void {
  installMemberBrowser(client, {
    // The same tools, and the same handlers, this device offers its own account's hosts.
    tools: async () => (await (await import('./peerQueryHandlers')).computeLocalTools()).tools.map(t => t.name),
    invoke: (toolName, args) => invokeLocalTool(toolName, args, 'The browser could not do that.'),
    label: () => getDevicePlatformLabel(),
  });
  installMemberDevice(client, {
    tools: async () => (await (await import('./peerQueryHandlers')).computeLocalTools()).tools,
    invoke: (toolName, args) => invokeLocalTool(toolName, args, 'The device could not do that.'),
    label: deviceLabel,
    report: (shares) => {
      void import('../hosted-app/NativeBridge')
        .then(({ getNativeBridgeInstance }) => getNativeBridgeInstance()?.reportDeviceSharing(shares))
        .catch(() => {});
    },
    // A member's socket carries their invitation: reopen it with that, then keep it from being let go.
    hold: (chatId) => {
      const share = getShareInfoForChat(toLocalChatId(chatId));
      if (share && !client.getSubscribedChatIds().includes(chatId)) {
        try { client.subscribeWithShareToken(share.shareToken, share.sessionChatId); } catch { /* opened when the chat is */ }
      }
      return client.pinSubscription(chatId);
    },
  });
  // The app's Stop, on the banner it shows while this device is shared.
  (globalThis as { __ripulStopDeviceSharing?: (chatId?: string) => Promise<void> }).__ripulStopDeviceSharing =
    (chatId?: string) => stopSharingDevice(chatId);
}

