/**
 * An answered card continues the chat.
 *
 * A browser call that needs someone's say is refused at once and the agent's
 * turn ends there (browserAccess.ts, relay/memberBrowserPrompt.ts). Without
 * this the person answered and nothing happened until somebody typed. The host
 * starts the next turn itself, with a line saying what was answered.
 *
 * The line is sent as RESUME_SENDER, which never counts as who asked: the turn
 * it starts still belongs to whoever asked for the one before it, so a member's
 * request stays a member's request.
 */
import { dispatchLocalCommand, hasLocalCommandContext } from '../relay/localCommandDispatch';
import { RESUME_SENDER } from '../relay/turnRequester';
import type { AccessAnswer } from './browserAccess';

const SENDER_NAME = 'Browser access';

export async function resumeChat(chatId: string, text: string, senderName = SENDER_NAME): Promise<void> {
  if (!hasLocalCommandContext()) {
    console.warn('[BrowserAccess] no host command bridge, so the chat was not continued', chatId);
    return;
  }
  console.log('[BrowserAccess] continuing the chat after an answer', chatId);
  try {
