/**
 * The card that asks an invited member whether to share their device with the
 * chat, for reading.
 *
 * The owner's host puts it in the chat when the owner's turn asks for a
 * member's device that is not shared. Only the member's own device acts on it,
 * and the device that answers is the one shared: answering turns sharing on
 * there (memberDevice.ts), and the offer that device then makes is what the
 * host sees. The answer itself never travels, so nobody else's tap, and nothing
 * the host or the agent does, can turn it on.
 */
import { getBackgroundApi } from '../web/BackgroundApiFactory';
import { logAgentAction } from '../Logger';
import { memberDevicePeers, onMemberDeviceChange, setSharingDevice, shareableTools, type LocalDeviceTool } from './memberDevice';
import { toCanonicalChatId, toLocalChatId } from './chatIdAliasing';
import { resumeChat } from '../frame-bridge/browserAccessResume';

const KEY_PREFIX = 'member_device_share_';
export const SHARE_READING_LABEL = 'Share tools that read';
export const SHARE_WITH_SCREEN_LABEL = 'Share them and the screen';
export const DECLINE_DEVICE_LABEL = 'Not now';
/** An unanswered card closes, and a later call may ask again. */
export const DEVICE_SHARE_CARD_WAIT_MS = 15 * 60_000;
const RESUME_NAME = 'Device sharing';

export function isMemberDeviceShareKey(responseKey: string | undefined): boolean {
  return !!responseKey?.startsWith(KEY_PREFIX);
}

/** `member_device_share_<userId>_<uuid>`: the card says who it is for. */
export function memberOfDeviceShareKey(responseKey: string): string | undefined {
  const rest = responseKey.slice(KEY_PREFIX.length);
  const cut = rest.lastIndexOf('_');
  return cut > 0 ? rest.slice(0, cut) : undefined;
}

export function deviceShareQuestion(name: string, ownerName: string, wanted: readonly string[]): string {
  const what = wanted.length ? ` It wants ${wanted.join(', ')}.` : '';
  return `${name}: the agent in this chat would like to read your device for ${ownerName}'s request.${what} `
    + 'Answer this in the app you want to share, such as wac on your iPhone: that app on that device is the one shared. '
    + 'Only tools that read are shared, never anything that changes your device, and the screen only if you choose it. '
    + 'Only the chat owner\'s requests can use it. It stops when you press Stop, when you close the app, or after an hour.';
}

/** The line that starts the agent's next turn once the member has shared. */
export function memberDeviceSharedLine(name: string, handle: string, label: string): string {
  return `${name} is now sharing ${label} with this chat for reading, as ${handle}. Carry on with what was asked: `
    + `make the device call again with \`device: "${handle}"\`.`;
}

// ── The owner's host ────────────────────────────────────────────────────────

const open = new Map<string, { responseKey: string; timer: ReturnType<typeof setTimeout>; stop: () => void }>();

async function closeCard(chatId: string, responseKey: string, text: string): Promise<void> {
  const backgroundApi = getBackgroundApi();
  if (!backgroundApi) return;
  await logAgentAction(backgroundApi, chatId, {
    method: 'askUserMultiChoice', status: 'success', isMergeable: true,
    toolInvocationId: responseKey, correlationId: responseKey, result: text, data: { answer: text, responseKey },
  }, 'askUserMultiChoice', { correlationId: responseKey, result: text });
}

/**
 * Show the member the card, once while one is open. Returns whether a new card
 * went up. `handleFor` names a shared device the way the agent calls it.
 */
export async function askMemberToShareDevice(
  chatId: string, member: { userId: string; name: string }, ownerName: string, wanted: readonly string[],
  handleFor: (peer: { clientId: string; label?: string }) => string,
): Promise<boolean> {
  const key = `${chatId}|${member.userId}`;
  if (open.has(key)) return false;
  const backgroundApi = getBackgroundApi();
  if (!backgroundApi) throw new Error('The chat is not ready to show a question.');
  const responseKey = `${KEY_PREFIX}${member.userId}_${crypto.randomUUID()}`;
  const canonical = toCanonicalChatId(chatId);
  const finish = (text: string): boolean => {
    const entry = open.get(key);
    if (!entry || entry.responseKey !== responseKey) return false;
    clearTimeout(entry.timer); entry.stop(); open.delete(key);
    void closeCard(chatId, responseKey, text).catch(() => {});
    return true;
  };
  const stop = onMemberDeviceChange(() => {
    const peer = memberDevicePeers(canonical).find(p => p.userId === member.userId);
    if (!peer || !finish(SHARE_READING_LABEL)) return;
    // The agent's turn ended when the call was refused: start the next one. It is still the owner's turn.
    void resumeChat(chatId, memberDeviceSharedLine(member.name, handleFor(peer), peer.label ?? 'their device'), RESUME_NAME);
  });
  open.set(key, { responseKey, stop, timer: setTimeout(() => finish('No answer. The request has closed'), DEVICE_SHARE_CARD_WAIT_MS) });
  const question = deviceShareQuestion(member.name, ownerName, wanted);
  const options = [
    { label: SHARE_READING_LABEL, value: SHARE_READING_LABEL, description: 'This app\'s tools that only read, for an hour. Not your screen.' },
    { label: SHARE_WITH_SCREEN_LABEL, value: SHARE_WITH_SCREEN_LABEL, description: 'Also what is on your screen in this app.' },
    { label: DECLINE_DEVICE_LABEL, value: DECLINE_DEVICE_LABEL, description: 'Nothing is shared.' },
  ];
  try {
    await logAgentAction(backgroundApi, chatId, {
      method: 'askUserMultiChoice', status: 'pending', isMergeable: true, isWorkflowNode: false,
      toolInvocationId: responseKey, correlationId: responseKey,
      args: { message: question, options, multiSelect: false },
      data: { question, header: 'Share your device', options, multiSelect: false, type: 'multiChoice',
        threadId: `member-device-share-${responseKey}`, actionId: `member-device-share-action-${responseKey}`, responseKey,
        forUserId: member.userId, wantTools: [...wanted] },
      persistPayload: true,
    }, 'askUserMultiChoice', { correlationId: responseKey });
  } catch (error) {
    const entry = open.get(key);
    if (entry) { clearTimeout(entry.timer); entry.stop(); open.delete(key); }
    throw error;
  }
  return true;
}

// ── The member's device ─────────────────────────────────────────────────────

/** The tools the card asked for, read from the card itself as this device holds it. */
async function wantedOnCard(chatId: string, responseKey: string): Promise<string[] | undefined> {
  const { ChatActionsManager } = await import('../config/ChatActionsManager');
  for (const id of new Set([chatId, toLocalChatId(chatId), toCanonicalChatId(chatId)])) {
    const actions = await ChatActionsManager.ensureChatLoaded(id).catch(() => [] as unknown[]);
    for (const action of actions as Array<{ correlationId?: string; data?: { wantTools?: unknown } }>) {
      if (action?.correlationId !== responseKey) continue;
      const wanted = action.data?.wantTools;
      if (Array.isArray(wanted)) return wanted.filter((t): t is string => typeof t === 'string');
    }
  }
  return undefined;
}

/**
 * The member answered the card on this device. Only the person it names may,
 * and only in an app that has what the agent asked for: answered in another
 * app, that app would be the one shared, and it would have none of it.
 */
export async function answerDeviceShareCard(
  chatId: string, responseKey: string, answer: string, currentUserId: string | null | undefined,
  localTools: () => Promise<LocalDeviceTool[]>,
): Promise<void> {
  const forUser = memberOfDeviceShareKey(responseKey);
  if (!forUser || !currentUserId || forUser !== currentUserId) {
    throw new Error('This question is for the person it names. Only they can answer it, on their own device.');
  }
  const canonical = toCanonicalChatId(chatId);
  if (answer !== SHARE_READING_LABEL && answer !== SHARE_WITH_SCREEN_LABEL) {
    await setSharingDevice(canonical, null);
    return;
  }
  const screen = answer === SHARE_WITH_SCREEN_LABEL;
  const here = shareableTools(await localTools(), screen).map(t => t.name);
  if (!here.length) {
    throw new Error('This app has no tools that only read, so there is nothing here to share. Answer in the app the agent needs, such as wac.');
  }
  const wanted = await wantedOnCard(chatId, responseKey);
  if (wanted?.length && !wanted.some(name => here.includes(name))) {
    throw new Error(`This app does not have ${wanted.join(', ')}. Open this chat in the app that has it, such as wac on your iPhone, and answer there.`);
  }
  await setSharingDevice(canonical, { screen });
}

export function _resetDeviceShareCardsForTests(): void {
  for (const entry of open.values()) { clearTimeout(entry.timer); entry.stop(); }
  open.clear();
}

