/** The per-install/per-tab suffix of a relay clientId (`controller-USERID-SUFFIX`), without any window part. */
function clientIdSuffix(clientId: string): string {
  const parts = deviceIdOf(clientId).split('-');
  return parts.length > 1 ? parts[parts.length - 1] : clientId;
}

/** Platform token out of a displayName's trailing parenthetical, e.g. `iPhone`. */
function platformSlug(displayName: string | undefined): string {
  const m = displayName?.match(/\(([^)]+)\)\s*$/);
  const raw = m?.[1]?.replace(/[^A-Za-z0-9]/g, '') ?? '';
  return raw ? raw.toLowerCase() : 'device';
}

/**
 * Stable, unique, readable handle for a peer — `iphone-c603`.
 *
 * Uniqueness rides on the clientId suffix (the relay's own key), so this is as
 * unique as the clientId while staying short enough to type or say. Derived, not
 * stored: no protocol change, and it cannot drift out of sync with the roster.
 */
export function deviceHandleFor(peer: IdentifiablePeer): string {
  const suffix = clientIdSuffix(peer.clientId);
  return `${platformSlug(peer.displayName)}-${suffix.slice(0, 4).toLowerCase()}`;
}
