import { conversationModesOffered } from './conversationModesGate';
import { isMacSessionId } from '../standalone/macSessionIdentity';
import { toCanonicalChatId } from './chatIdAliasing';
import type { ConversationMode } from '../LLM/multiParticipant/conversationMode';
import { readStoredPairings } from './storedPairings';

// Only authenticated invitation membership drives routing, never connected devices.
export interface ConversationPerson { id: string; name: string; imageUrl?: string }
const emptyPeople: readonly ConversationPerson[] = [];
const people = new Map<string, readonly ConversationPerson[]>();
export function conversationPeople(chatId: string): readonly ConversationPerson[] {
  return people.get(conversationMembershipIdentity(chatId).key) ?? emptyPeople;
}
const membership = new Map<string, boolean>();
const pending = new Map<string, Promise<void>>();
const listeners = new Set<() => void>();
export function conversationMembershipIdentity(chatId: string) {
  const canonicalId = toCanonicalChatId(chatId);
  let shareToken: string | undefined;
  try {
    const pairings = readStoredPairings<any>();
    shareToken = pairings.find((p: any) => p.chatId === chatId || p.tabId === chatId || p.hostChatId === canonicalId || p.chatId === canonicalId)?.shareToken;
  } catch { /* Storage may be unavailable. */ }
  const userId = (globalThis as any).window?.Clerk?.user?.id ?? '';
  return { canonicalId, shareToken, key: JSON.stringify([userId, canonicalId, shareToken]) };
}
export function hasOtherHumans(chatId: string): boolean | undefined {
  if (isMacSessionId(chatId)) return false;
  return membership.get(conversationMembershipIdentity(chatId).key);
}
export function effectiveConversationMode(mode: ConversationMode, otherHumans: boolean | undefined): ConversationMode {
  // Preserve a saved Group choice while offline or still checking membership.
  return otherHumans === false ? 'agent' : mode;
}
export function showConversationMode(mode: ConversationMode, otherHumans: boolean | undefined): boolean {
  // A view context that does not offer the switcher hides it regardless of who
  // else is in the conversation. Routing for an existing Group chat is unchanged.
  if (!conversationModesOffered()) return false;
  return otherHumans === true || (otherHumans === undefined && mode === 'group');
}
export function subscribeMembership(listener: () => void): () => void {
  listeners.add(listener);
  return () => { listeners.delete(listener); };
}

