export async function refreshConversationMembership(chatId: string, afterPending = false): Promise<void> {
  if (isMacSessionId(chatId)) return;
  const { canonicalId, shareToken, key } = conversationMembershipIdentity(chatId);
  if (pending.has(key)) {
    await pending.get(key);
    if (!afterPending) return;
    // An invite can land while the old solo lookup is still in flight.
    // Its response cannot satisfy the post-invitation refresh.
    return refreshConversationMembership(chatId);
  }
  const request = (async () => {
    try {
      const roster = await getSessionChannelClient()?.getParticipantRoster(canonicalId, shareToken);
      if (!roster) return;
      let changed = false;
      if (typeof roster.hasOtherHumans === 'boolean' && membership.get(key) !== roster.hasOtherHumans) {
        membership.set(key, roster.hasOtherHumans);
        changed = true;
      }
      if (Array.isArray(roster.participants) && JSON.stringify(people.get(key)) !== JSON.stringify(roster.participants)) {
        people.set(key, roster.participants);
        changed = true;
      }
      if (changed) for (const listener of listeners) listener();
    } catch { /* A failed lookup must not reroute an existing Group message to an agent. */ }
  })();
  pending.set(key, request);
  try { await request; } finally { pending.delete(key); }
}
