function platformOf(label: string | undefined): string {
  const match = label?.match(/(iPhone|iPad|Mac|Web)( Simulator)?\s*$/);
  return match ? `${match[1]}${match[2] ?? ''}`.replace(/\s+/g, '').toLowerCase() : 'device';
}

/** Each device shared with this chat now, with the handle a call names it by. */
export function sharedMemberDevices(chatId: string): SharedMemberDevice[] {
  const peers = memberDevicePeers(toCanonicalChatId(chatId));
  const base = peers.map(p => `${memberBrowserHandle(p.userId)}-${platformOf(p.label)}`);
  return peers.map((peer, i) => {
    const twin = base.filter(b => b === base[i]).length > 1;
    const tail = peer.clientId.replace(/[^a-zA-Z0-9]/g, '').slice(-4).toLowerCase();
    return { ...peer, memberHandle: memberBrowserHandle(peer.userId), handle: twin ? `${base[i]}-${tail}` : base[i] };
  });
}

/** What a shared device is called where a person reads it: "Eden Heath's wac on iPhone". */
export function sharedDeviceLabel(device: Pick<SharedMemberDevice, 'displayName' | 'label'>): string {
  return `${device.displayName ?? 'A member'}'s ${device.label ?? 'device'}`;
}

/** The chat's shared devices as tool sources, beside its own devices'. Each source's id is its handle. */
export function memberDeviceSources(chatId: string): Array<{ id: string; label: string; tools: MemberDeviceTool[] }> {
  return sharedMemberDevices(chatId).map(device => ({
    id: device.handle, label: `${sharedDeviceLabel(device)}, shared with this chat for reading`, tools: device.tools,
  }));
}

/** device_list_targets: what this chat can read of its members' devices, and who could be asked. */
export async function describeMemberDevices(chatId: string): Promise<{
  sharedWithThisChat: unknown[];
  membersWhoCanShare: unknown[];
  note: string;
}> {
  await refreshConversationMembership(chatId).catch(() => {});
  const shared = sharedMemberDevices(chatId);
  const sharing = new Set(shared.map(d => d.userId));
  return {
    sharedWithThisChat: shared.map(d => ({
      handle: d.handle, label: sharedDeviceLabel(d), sharedBy: d.displayName ?? null,
      reads: d.tools.filter(t => t.access === 'reads').map(t => t.name),
      screen: d.tools.filter(t => t.access === 'screen').map(t => t.name),
      until: new Date(d.until).toISOString(),
    })),
    membersWhoCanShare: conversationPeople(chatId)
      .map(p => ({ userId: p.id.replace(/^human-/, ''), name: p.name }))
      .filter(p => !sharing.has(p.userId))
      .map(p => ({ member: p.name, handle: memberBrowserHandle(p.userId) })),
    note: 'A device a member shares is read with `device: "<its handle>"`, only in the chat owner\'s own turns, and only '
      + 'with the tools it shares, which only read. To ask a member who is not sharing, call the tool you need with '
      + '`device: "<their handle>"`: they are asked in the chat, and nothing runs until they share.',
  };
}

function decorate(result: unknown, device: SharedMemberDevice): unknown {
  const body = result && typeof result === 'object' && !Array.isArray(result) ? result as Record<string, unknown> : { value: result };
  return { ...body, _device: device.handle, _deviceLabel: sharedDeviceLabel(device),
    _notice: `This ran on ${sharedDeviceLabel(device)}, which they shared with this chat for reading.` };
}

/**
 * A device tool call that names a member's device or a member. Returns
 * undefined when it names neither, so the call goes on to the owner's devices.
 */
export async function executeOnMemberDevice(
  chatId: string, selector: string | undefined, toolName: string, args: Record<string, unknown>,
  ownerName: () => string,
): Promise<{ result?: unknown; error?: string; chatId: string } | undefined> {
  if (!isMemberDeviceSelector(selector)) return undefined;
  const wanted = selector!;
  const requester = invitedRequesterFor(chatId) ?? teamRequesterFor(chatId);
  if (requester) {
    return { error: `${wanted} is a member's own device. It is used only in the chat owner's own turns, and `
      + `${requester.name} asked for this one. Nothing ran.`, chatId };
  }
  const shared = sharedMemberDevices(chatId);
  const exact = shared.find(d => d.handle === wanted);
  const theirs = exact ? [exact] : shared.filter(d => d.memberHandle === wanted);
  if (theirs.length > 1) {
    return { error: `${wanted} shares more than one device with this chat. Name one: ${theirs.map(d => `${d.handle} (${d.label ?? 'device'})`).join(', ')}.`, chatId };
  }
  const device = theirs[0];
  if (device) {
    const tool = device.tools.find(t => t.name === toolName);
    if (!tool) {
      return { error: `${sharedDeviceLabel(device)} does not share ${toolName}. It shares only tools that read: `
        + `${device.tools.map(t => t.name).join(', ')}. Nothing ran.`, chatId };
    }
    const answer = await queryMemberDevice(toCanonicalChatId(chatId), device, toolName, args);
    if (answer.error !== undefined) return { error: `${sharedDeviceLabel(device)} (${device.handle}): ${answer.error}`, chatId };
    return { result: decorate(answer.result, device), chatId };
  }
  // A member, or a device that is no longer shared: ask the member, when they are in this chat.
  await refreshConversationMembership(chatId).catch(() => {});
  const memberHandle = wanted.split('-').slice(0, 2).join('-');
  const person = conversationPeople(chatId).map(p => ({ userId: p.id.replace(/^human-/, ''), name: p.name }))
    .find(p => memberBrowserHandle(p.userId) === memberHandle);
  if (!person) {
    return { error: `No member of this chat goes by ${wanted}. device_list_targets lists the members who can share a device.`, chatId };
  }
  const how = await askMemberToShareDevice(chatId, person, ownerName(), [toolName], peer => {
    const fresh = sharedMemberDevices(chatId).find(d => d.clientId === peer.clientId);
    return fresh?.handle ?? `${memberHandle}-${platformOf(peer.label)}`;
  }).then(asked => asked ? 'has now been asked' : 'was asked already and has not answered yet')
    .catch(error => { console.warn('[MemberDevice] could not ask the member', error); return 'could not be asked from here'; });
  return { error: `${person.name} is not sharing a device with this chat, so nothing ran. ${person.name} ${how} in this chat, `
    + 'on a card they answer in the app to be shared. Say in the chat what you need to read and why, then stop and wait: '
    + 'the chat carries on by itself once they share.', chatId };
}

