vi.mock('../web/BackgroundApiFactory', () => ({ getBackgroundApi: () => ({}) }));
vi.mock('./chatIdAliasing', () => ({
  toCanonicalChatId: (id: string) => id.replace(/^shared_/, ''),
  toLocalChatId: (id: string) => `shared_${id}`,
}));
const resumed = vi.hoisted(() => [] as Array<{ chatId: string; text: string }>);
vi.mock('../frame-bridge/browserAccessResume', () => ({
  resumeChat: vi.fn(async (chatId: string, text: string) => { resumed.push({ chatId, text }); }),
}));
const cards = vi.hoisted(() => new Map<string, any[]>());
vi.mock('../config/ChatActionsManager', () => ({ ChatActionsManager: { getChatActions: (id: string) => cards.get(id) ?? [] } }));

import {
  MEMBER_DEVICE_SHARE_MS, deviceConsent, installMemberDevice, isSharingDevice, memberDevicePeers, memberDeviceWait,
  queryMemberDevice, setSharingDevice, shareableTools, stopSharingDevice, _resetMemberDeviceForTests, type LocalDeviceTool,
} from './memberDevice';
import {
  answerDeviceShareCard, askMemberToShareDevice, DECLINE_DEVICE_LABEL, SHARE_READING_LABEL, SHARE_WITH_SCREEN_LABEL,
  _resetDeviceShareCardsForTests,
} from './memberDevicePrompt';

const tool = (name: string, access?: string, extra: Partial<LocalDeviceTool> = {}): LocalDeviceTool =>
  ({ name, description: `${name} tool`, inputSchema: { type: 'object', properties: {} }, ...(access ? { access } : {}), ...extra });
const WAC_TOOLS = [
  tool('theme_server', 'reads', { timeout: 30_000 }), tool('theme_server_edit', 'changes'), tool('inspect_screen', 'screen'),
  tool('tap_element'), tool('evaluate'),
];
const EDEN = { userId: 'user_3JgEden', name: 'Eden Heath' };

function fakeChannel() {
  const sent: any[] = [];
  const channel: any = {
    sent,
    sendDeviceFrame: vi.fn(async (chatId: string, message: any, open?: boolean) => { sent.push({ chatId, open: !!open, ...message }); }),
    receive: (chatId: string, message: any) => channel.onDeviceFrame(chatId, message),
    open: (chatId: string) => channel.onChannelOpen(chatId),
  };
  return channel;
}
const localTools = vi.fn(async () => WAC_TOOLS);
const invoke = vi.fn(async (toolName: string, args: Record<string, unknown>) => ({ ran: toolName, args }));
const reports: any[] = [];
const held: string[] = [];
const released: string[] = [];
const flush = () => vi.advanceTimersByTimeAsync(0);

let channel: ReturnType<typeof fakeChannel>;
beforeEach(() => {
  vi.useFakeTimers();
  const store = new Map<string, string>();
  vi.stubGlobal('localStorage', { getItem: (k: string) => store.get(k) ?? null, setItem: (k: string, v: string) => { store.set(k, v); },
    removeItem: (k: string) => { store.delete(k); }, length: 0, key: () => null });
  _resetMemberDeviceForTests(); _resetDeviceShareCardsForTests();
  logged.length = 0; resumed.length = 0; reports.length = 0; held.length = 0; released.length = 0; cards.clear();
  invoke.mockClear(); localTools.mockClear();
  channel = fakeChannel();
  installMemberDevice(channel, {
    tools: localTools, invoke, label: () => 'wac on iPhone', report: shares => reports.push(shares),
    hold: chatId => { held.push(chatId); return () => released.push(chatId); },
  });
});
afterEach(() => { vi.useRealTimers(); vi.unstubAllGlobals(); });

describe('what may be shared', () => {
  it('takes only tools that say they only read, and those that read the screen only when chosen', () => {
    expect(shareableTools(WAC_TOOLS, false).map(t => t.name)).toEqual(['theme_server']);
    expect(shareableTools(WAC_TOOLS, true).map(t => t.name)).toEqual(['theme_server', 'inspect_screen']);
    expect(shareableTools(WAC_TOOLS, false)[0]).toEqual({ name: 'theme_server', description: 'theme_server tool',
      inputSchema: { type: 'object', properties: {} }, timeout: 30_000, access: 'reads' });
  });
});

describe('the member\'s device', () => {
  it('shares nothing, and answers nothing, until the member says so', async () => {
    expect(isSharingDevice('chat')).toBe(false);
    channel.open('chat');
    await flush();
    expect(channel.sent).toEqual([]);
    channel.receive('chat', { type: 'session.deviceQuery', chatId: 'chat', requestId: 'q', toolName: 'theme_server', args: {} });
    await flush();
    expect(invoke).not.toHaveBeenCalled();
    expect(channel.sent).toEqual([expect.objectContaining({ type: 'session.deviceResult', requestId: 'q', error: expect.stringContaining('not sharing') })]);
  });

  it('shares the tools that read for an hour, keeps the chat open, and tells the app', async () => {
    await setSharingDevice('chat', { screen: false });
    expect(deviceConsent('chat')).toMatchObject({ screen: false, until: Date.now() + MEMBER_DEVICE_SHARE_MS });
    expect(channel.sent).toEqual([{ chatId: 'chat', open: false, type: 'session.deviceOffer', enabled: true, label: 'wac on iPhone',
      until: Date.now() + MEMBER_DEVICE_SHARE_MS, tools: [expect.objectContaining({ name: 'theme_server', access: 'reads' })] }]);
    expect(held).toEqual(['chat']);
    expect(reports.at(-1)).toEqual([{ chatId: 'chat', screen: false, until: Date.now() + MEMBER_DEVICE_SHARE_MS, live: false }]);
    channel.receive('chat', { type: 'session.deviceOffer', chatId: 'chat', enabled: true, until: Date.now() + MEMBER_DEVICE_SHARE_MS });
    expect(reports.at(-1)[0].live).toBe(true);
  });

  it('runs a shared tool, and refuses one it does not share even if the server passed it on', async () => {
    await setSharingDevice('chat', { screen: false });
    channel.sent.length = 0;
    channel.receive('chat', { type: 'session.deviceQuery', chatId: 'chat', requestId: 'ok', toolName: 'theme_server', args: { action: 'local_diff' } });
    await flush();
    expect(invoke).toHaveBeenCalledWith('theme_server', { action: 'local_diff' });
    expect(channel.sent.at(-1)).toMatchObject({ type: 'session.deviceResult', requestId: 'ok', result: { ran: 'theme_server' } });
    expect(reports.at(-1)[0].lastUse).toMatchObject({ tool: 'theme_server' });
    for (const toolName of ['theme_server_edit', 'tap_element', 'evaluate', 'inspect_screen']) {
      invoke.mockClear();
      channel.receive('chat', { type: 'session.deviceQuery', chatId: 'chat', requestId: toolName, toolName, args: {} });
      await flush();
      expect(invoke).not.toHaveBeenCalled();
      expect(channel.sent.at(-1)).toMatchObject({ requestId: toolName, error: expect.stringContaining('not something this device shares') });
    }
  });

  it('stops at once when the member says stop, whatever the network does', async () => {
    await setSharingDevice('chat', { screen: true });
    channel.sendDeviceFrame.mockRejectedValueOnce(new Error('This conversation is not connected.'));
    await stopSharingDevice('chat');
    expect(isSharingDevice('chat')).toBe(false);
    expect(released).toEqual(['chat']);
    expect(reports.at(-1)).toEqual([]);
    channel.receive('chat', { type: 'session.deviceQuery', chatId: 'chat', requestId: 'late', toolName: 'theme_server', args: {} });
    await flush();
    expect(invoke).not.toHaveBeenCalled();
  });

