    channel.receive('chat', { type: 'session.deviceOffer', chatId: 'chat', enabled: true, until: Date.now() + MEMBER_DEVICE_SHARE_MS });
    expect(reports.at(-1)[0].live).toBe(true);
  });

  it('runs a shared tool, and refuses one it does not share even if the server passed it on', async () => {
    await setSharingDevice('chat', { screen: false });
    channel.sent.length = 0;
    channel.receive('chat', { type: 'session.deviceQuery', chatId: 'chat', requestId: 'ok', toolName: 'theme_server', args: { action: 'local_diff' } });
    await flush();
    expect(invoke).toHaveBeenCalledWith('theme_server', { action: 'local_diff' });
    expect(channel.sent.at(-1)).toMatchObject({ type: 'session.deviceResult', requestId: 'ok', result: { ran: 'theme_server' } });
    expect(reports.at(-1)[0].lastUse).toMatchObject({ tool: 'theme_server' });
    for (const toolName of ['theme_server_edit', 'tap_element', 'evaluate', 'inspect_screen']) {
      invoke.mockClear();
      channel.receive('chat', { type: 'session.deviceQuery', chatId: 'chat', requestId: toolName, toolName, args: {} });
      await flush();
      expect(invoke).not.toHaveBeenCalled();
      expect(channel.sent.at(-1)).toMatchObject({ requestId: toolName, error: expect.stringContaining('not something this device shares') });
    }
  });

  it('stops at once when the member says stop, whatever the network does', async () => {
    await setSharingDevice('chat', { screen: true });
    channel.sendDeviceFrame.mockRejectedValueOnce(new Error('This conversation is not connected.'));
    await stopSharingDevice('chat');
    expect(isSharingDevice('chat')).toBe(false);
    expect(released).toEqual(['chat']);
    expect(reports.at(-1)).toEqual([]);
    channel.receive('chat', { type: 'session.deviceQuery', chatId: 'chat', requestId: 'late', toolName: 'theme_server', args: {} });
    await flush();
    expect(invoke).not.toHaveBeenCalled();
  });

  it('ends at its time, and when the server says it has ended', async () => {
    await setSharingDevice('chat', { screen: false });
    await vi.advanceTimersByTimeAsync(MEMBER_DEVICE_SHARE_MS);
    expect(isSharingDevice('chat')).toBe(false);
    expect(channel.sent.at(-1)).toMatchObject({ type: 'session.deviceOffer', enabled: false });
    expect(released).toEqual(['chat']);

    await setSharingDevice('other', { screen: false });
    channel.receive('other', { type: 'session.deviceOffer', chatId: 'other', enabled: false });
    expect(isSharingDevice('other')).toBe(false);
    expect(released).toEqual(['chat', 'other']);
  });

  it('shares again when its socket reopens, but not once its time is up', async () => {
    await setSharingDevice('chat', { screen: false });
    channel.sent.length = 0;
    channel.open('chat');
    await flush();
    expect(channel.sent).toEqual([expect.objectContaining({ type: 'session.deviceOffer', enabled: true })]);
    await vi.advanceTimersByTimeAsync(MEMBER_DEVICE_SHARE_MS);
    channel.sent.length = 0;
    channel.open('chat');
    await flush();
    expect(channel.sent).toEqual([]);
  });

  it('refuses to share an app with no tools that only read', async () => {
    localTools.mockResolvedValueOnce([tool('tap_element'), tool('evaluate', 'changes')]);
    await expect(setSharingDevice('chat', { screen: true })).rejects.toThrow(/no tools that only read/);
  });
});

describe('the owner\'s host', () => {
