    const until = Date.now() + 30 * 60_000;
    const peer = { userId: EDEN.userId, clientId: 'share:abc', displayName: EDEN.name, label: 'wac on iPhone', until,
      tools: shareableTools(WAC_TOOLS, false) };
    channel.receive('chat', { type: 'session.devicePeers', chatId: 'chat', peers: [peer] });
    expect(memberDevicePeers('chat')).toEqual([peer]);
    const answer = queryMemberDevice('chat', peer, 'theme_server', { action: 'status' });
    await flush();
    const query = channel.sent.at(-1);
    expect(query).toMatchObject({ type: 'session.deviceQuery', open: true, userId: EDEN.userId, clientId: 'share:abc', toolName: 'theme_server', args: { action: 'status' } });
    channel.receive('chat', { type: 'session.deviceResult', chatId: 'chat', requestId: query.requestId, result: { source: 'local' } });
    await expect(answer).resolves.toEqual({ result: { source: 'local' } });
    // Past its time, a share is not listed whatever the server last said.
    vi.setSystemTime(until + 1);
    expect(memberDevicePeers('chat')).toEqual([]);
  });

  it('waits for a tool as long as it declares, and says so when the device does not answer', async () => {
    expect(memberDeviceWait({ timeout: 30_000 })).toBe(38_000);
    expect(memberDeviceWait(undefined)).toBe(58_000);
    const peer = { userId: EDEN.userId, clientId: 'share:abc', tools: shareableTools(WAC_TOOLS, false) };
    const answer = queryMemberDevice('chat', peer, 'theme_server', {});
    await vi.advanceTimersByTimeAsync(38_000);
    await expect(answer).resolves.toEqual({ error: expect.stringContaining('did not answer') });
  });
});

describe('the card', () => {
  const key = (userId = EDEN.userId) => `member_device_share_${userId}_1234`;

  it('is answered only by the person it names, on their own device', async () => {
    await expect(answerDeviceShareCard('chat', key(), SHARE_READING_LABEL, 'user_someoneElse', localTools)).rejects.toThrow(/person it names/);
    await expect(answerDeviceShareCard('chat', key(), SHARE_READING_LABEL, null, localTools)).rejects.toThrow(/person it names/);
    expect(isSharingDevice('chat')).toBe(false);
  });

  it('shares what the member chose: the tools that read, or those and the screen', async () => {
    await answerDeviceShareCard('shared_chat', key(), SHARE_READING_LABEL, EDEN.userId, localTools);
    expect(deviceConsent('chat')).toMatchObject({ screen: false });
    await answerDeviceShareCard('shared_chat', key(), SHARE_WITH_SCREEN_LABEL, EDEN.userId, localTools);
    expect(deviceConsent('chat')).toMatchObject({ screen: true });
    await answerDeviceShareCard('shared_chat', key(), DECLINE_DEVICE_LABEL, EDEN.userId, localTools);
    expect(isSharingDevice('chat')).toBe(false);
  });

  it('is not answered in an app without what the agent asked for, which would be the one shared', async () => {
    cards.set('shared_chat', [{ correlationId: key(), data: { wantTools: ['theme_server'] } }]);
    const ripulApp = async () => [tool('get_app_diagnostics', 'reads'), tool('tap_element')];
    await expect(answerDeviceShareCard('shared_chat', key(), SHARE_READING_LABEL, EDEN.userId, ripulApp))
      .rejects.toThrow(/does not have theme_server/);
    expect(isSharingDevice('chat')).toBe(false);
    await answerDeviceShareCard('shared_chat', key(), SHARE_READING_LABEL, EDEN.userId, localTools);
    expect(isSharingDevice('chat')).toBe(true);
  });

  it('goes up once for the member, and the chat carries on when they share', async () => {
    const handleFor = () => 'member-3jgede-iphone';
    expect(await askMemberToShareDevice('chat', EDEN, 'Peter Maude', ['theme_server'], handleFor)).toBe(true);
    expect(await askMemberToShareDevice('chat', EDEN, 'Peter Maude', ['theme_server'], handleFor)).toBe(false);
    expect(logged).toHaveLength(1);
    expect(logged[0]).toMatchObject({ status: 'pending', data: { forUserId: EDEN.userId, wantTools: ['theme_server'] } });
    expect(logged[0].data.question).toMatch(/Peter Maude's request/);
    channel.receive('chat', { type: 'session.devicePeers', chatId: 'chat', peers: [{ userId: EDEN.userId, clientId: 'share:abc',
      label: 'wac on iPhone', until: Date.now() + 60_000, tools: shareableTools(WAC_TOOLS, false) }] });
    await flush();
    expect(logged.at(-1)).toMatchObject({ status: 'success' });
    expect(resumed).toEqual([{ chatId: 'chat', text: expect.stringContaining('device: "member-3jgede-iphone"') }]);
  });
});

