const device = vi.hoisted(() => ({
  memberDevicePeers: vi.fn((): any[] => []),
  queryMemberDevice: vi.fn(),
}));
vi.mock('../relay/memberDevice', () => device);
const prompt = vi.hoisted(() => ({ askMemberToShareDevice: vi.fn(async () => true) }));
vi.mock('../relay/memberDevicePrompt', () => prompt);
const members = vi.hoisted(() => ({
  conversationPeople: vi.fn(() => [{ id: 'human-user_3JgEden', name: 'Eden Heath' }]),
  refreshConversationMembership: vi.fn(async () => {}),
}));
vi.mock('../relay/conversationMembership', () => members);

import { describeMemberDevices, executeOnMemberDevice, memberDeviceSources, sharedMemberDevices } from './memberDeviceRoute';
import { noteHostRoom, recordTurnRequester } from '../relay/turnRequester';
import { _resetToolStateMemory, _setToolStateBackendForTests } from './toolCatalog';

const reads = (name: string, timeout?: number) =>
  ({ name, description: name, inputSchema: { type: 'object', properties: {} }, access: 'reads' as const, ...(timeout ? { timeout } : {}) });
const EDEN_PHONE = { userId: 'user_3JgEden', clientId: 'share:1111-aaaa', displayName: 'Eden Heath', label: 'wac on iPhone',
  until: Date.now() + 60 * 60_000, tools: [reads('theme_server', 30_000)] };
const owner = () => 'Peter Maude';

beforeEach(() => {
  vi.stubGlobal('localStorage', { getItem: () => null, setItem: () => {}, length: 0, key: () => null, removeItem: () => {} });
  _resetToolStateMemory();
  _setToolStateBackendForTests({ load: async () => ({}), save: async () => {}, remove: async () => {} });
  device.memberDevicePeers.mockReturnValue([EDEN_PHONE]);
  device.queryMemberDevice.mockReset();
  prompt.askMemberToShareDevice.mockClear();
  noteHostRoom('machine:user_3AOwner:machine-B62369AD');
  recordTurnRequester('chat', 'controller-user_3AOwner-ABCD1234', 'Peter Maude', undefined, 'user_3AOwner');
});
afterEach(() => vi.unstubAllGlobals());

it('names a shared device by its member and platform, and lists its tools beside the chat\'s own devices', () => {
  expect(sharedMemberDevices('chat').map(d => d.handle)).toEqual(['member-3jgede-iphone']);
  expect(memberDeviceSources('chat')).toEqual([{ id: 'member-3jgede-iphone',
    label: 'Eden Heath\'s wac on iPhone, shared with this chat for reading', tools: EDEN_PHONE.tools }]);
  // Two iPhones of one member are told apart.
  device.memberDevicePeers.mockReturnValue([EDEN_PHONE, { ...EDEN_PHONE, clientId: 'share:2222-bbbb' }]);
  expect(sharedMemberDevices('chat').map(d => d.handle)).toEqual(['member-3jgede-iphone-aaaa', 'member-3jgede-iphone-bbbb']);
});

it('leaves a call that names no member device to the owner\'s devices', async () => {
  expect(await executeOnMemberDevice('chat', undefined, 'theme_server', {}, owner)).toBeUndefined();
  expect(await executeOnMemberDevice('chat', 'iphone-c603', 'theme_server', {}, owner)).toBeUndefined();
});

it('runs an owner\'s call on the shared device it names, by its handle or the member\'s', async () => {
  device.queryMemberDevice.mockResolvedValue({ result: { count: 2 } });
  for (const selector of ['member-3jgede-iphone', 'member-3jgede']) {
    const outcome = await executeOnMemberDevice('chat', selector, 'theme_server', { action: 'local_diff' }, owner);
    expect(outcome?.result).toMatchObject({ count: 2, _device: 'member-3jgede-iphone', _deviceLabel: 'Eden Heath\'s wac on iPhone' });
  }
  expect(device.queryMemberDevice).toHaveBeenCalledWith('chat', expect.objectContaining({ clientId: 'share:1111-aaaa' }),
    'theme_server', { action: 'local_diff' });
});

it('refuses a tool the device does not share, and runs nothing', async () => {
  const outcome = await executeOnMemberDevice('chat', 'member-3jgede-iphone', 'theme_server_edit', { action: 'discard_local' }, owner);
  expect(outcome?.error).toMatch(/does not share theme_server_edit\. It shares only tools that read: theme_server/);
  expect(device.queryMemberDevice).not.toHaveBeenCalled();
});

it('is never used in a turn a member asked for', async () => {
  recordTurnRequester('chat', 'participant:user_3JgEden', 'Eden Heath');
  const outcome = await executeOnMemberDevice('chat', 'member-3jgede-iphone', 'theme_server', {}, owner);
  expect(outcome?.error).toMatch(/only in the chat owner's own turns/);
  expect(device.queryMemberDevice).not.toHaveBeenCalled();
});

it('asks a member who is not sharing, and runs nothing', async () => {
  device.memberDevicePeers.mockReturnValue([]);
  const outcome = await executeOnMemberDevice('chat', 'member-3jgede', 'theme_server', { action: 'local_diff' }, owner);
  expect(prompt.askMemberToShareDevice).toHaveBeenCalledWith('chat', { userId: 'user_3JgEden', name: 'Eden Heath' }, 'Peter Maude',
    ['theme_server'], expect.any(Function));
  expect(outcome?.error).toMatch(/Eden Heath is not sharing a device with this chat, so nothing ran/);
  expect(device.queryMemberDevice).not.toHaveBeenCalled();
  expect((await executeOnMemberDevice('chat', 'member-zzzzzz', 'theme_server', {}, owner))?.error).toMatch(/No member of this chat/);
});

it('lists what is shared and who could be asked', async () => {
  members.conversationPeople.mockReturnValue([{ id: 'human-user_3JgEden', name: 'Eden Heath' }, { id: 'human-user_3KSam', name: 'Sam Other' }]);
  const listed = await describeMemberDevices('chat');
  expect(listed.sharedWithThisChat).toEqual([expect.objectContaining({ handle: 'member-3jgede-iphone', sharedBy: 'Eden Heath', reads: ['theme_server'], screen: [] })]);
  expect(listed.membersWhoCanShare).toEqual([{ member: 'Sam Other', handle: 'member-er3ksam' }]);
});

