import Foundation
import WebKit

/// What came back from asking the page to run one of its callables.
///
/// The page can fail to answer in two ways that callers treat differently:
/// there is no web view yet, or the call threw. Both leave `value` nil;
/// `failure(detached:)` says which, in words a caller can hand on.
struct PageReply {
    enum Outcome {
        /// The page answered, possibly with nothing.
        case answered(Any?)
        /// No web view is attached.
        case detached
        /// The call threw.
        case failed(Error)
    }

    let outcome: Outcome

    /// The page's answer. Nil when it answered nothing, when no web view is
    /// attached and when the call threw.
    var value: Any? {
        if case .answered(let value) = outcome { return value }
        return nil
    }

    var dictionary: [String: Any]? { value as? [String: Any] }

    /// The answer carries `success: true`.
    var succeeded: Bool { dictionary?["success"] as? Bool == true }

    var isDetached: Bool {
        if case .detached = outcome { return true }
        return false
    }

    var error: Error? {
        if case .failed(let error) = outcome { return error }
        return nil
    }

    /// Why there is no answer to read: `detached` when no web view is attached,
    /// the error's own words when the call threw. Nil when the page answered.
    func failure(detached: String = "webView is nil") -> String? {
        switch outcome {
        case .answered: return nil
        case .detached: return detached
        case .failed(let error): return error.localizedDescription
        }
    }
}

extension AgentBridge {
    /// What a call answers when the page has not defined the callable.
    enum PageStandIn {
        /// `window.f?.(…) ?? literal`. The literal also replaces a null answer.
        case orElse(String)
        /// `if (!window.f) return literal`. A null answer stays null.
        case ifMissing(String)
        /// A missing callable answers nothing.
        case nothing
    }

    /// Where a thrown call is written, as "[AgentBridge] <caller> error: <why>".
    enum PageFailureLog {
        case nslog
        /// The bridge console, which the log tools read.
        case console
        /// The caller reports it, or nobody needs to hear.
        case none
    }

    /// An argument the callable should see as `undefined`. Nil arrives as `null`,
    /// and the two differ wherever the page forwards the value or defaults it.
    struct PageUndefined {}
    static let undefinedArgument = PageUndefined()

    /// Run `window.<function>(arguments…)` in the page and await its answer.
    ///
    /// Arguments are bound, never pasted into the script, so their content
    /// cannot change what the script does.

import Foundation

// MARK: - NativeTool Protocol
//
// Conform to this protocol to expose any native API as a tool the agent can call.
//
// Naming convention:
//   pick_*      Interactive picker — presents native UI, waits for user selection.
//               Result is shown as a confirmation card in the agent chat.
//               Must return `name` (String) or `value` ([String: Any]) for display.
//   get_*/list_*  Read data — fetches info for the agent.
//   create_*/setup_*/delete_*  Write action — modifies app state.
//   run_*       Replays a developer-recorded workflow (a macro — see
//               `docs/plans/automation-macros/`), synthesized from data rather
//               than hand-coded. Named `run_macro_<slug>`.

public protocol NativeTool {
    /// Tool identifier using snake_case. Prefix drives agent behaviour (see above).
    var name: String { get }
    var description: String { get }
    var inputSchema: [String: Any] { get }
    /// Optional output schema describing the fields returned by this tool.
    /// When provided, the agent sees a "Returns:" section in the tool description
    /// so it can construct correct `$ref` paths in sequential chains.
    /// Build with `ToolSchema.object(...)` just like `inputSchema`.
    var outputSchema: [String: Any]? { get }
    /// Timeout in seconds for this tool. `0` means no timeout (wait indefinitely).
    /// Default is `30`. Override per-tool for slower operations.
    var timeout: TimeInterval { get }
    func execute(args: [String: Any]) async throws -> Any
}

public extension NativeTool {
    var outputSchema: [String: Any]? { nil }
    var timeout: TimeInterval { 30 }

    /// MCP-formatted definition sent to the agent during discovery.
    var definition: [String: Any] {
        var def: [String: Any] = [
            "name": name,
            "description": description,
            "inputSchema": inputSchema,
        ]
        if let outputSchema {
            def["outputSchema"] = outputSchema
        }
        def["timeout"] = Int(timeout * 1000) // milliseconds for JS
        return def
    }

