import UIKit
import SwiftUI
import RipulAgent

// DEVELOPER tools for the theme pipeline and screen navigation — so theme state is read and
// changed through formal, inspectable operations instead of guessed from pixels or driven by
// blind taps. Registered `.developer` beside the functional-test tools (WACNativeTools).

private struct ThemeToolError: LocalizedError {
    let errorDescription: String?
    init(_ message: String) { errorDescription = message }
}

/// Read every scene window, including overlays omitted by inspect_screen. A blank overlay
/// can cover WAC while its own window still reports Home. Do not load controllers' views,
/// capture pixels, or include user-facing text in this structural diagnostic.
@MainActor
enum WACWindowDiagnostics {
    static var snapshot: [String: Any] {
        let scenes = UIApplication.shared.connectedScenes.compactMap { $0 as? UIWindowScene }
        let root = appDelegate.window?.rootViewController
        return [
            "appRoot": root.map { controller($0) } ?? [:],
            "scenes": scenes.map { scene in
                ["activationState": scene.activationState.rawValue,
                 "windows": scene.windows.map { window in
                     ["class": String(describing: type(of: window)),
                      "isWACWindow": window === appDelegate.window,
                      "isKeyWindow": window.isKeyWindow,
                      "level": window.windowLevel.rawValue,
                      "hidden": window.isHidden,
                      "alpha": window.alpha,
                      "frame": NSCoder.string(for: window.frame),
                      "root": window.rootViewController.map { controller($0) } ?? [:],
                      "subviews": window.subviews.map { view($0) }] as [String: Any]
                 }] as [String: Any]
            }
        ]
    }

    private static func view(_ view: UIView) -> [String: Any] {
        ["class": String(describing: type(of: view)),
         "id": view.accessibilityIdentifier ?? "",
         "frame": NSCoder.string(for: view.frame),
         "hidden": view.isHidden,
         "alpha": view.alpha,
         "background": view.backgroundColor?.description ?? "none",
         "subviewCount": view.subviews.count]
    }

    private static func controller(_ controller: UIViewController, depth: Int = 0) -> [String: Any] {
        var result: [String: Any] = ["class": String(describing: type(of: controller)),
                                   "viewLoaded": controller.isViewLoaded]
        if let loadedView = controller.viewIfLoaded { result["view"] = view(loadedView) }
        guard depth < 8 else { return result }
        if let presented = controller.presentedViewController {
            result["presented"] = self.controller(presented, depth: depth + 1)
        }
        if let nav = controller as? UINavigationController {
            result["visibleController"] = nav.visibleViewController.map { String(describing: type(of: $0)) } ?? "none"
        }
        if let tab = controller as? UITabBarController { result["selectedTab"] = tab.selectedIndex }
        result["children"] = controller.children.map { self.controller($0, depth: depth + 1) }
        return result
    }
}

// MARK: - theme_server

/// The published server theme (wac-v1) versus what this phone runs and what the build ships.
struct ThemeServerTool: NativeTool {
    let name = "theme_server"
    let description = """
    DEVELOPER. Inspect and manage the published app theme (wac-v1), which every phone runs in \
    preference to the theme shipped in the build. action=status: the running source, remote origin \
    and version, local override, sign-in, and hubRowShowsCard as running / shipped / server. \
    action=diff: every path where the server document differs from the shipped Theme.json (0 = in \
    lockstep; jobKindCatalogue is excluded — it has its own publication flow). \
    action=local_diff: this phone's UNPUBLISHED editor edits versus the server version they were \
    taken from — what the person changed locally, path by path. \
    action=discard_local: drop those local edits and run the server theme again. \
    action=publish_shipped (dry_run to preview): make the server theme EQUAL the build's shipped \
    Theme.json (jobKindCatalogue kept as on the server), schema-validated, conditional on the version \
    read — keeps source and online in lockstep; affects EVERY phone following wac-v1. \
    action=publish_setting (key, value_json; dry_run to preview): changes ONE top-level key of the \
    LIVE server document, keeping everything else, validated against WAC's schema, conditional on \
    the version read (a concurrent publish is refused), then adopted on this phone — affects EVERY \
    phone following wac-v1; signs in with the WAC login (a WAC App site designer) or the Ripul assistant. action=use_shipped: \
    this phone runs the shipped defaults (persists across relaunch; server untouched). \
    action=follow_server: back to the server theme, checking for a newer version.
    """
    let inputSchema = ToolSchema.object(
        .string("action", "status | diff | local_diff | discard_local | publish_setting | publish_shipped | use_shipped | follow_server; default status"),
        .string("key", "publish_setting: top-level theme key, e.g. hubRowShowsCard"),
        .string("value_json", "publish_setting: the new value as JSON, e.g. true, \"card\", {\"a\":1}"),
        .bool("dry_run", "publish_setting / publish_shipped: report the change without publishing (default false)")
    )
    let outputSchema: [String: Any]? = nil
    let timeout: TimeInterval = 30

    @MainActor
    func execute(args: [String: Any]) async throws -> Any {
        switch args["action"] as? String ?? "status" {
        case "status":
            var result = ThemeProvider.themeDiagnostics
            result["serverStatus"] = await WACServerTheme.refreshStatus().summary
            return result
        case "diff":
            let diff = try await WACServerTheme.diffAgainstShipped()
            return ["serverVersion": diff.etag ?? "", "differences": diff.entries, "count": diff.entries.count] as [String: Any]
        case "publish_setting":
            guard let key = args["key"] as? String, !key.isEmpty else { throw ThemeToolError("publish_setting requires key") }
            guard let raw = args["value_json"] as? String,
                  let value = try? JSONSerialization.jsonObject(with: Data(raw.utf8), options: [.fragmentsAllowed]) else {
                throw ThemeToolError("publish_setting requires value_json (valid JSON)")
            }
            if args["dry_run"] as? Bool == true {
                return try await WACServerTheme.previewChange(setting: key, to: value)
            }
            try await WACServerTheme.publish(setting: key, to: value)
            var result = ThemeProvider.themeDiagnostics
            result["published"] = ["key": key, "value": value]
            return result
        case "local_diff":
            return try WACServerTheme.localDiff()
        case "discard_local":
            ThemeProvider.resetToAuthoritativeTheme()
            var result = ThemeProvider.themeDiagnostics
            result["localEditsRemaining"] = try WACServerTheme.localDiff()["count"] ?? 0
            return result
        case "publish_shipped":
            if args["dry_run"] as? Bool == true {
                return try await WACServerTheme.previewShippedPublish()
            }
            try await WACServerTheme.publishShipped()
            let drift = try await WACServerTheme.diffAgainstShipped()
            var result = ThemeProvider.themeDiagnostics
            result["lockstepDifferences"] = drift.entries
            result["serverVersion"] = drift.etag ?? ""
            return result
        case "use_shipped":
            try ThemeProvider.useShippedTheme()
            return ThemeProvider.themeDiagnostics
        case "follow_server":
            ThemeProvider.resetToAuthoritativeTheme()
            return ThemeProvider.themeDiagnostics
        default:
            throw ThemeToolError("Unknown action")
        }
    }
}

// MARK: - hub_style

/// The resolved hub row style (card / flat) of every hub screen, and per-screen withdrawals.
struct HubStyleTool: NativeTool {
    let name = "hub_style"
    let description = """
    DEVELOPER. Hub row style across every hub screen. action=status: the global switch \
    (hubRowShowsCard) and, per hub scope, its override (or follow) and resolved style. \
    action=set (scope, style=card|flat|follow): withdraw one hub screen from the global switch, or \
    return it to follow. action=set_global (style=card|flat): flip the switch. set/set_global are a \
    LOCAL edit on this phone, kept as its unpublished theme draft (theme_server local_diff lists it, \
    discard_local drops it) until Review & Publish sends it; theme_server publish_setting changes \
    one setting for every phone directly.
    """
    let inputSchema = ToolSchema.object(
        .string("action", "status | set | set_global; default status"),
        .string("scope", "set: a hub scope id from status"),
        .string("style", "card | flat | follow (follow only for set)")
    )
    let outputSchema: [String: Any]? = nil
    let timeout: TimeInterval = 10

    @MainActor

