    let description = """
    DEVELOPER. Reads the published app theme (wac-v1), which every phone runs in preference to the \\
    theme shipped in the build. Changes nothing. action=status: the running source, remote origin \\
    and version, local override, sign-in, and hubRowShowsCard as running / shipped / server. \\
    action=diff: every path where the server document differs from the shipped Theme.json (0 = in \\
    lockstep; jobKindCatalogue is excluded — it has its own publication flow). \\
    action=local_diff: this phone's UNPUBLISHED editor edits versus the server version they were \\
    taken from — what the person changed locally, path by path. theme_server_edit makes changes.
    """
    let inputSchema = ToolSchema.object(
        .string("action", "status | diff | local_diff; default status")
    )
    let outputSchema: [String: Any]? = nil
    let timeout: TimeInterval = 30
    let access: NativeToolAccess = .reads

