            throw ThemeToolError("Unknown action")
        }
    }
}

/// Changes the theme: this phone's (its draft, or which theme it runs) or the published one
/// every phone follows. `discard_local`, `use_shipped`, `follow_server` and `publish_*` all
/// delete this phone's unpublished theme draft.
struct ThemeServerEditTool: NativeTool {
    let name = "theme_server_edit"
    let description = """
    DEVELOPER. Changes the app theme. Every action here deletes this phone's unpublished editor \\
    edits (theme_server local_diff lists them first). action=discard_local: drop those local edits and \\
    run the server theme again. action=publish_shipped (dry_run to preview): make the server theme EQUAL \\
    the build's shipped Theme.json (jobKindCatalogue kept as on the server), schema-validated, \\
    conditional on the version read — keeps source and online in lockstep; affects EVERY phone \\
    following wac-v1. action=publish_setting (key, value_json; dry_run to preview): changes ONE \\
    top-level key of the LIVE server document, keeping everything else, validated against WAC's \\
    schema, conditional on the version read (a concurrent publish is refused), then adopted on this \\
    phone — affects EVERY phone following wac-v1; signs in with the WAC login (a WAC App site \\
    designer) or the Ripul assistant. action=use_shipped: this phone runs the shipped defaults \\
    (persists across relaunch; server untouched). action=follow_server: back to the server theme, \\
    checking for a newer version.
    """
    let inputSchema = ToolSchema.object(
        .string("action", "discard_local | publish_setting | publish_shipped | use_shipped | follow_server"),
        .string("key", "publish_setting: top-level theme key, e.g. hubRowShowsCard"),
        .string("value_json", "publish_setting: the new value as JSON, e.g. true, \\"card\\", {\\"a\\":1}"),
        .bool("dry_run", "publish_setting / publish_shipped: report the change without publishing (default false)")
    )
    let outputSchema: [String: Any]? = nil
    let timeout: TimeInterval = 30

    @MainActor
    func execute(args: [String: Any]) async throws -> Any {
        switch args["action"] as? String ?? "" {
        case "publish_setting":
            guard let key = args["key"] as? String, !key.isEmpty else { throw ThemeToolError("publish_setting requires key") }
            guard let raw = args["value_json"] as? String,
                  let value = try? JSONSerialization.jsonObject(with: Data(raw.utf8), options: [.fragmentsAllowed]) else {
                throw ThemeToolError("publish_setting requires value_json (valid JSON)")
            }
            if args["dry_run"] as? Bool == true {
                return try await WACServerTheme.previewChange(setting: key, to: value)
            }
            try await WACServerTheme.publish(setting: key, to: value)
            var result = ThemeProvider.themeDiagnostics
            result["published"] = ["key": key, "value": value]
            return result
        case "discard_local":
            ThemeProvider.resetToAuthoritativeTheme()
            var result = ThemeProvider.themeDiagnostics
            result["localEditsRemaining"] = try WACServerTheme.localDiff()["count"] ?? 0
            return result
        case "publish_shipped":
            if args["dry_run"] as? Bool == true {
                return try await WACServerTheme.previewShippedPublish()
            }
            try await WACServerTheme.publishShipped()
            let drift = try await WACServerTheme.diffAgainstShipped()
            var result = ThemeProvider.themeDiagnostics
            result["lockstepDifferences"] = drift.entries
            result["serverVersion"] = drift.etag ?? ""
            return result
        case "use_shipped":
            try ThemeProvider.useShippedTheme()
            return ThemeProvider.themeDiagnostics
        case "follow_server":
            ThemeProvider.resetToAuthoritativeTheme()
            return ThemeProvider.themeDiagnostics
        default:
            throw ThemeToolError("Unknown action. Reading the theme is theme_server's.")
        }
    }
}

