package io.ripul.sdk.agent

import io.ripul.sdk.agent.capabilities.CapabilityError
import io.ripul.sdk.agent.capabilities.CapabilityRouter
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch
import kotlinx.serialization.json.Json
import kotlinx.serialization.json.JsonArray
import kotlinx.serialization.json.JsonElement
import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.JsonPrimitive
import kotlinx.serialization.json.buildJsonObject
import kotlinx.serialization.json.contentOrNull
import kotlinx.serialization.json.put
import java.util.UUID
import java.util.concurrent.CopyOnWriteArrayList

/**
 * The native side of the `agent-framework:*` protocol (twin of iOS `AgentBridge`, the part an SDK
 * app needs; chrome-extension `src/frame-bridge/protocol.ts`, docs/NATIVE-BRIDGE-ARCHITECTURE.md):
 *
 * - **handshake** → `handshake:ack` with the capabilities, then the tools (`mcp:tools`).
 * - **capability:ping** → `capability:pong` (the web's NativeBridgedContext connects this way).
 * - **host:info**, **mcp:discover** → the host and the tools.
 * - **mcp:invoke** → runs the native tool and answers `mcp:result` or `mcp:error`.
 * - **capability** → runs a [CapabilityRouter] handler and answers `capability:response`.
 * - **link:open** → [onOpenLink] when the app takes it, else an http, https, mailto or tel address
 *   opens outside the app ([openExternally], set by AgentWebView).
 *
 * Anything else reaches [onMessage]. Web → native arrives as JSON text through [handleMessage];
 * native → web leaves through [evaluate] as `window.__agentBridgeReceive(<json>)`, which
 * AgentWebView's start script turns into a `message` event from `ripul-native://app`.
 */
class AgentBridge(private val scope: CoroutineScope) {
    /** Runs JavaScript in the page; set by AgentWebView, null while there is no page. */
    @Volatile var evaluate: ((String) -> Unit)? = null

    /** Every message the bridge doesn't answer itself: type without the prefix, and the message. */
    @Volatile var onMessage: ((String, JsonObject) -> Unit)? = null

    /** The app's own handling of a link the page asks to open; return true when it took it. */
    @Volatile var onOpenLink: ((String) -> Boolean)? = null

    /** Opens an address outside the app (the browser, mail, the dialler); set by AgentWebView. */
    @Volatile var openExternally: ((String) -> Unit)? = null

    val capabilityRouter = CapabilityRouter()

    /** Extra capabilities merged into the handshake (`llm`, `searchClick`, …). */
    val extraCapabilities = LinkedHashMap<String, Boolean>()

    private val _isConnected = MutableStateFlow(false)
    /** The page has shaken hands (or pinged) since it last loaded. */
    val isConnected: StateFlow<Boolean> = _isConnected.asStateFlow()

    private val registered = CopyOnWriteArrayList<NativeTool>()
    val tools: List<NativeTool> get() = registered.toList()

    /** Adds [tool] (replacing one of the same name) and tells a connected page. */
    fun register(tool: NativeTool) {
        registered.removeAll { it.name == tool.name }
        registered += tool
        broadcastToolsIfConnected()
    }

    fun unregister(name: String) {
        if (registered.removeAll { it.name == name }) broadcastToolsIfConnected()
    }

    fun tool(named: String): NativeTool? = registered.firstOrNull { it.name == named }

    private val toolDefinitions: JsonArray get() = JsonArray(registered.map { it.definition })

    /** A new page is loading: it must shake hands again. */
    fun pageWillLoad() { _isConnected.value = false }

    // MARK: - Web → native

    /** One message from the page, as the JSON text it posted. Ignores anything not `agent-framework:*`. */
    fun handleMessage(json: String) {
        val message = runCatching { Json.parseToJsonElement(json) as? JsonObject }.getOrNull() ?: return
        val type = message.str("type") ?: return
        if (!type.startsWith(PREFIX)) return
        when (val kind = type.removePrefix(PREFIX)) {
            "handshake" -> handshake()
            "capability:ping" -> capabilityPing(message)
            "host:info" -> send("host:info:response", message.str("requestId") ?: newId()) {
                put("url", HOST_ORIGIN); put("title", HOST_TITLE); put("origin", HOST_ORIGIN)
            }
            "mcp:discover" -> send("mcp:tools", message.str("requestId") ?: newId()) { put("tools", toolDefinitions) }
            "mcp:invoke" -> invoke(message)
            "capability" -> capability(message)
            "link:open" -> message.str("url")?.let { openLink(it) }
            else -> onMessage?.invoke(kind, message)
        }
    }

    private fun handshake() {
        val caps = buildJsonObject {
            put("mcp", true); put("dom", false); put("storage", false); put("llm", false); put("searchClick", false)
            capabilityRouter.availableCapabilities.forEach { put(it, true) }
            extraCapabilities.forEach { (k, v) -> put(k, v) }
        }
        send("handshake:ack") { put("capabilities", caps); put("hostOrigin", HOST_ORIGIN) }
        _isConnected.value = true
        if (registered.isNotEmpty()) send("mcp:tools") { put("tools", toolDefinitions) }
    }

    private fun capabilityPing(message: JsonObject) {
        send("capability:pong") {
            put("id", message.str("id") ?: newId())
            put("success", true)
            put("result", JsonArray((capabilityRouter.availableCapabilities + "mcp").map { JsonPrimitive(it) }))
            put("uiFeatures", JsonArray(emptyList()))
        }
        // A ping proves the page is alive, as a handshake does.
        _isConnected.value = true
    }

    private fun invoke(message: JsonObject) {
        val requestId = message.str("requestId") ?: newId()
        val name = message.str("toolName").orEmpty()
        val args = message["args"] as? JsonObject ?: JsonObject(emptyMap())
        val tool = tool(name) ?: return send("mcp:error", requestId) { put("error", "Tool not found: $name") }
        scope.launch {
            try {
                val result = tool.execute(args)
                send("mcp:result", requestId) { put("result", result) }
            } catch (e: kotlinx.coroutines.CancellationException) {
                throw e
            } catch (e: Throwable) {
                send("mcp:error", requestId) { put("error", e.message ?: e.toString()) }
            }
        }
    }

    private fun capability(message: JsonObject) {
