/**
 * A native API the web agent can call (twin of iOS `NativeTool`, NativeTool.swift).
 *
 * Naming, as on iOS: `pick_*` presents native UI and waits for a choice (return `name` or `value`
 * for the confirmation card), `get_*`/`list_*` read, `create_*`/`setup_*`/`delete_*` write.
 */
interface NativeTool {
    /** snake_case; the prefix drives the agent's behaviour (above). */
    val name: String
    val description: String
    /** JSON Schema of the input, built with [ToolSchema.obj]. */
    val inputSchema: JsonObject
    /** The fields the tool returns, shown to the agent as "Returns:" so it can chain `$ref` paths. */
    val outputSchema: JsonObject? get() = null
    /** Seconds before the web gives up; 0 waits indefinitely. */
    val timeoutSeconds: Double get() = 30.0

    /** Runs the tool. Throw [ToolError] (or any exception) to answer the agent with its message. */
    suspend fun execute(args: JsonObject): JsonElement

    /** The MCP definition sent to the web agent (`mcp:tools`); `timeout` in milliseconds for JS. */
    val definition: JsonObject get() = buildJsonObject {
        put("name", name)
        put("description", description)
        put("inputSchema", inputSchema)
        outputSchema?.let { put("outputSchema", it) }
        put("timeout", (timeoutSeconds * 1000).toLong())
    }

    // Argument helpers, as iOS's.

    /** A required string; throws [ToolError.InvalidArgs] when missing or not a string. */
    fun string(key: String, args: JsonObject): String =
        optionalString(key, args) ?: throw ToolError.InvalidArgs("Missing required string parameter '$key'")

