    private fun capability(message: JsonObject) {
        val id = message.str("id") ?: newId()
        val cap = message.str("capability").orEmpty()
        val method = message.str("method").orEmpty()
        val args = (message["args"] as? JsonArray)?.toList() ?: emptyList()
        scope.launch {
            try {
                val result = capabilityRouter.invoke(cap, method, args)
                send("capability:response") { put("id", id); put("success", true); put("result", result) }
            } catch (e: kotlinx.coroutines.CancellationException) {
                throw e
            } catch (e: Throwable) {
                send("capability:response") {
                    put("id", id); put("success", false); put("error", e.message ?: e.toString())
                    put("errorCode", (e as? CapabilityError)?.errorCode ?: "EXECUTION_FAILED")
                }
            }
        }
    }

    private fun openLink(url: String) {
        if (onOpenLink?.invoke(url) == true) return
        val scheme = runCatching { java.net.URI(url).scheme?.lowercase() }.getOrNull()
        if (scheme in EXTERNAL_SCHEMES) openExternally?.invoke(url)
    }

    private fun broadcastToolsIfConnected() {
        if (_isConnected.value) send("mcp:tools") { put("tools", toolDefinitions) }
    }

    // MARK: - Native → web

    /** Sends `agent-framework:<kind>` with the protocol's envelope (version, timestamp, requestId). */
    fun send(kind: String, requestId: String? = null, body: kotlinx.serialization.json.JsonObjectBuilder.() -> Unit = {}) {
        send(buildJsonObject {
            put("type", PREFIX + kind)
            put("version", PROTOCOL_VERSION)
            put("timestamp", System.currentTimeMillis())
            requestId?.let { put("requestId", it) }
            body()
        })
    }

    /** Sends a whole message object to the page. */
    fun send(message: JsonObject) {
        evaluate?.invoke(receiveScript(message))
    }

    companion object {
        const val PREFIX = "agent-framework:"
        const val PROTOCOL_VERSION = "1.0.0"
        const val HOST_ORIGIN = "ripul-native://app"
        const val HOST_TITLE = "Ripul Native App (Android)"
        private val EXTERNAL_SCHEMES = setOf("http", "https", "mailto", "tel")

        /** The JavaScript that hands [message] to the page. JSON is a JS literal once U+2028/9 are escaped. */
        fun receiveScript(message: JsonObject): String =
            "window.__agentBridgeReceive && window.__agentBridgeReceive(" +
                message.toString().replace("\u2028", "\\u2028").replace("\u2029", "\\u2029") + ")"

        private fun newId() = UUID.randomUUID().toString()
        private fun JsonObject.str(key: String): String? = (this[key] as? JsonPrimitive)?.takeIf { it.isString }?.contentOrNull
    }
}

/** A tool result from a plain map (strings, numbers, booleans, lists, maps, null). */
fun jsonOf(value: Any?): JsonElement = when (value) {
    null -> kotlinx.serialization.json.JsonNull
    is JsonElement -> value
    is String -> JsonPrimitive(value)
    is Number -> JsonPrimitive(value)
    is Boolean -> JsonPrimitive(value)
    is Map<*, *> -> JsonObject(value.entries.associate { (k, v) -> k.toString() to jsonOf(v) })
    is Iterable<*> -> JsonArray(value.map { jsonOf(it) })
    is Array<*> -> JsonArray(value.map { jsonOf(it) })
    else -> JsonPrimitive(value.toString())
}

