/** The `agent-framework:*` protocol as the web app's NativeBridge and FrameMCPBridge speak it. */
@OptIn(ExperimentalCoroutinesApi::class)
class AgentBridgeTest {
    private class Page(scope: TestScope) {
        val bridge = AgentBridge(scope)
        val sent = mutableListOf<JsonObject>()
        init {
            bridge.evaluate = { js ->
                val json = js.substringAfter("__agentBridgeReceive(").removeSuffix(")")
                sent += Json.parseToJsonElement(json).jsonObject
            }
        }
        fun post(json: String) = bridge.handleMessage(json)
        fun last(type: String) = sent.last { it["type"]!!.jsonPrimitive.content == "agent-framework:$type" }
    }

    private val echo = object : NativeTool {
        override val name = "get_echo"
        override val description = "Echoes its text"
        override val inputSchema = ToolSchema.obj(ToolSchema.Property.string("text", "What to echo", required = true))
        override suspend fun execute(args: JsonObject): JsonElement = jsonOf(mapOf("echo" to string("text", args), "n" to 2))
    }

    @Test fun handshakeAcksAndSendsTools() = runTest {
        val page = Page(this)
        page.bridge.register(echo)
        assertTrue(page.sent.isEmpty()) // Not connected: nothing is broadcast.
        page.post("""{"type":"agent-framework:handshake","version":"1.0.0","timestamp":1,"capabilities":{"mcp":true}}""")
        val ack = page.last("handshake:ack")
        assertEquals("ripul-native://app", ack["hostOrigin"]!!.jsonPrimitive.content)
        assertEquals(true, ack["capabilities"]!!.jsonObject["mcp"]!!.jsonPrimitive.content.toBoolean())
        val tool = page.last("mcp:tools")["tools"]!!.jsonArray.single().jsonObject
        assertEquals("get_echo", tool["name"]!!.jsonPrimitive.content)
        assertEquals(30000L, tool["timeout"]!!.jsonPrimitive.content.toLong())
        assertEquals(listOf("text"), tool["inputSchema"]!!.jsonObject["required"]!!.jsonArray.map { it.jsonPrimitive.content })
        assertTrue(page.bridge.isConnected.value)
    }

